  ('f1e32b93-0efa-5ee0-9968-f53f43ea7839', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-5-kohaesion-adhaesion-kapillaritaet/fachpraktisches-arbeiten-kapillaritaet-3', '57819edc-85d2-5c6a-adff-9579ea67ae54', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 3, 'Fachpraktisches Arbeiten (Kapillarität)', 'Practical work (capillarity)', 'Lernende untersuchen im Versuch, wie hoch Flüssigkeit in Kapillarröhrchen steigt und welche Rolle der Durchmesser spielt.', 'In an experiment pupils investigate how high a liquid rises in capillary tubes and what role the tube diameter plays.', NULL, NULL, '{"goals_in_evomentor": 1, "match": ["5/6", "2.2.5 Kohäsion, Adhäsion, Kapillarität", "Fachpraktisches Arbeiten (Kapillarität)"]}', 'evomentor-goals-2026-11-02'),
  ('88bcd9b9-2051-5cd6-9fca-2266474cffb1', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-6-die-vielfalt-der-lebewesen', 'b4a47e21-cba0-578a-8a84-90fe8fc79b91', 'topic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 5, '2.2.6 Die Vielfalt der Lebewesen', '2.2.6 The diversity of living things', 'Lernende sortieren Lebewesen in vorgegebene Gruppen und unterscheiden sie von nichtlebenden Dingen.', 'Pupils sort living things into given groups and tell them apart from non-living things.', NULL, NULL, '{"goals_in_evomentor": 2, "match": ["5/6", "2.2.6 Die Vielfalt der Lebewesen"]}', 'evomentor-goals-2026-11-02'),
  ('6bfcf81c-b147-5149-852a-2608e4e1974a', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-6-die-vielfalt-der-lebewesen/ohne-titel-0', '88bcd9b9-2051-5cd6-9fca-2266474cffb1', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 0, '2.2.6 Die Vielfalt der Lebewesen', '2.2.6 The diversity of living things', 'Lernende sortieren Lebewesen in vorgegebene Gruppen und grenzen sie von nichtlebenden Dingen ab.', 'Pupils sort living things into given groups and set them apart from non-living things.', NULL, NULL, '{"goals_in_evomentor": 2, "match": ["5/6", "2.2.6 Die Vielfalt der Lebewesen", ""]}', 'evomentor-goals-2026-11-02'),
  ('73c3efd7-f0e2-51d6-9e96-2db341123dbc', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-7-samenpflanzen', 'b4a47e21-cba0-578a-8a84-90fe8fc79b91', 'topic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 6, '2.2.7 Samenpflanzen', '2.2.7 Seed plants', 'Lernende untersuchen Bau, Ernährung, Fortpflanzung und Ordnung der Samenpflanzen sowie ihre Bedeutung für den Menschen.', 'Pupils study the structure, nutrition, reproduction and classification of seed plants and their importance for people.', NULL, NULL, '{"goals_in_evomentor": 33, "match": ["5/6", "2.2.7 Samenpflanzen"]}', 'evomentor-goals-2026-11-02'),
  ('d3a778a4-d7ac-51bf-9392-df06c89d3fdb', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-7-samenpflanzen/vielfalt-gleicher-grundaufbau-0', '73c3efd7-f0e2-51d6-9e96-2db341123dbc', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 0, 'Vielfalt – gleicher Grundaufbau', 'Diversity with the same basic structure', 'Lernende beschreiben den Bau einer Samenpflanze, vergleichen Samenpflanzen und ordnen sie nach ihrer Wuchsform.', 'Pupils describe how a seed plant is built, compare seed plants and sort them by growth form.', NULL, NULL, '{"goals_in_evomentor": 3, "match": ["5/6", "2.2.7 Samenpflanzen", "Vielfalt – gleicher Grundaufbau"]}', 'evomentor-goals-2026-11-02'),
  ('eaf5969a-0002-56e0-828f-017d9bae2bbb', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-7-samenpflanzen/fachpraktische-arbeiten-aufbau-samenpflanzen-1', '73c3efd7-f0e2-51d6-9e96-2db341123dbc', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 1, 'Fachpraktische Arbeiten (Aufbau Samenpflanzen)', 'Practical work (structure of seed plants)', 'Lernende schauen sich in einer praktischen Arbeit an, wie Samenpflanzen gestaltet sind.', 'In a practical task pupils look at how seed plants are shaped.', NULL, NULL, '{"goals_in_evomentor": 1, "match": ["5/6", "2.2.7 Samenpflanzen", "Fachpraktische Arbeiten (Aufbau Samenpflanzen)"]}', 'evomentor-goals-2026-11-02'),
  ('a391e4e1-4f96-5da4-a072-be88bab9c407', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-7-samenpflanzen/ernaehrung-der-samenpflanzen-2', '73c3efd7-f0e2-51d6-9e96-2db341123dbc', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 2, 'Ernährung der Samenpflanzen', 'Nutrition of seed plants', 'Lernende verfolgen, wie Wasser über Wurzel und Sprossachse transportiert wird und wie Laubblätter Kohlenstoffdioxid aufnehmen und zu Traubenzucker und Sauerstoff umwandeln.', 'Pupils follow how water moves through root and stem and how leaves take in carbon dioxide and turn it into glucose and oxygen.', NULL, NULL, '{"goals_in_evomentor": 7, "match": ["5/6", "2.2.7 Samenpflanzen", "Ernährung der Samenpflanzen"]}', 'evomentor-goals-2026-11-02'),
  ('41d58af1-d50c-56a6-9cc6-cb190bc73fd7', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-7-samenpflanzen/fachpraktische-arbeiten-ernaehrung-samenpflanzen-3', '73c3efd7-f0e2-51d6-9e96-2db341123dbc', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 3, 'Fachpraktische Arbeiten (Ernährung Samenpflanzen)', 'Practical work (nutrition of seed plants)', 'Lernende untersuchen in Versuchen den Querschnitt der Sprossachse, das Aufsteigen gefärbten Wassers, die Wasserabgabe der Blätter und die Wasseraufnahme der Wurzeln.', 'In experiments pupils examine the cross-section of the stem, watch coloured water rise, and study water loss through leaves and water uptake by roots.', NULL, NULL, '{"goals_in_evomentor": 5, "match": ["5/6", "2.2.7 Samenpflanzen", "Fachpraktische Arbeiten (Ernährung Samenpflanzen)"]}', 'evomentor-goals-2026-11-02'),
  ('36887897-f13b-5b35-ad95-23ffaaf70dd1', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-7-samenpflanzen/fortpflanzung-und-entwicklung-der-samenpflanzen-4', '73c3efd7-f0e2-51d6-9e96-2db341123dbc', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 4, 'Fortpflanzung und Entwicklung der Samenpflanzen', 'Reproduction and development of seed plants', 'Lernende beschreiben und vergleichen Blüten, erklären Bestäubung, Befruchtung und Fruchtbildung und beschreiben den Bau eines Samens.', 'Pupils describe and compare flowers, explain pollination, fertilisation and fruit formation, and describe how a seed is built.', NULL, NULL, '{"goals_in_evomentor": 8, "match": ["5/6", "2.2.7 Samenpflanzen", "Fortpflanzung und Entwicklung der Samenpflanzen"]}', 'evomentor-goals-2026-11-02'),
  ('aa2877be-15ea-5a36-8834-7a63042b3b11', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-7-samenpflanzen/fachpraktische-arbeiten-fortpflanzung-entwicklun-5', '73c3efd7-f0e2-51d6-9e96-2db341123dbc', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 5, 'Fachpraktische Arbeiten (Fortpflanzung, Entwicklung Samenpflanzen)', 'Practical work (reproduction and development of seed plants)', 'Lernende zerlegen Blüten und zeichnen ein Blütendiagramm, weisen Stärke und Fett in Samen nach, untersuchen Keimungsbedingungen und ziehen Jungpflanzen heran.', 'Pupils take flowers apart and draw a floral diagram, test seeds for starch and fat, investigate conditions for germination and grow young plants.', NULL, NULL, '{"goals_in_evomentor": 4, "match": ["5/6", "2.2.7 Samenpflanzen", "Fachpraktische Arbeiten (Fortpflanzung, Entwicklung Samenpflanzen)"]}', 'evomentor-goals-2026-11-02'),
  ('9ee67ef1-13af-56d0-93b4-9f974336432f', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-7-samenpflanzen/ordnen-von-samenpflanzen-6', '73c3efd7-f0e2-51d6-9e96-2db341123dbc', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 6, 'Ordnen von Samenpflanzen', 'Classifying seed plants', 'Lernende vergleichen Vertreter einer Pflanzenfamilie, grenzen die Familie ab und erläutern, nach welchen Kriterien man Samenpflanzen einteilt.', 'Pupils compare members of a plant family, set the family apart and explain the criteria used to divide seed plants into groups.', NULL, NULL, '{"goals_in_evomentor": 3, "match": ["5/6", "2.2.7 Samenpflanzen", "Ordnen von Samenpflanzen"]}', 'evomentor-goals-2026-11-02'),
  ('cc74106e-6dde-5c2a-8471-1ca3d10b2987', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-7-samenpflanzen/bedeutung-von-samenpflanzen-und-nutzung-durch-de-7', '73c3efd7-f0e2-51d6-9e96-2db341123dbc', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 7, 'Bedeutung von Samenpflanzen und Nutzung durch den Menschen', 'Importance and human use of seed plants', 'Lernende überlegen, welche Rolle wild wachsende Samenpflanzen für die Natur spielen und wie Menschen sie nutzen.', 'Pupils consider what role wild seed plants play in nature and how people use seed plants.', NULL, NULL, '{"goals_in_evomentor": 2, "match": ["5/6", "2.2.7 Samenpflanzen", "Bedeutung von Samenpflanzen und Nutzung durch den Menschen"]}', 'evomentor-goals-2026-11-02'),
  ('fee2bc8e-f8da-5355-995e-a8401fb62e63', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-8-wirbeltiere', 'b4a47e21-cba0-578a-8a84-90fe8fc79b91', 'topic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 7, '2.2.8 Wirbeltiere', '2.2.8 Vertebrates', 'Lernende lernen die Wirbeltierklassen kennen, vergleichen Körperbau und Lebensweise der Tiergruppen, stellen die Klassen einander gegenüber und befassen sich mit dem Schutz von Wirbeltieren.', 'Pupils get to know the vertebrate classes, compare body structure and way of life of the animal groups, set the classes side by side and look at the protection of vertebrates.', NULL, NULL, '{"goals_in_evomentor": 34, "match": ["5/6", "2.2.8 Wirbeltiere"]}', 'evomentor-goals-2026-11-02'),
  ('baf07638-c77d-5a17-90ad-ab7e0efea2ce', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-8-wirbeltiere/die-vielfalt-der-wirbeltiere-und-ihre-einteilung-0', 'fee2bc8e-f8da-5355-995e-a8401fb62e63', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 0, 'Die Vielfalt der Wirbeltiere und ihre Einteilung in Wirbeltierklassen', 'Diversity of vertebrates and their classes', 'Lernende ordnen Wirbeltierarten den passenden Klassen zu.', 'Pupils assign vertebrate species to the matching classes.', NULL, NULL, '{"goals_in_evomentor": 1, "match": ["5/6", "2.2.8 Wirbeltiere", "Die Vielfalt der Wirbeltiere und ihre Einteilung in Wirbeltierklassen"]}', 'evomentor-goals-2026-11-02'),
  ('bd410469-9b5d-515b-831a-7286884649a1', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-8-wirbeltiere/koerpergliederung-und-koerperbau-1', 'fee2bc8e-f8da-5355-995e-a8401fb62e63', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 1, 'Körpergliederung und Körperbau', 'Body organisation and body structure', 'Lernende vergleichen Körpergliederung und Skelett von Wirbeltieren und definieren den Begriff Wirbeltier.', 'Pupils compare body organisation and skeleton of vertebrates and define the term vertebrate.', NULL, NULL, '{"goals_in_evomentor": 2, "match": ["5/6", "2.2.8 Wirbeltiere", "Körpergliederung und Körperbau"]}', 'evomentor-goals-2026-11-02'),
  ('f20c52a4-914b-5c57-9ba8-e2e64ea43713', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-8-wirbeltiere/fachpraktische-arbeiten-koerperbau-2', 'fee2bc8e-f8da-5355-995e-a8401fb62e63', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 2, 'Fachpraktische Arbeiten (Körperbau)', 'Practical work (body structure)', 'Lernende stellen ein Modell des Beins von Wirbeltieren her.', 'Pupils build a model of a vertebrate leg.', NULL, NULL, '{"goals_in_evomentor": 1, "match": ["5/6", "2.2.8 Wirbeltiere", "Fachpraktische Arbeiten (Körperbau)"]}', 'evomentor-goals-2026-11-02'),
  ('06294987-004e-5efa-b06f-c02874cdb2d7', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-8-wirbeltiere/angepasstheit-an-lebensweise-und-lebensraeume-sa-3', 'fee2bc8e-f8da-5355-995e-a8401fb62e63', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 3, 'Angepasstheit an Lebensweise und Lebensräume (Säugetiere)', 'Adaptation to way of life and habitat (mammals)', 'Lernende erläutern am Beispiel der Säugetiere, wie Gliedmaßen, Fortbewegung, Ernährung, Atmung und Stofftransport zur Lebensweise passen.', 'Using mammals as the example, pupils explain how limbs, movement, feeding, breathing and transport of substances suit the animal''s way of life.', NULL, NULL, '{"goals_in_evomentor": 8, "match": ["5/6", "2.2.8 Wirbeltiere", "Angepasstheit an Lebensweise und Lebensräume (Säugetiere)"]}', 'evomentor-goals-2026-11-02'),
  ('88970996-3123-57e4-85a7-5663f5f06cce', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-8-wirbeltiere/fachpraktische-arbeiten-ernaehrung-atmung-4', 'fee2bc8e-f8da-5355-995e-a8401fb62e63', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 4, 'Fachpraktische Arbeiten (Ernährung, Atmung)', 'Practical work (nutrition, breathing)', 'Lernende prüfen, wie gut sich Stärke und Traubenzucker lösen, stellen Blutkreislauf oder Lunge in einem Modell dar und zeigen das Prinzip der Oberflächenvergrößerung.', 'Pupils test how well starch and glucose dissolve, show the blood circulation or a lung in a model and demonstrate the principle of enlarging a surface.', NULL, NULL, '{"goals_in_evomentor": 3, "match": ["5/6", "2.2.8 Wirbeltiere", "Fachpraktische Arbeiten (Ernährung, Atmung)"]}', 'evomentor-goals-2026-11-02'),
  ('8022532e-3732-58b4-b83d-07fe3eb12ca2', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-8-wirbeltiere/angepasstheit-an-lebensweise-und-lebensraeume-fi-5', 'fee2bc8e-f8da-5355-995e-a8401fb62e63', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 5, 'Angepasstheit an Lebensweise und Lebensräume (Fische)', 'Adaptation to way of life and habitat (fish)', 'Lernende erläutern am Beispiel der Fische, wie Fortbewegung und Atmung im Wasser funktionieren.', 'Using fish as the example, pupils explain how movement and breathing work in water.', NULL, NULL, '{"goals_in_evomentor": 2, "match": ["5/6", "2.2.8 Wirbeltiere", "Angepasstheit an Lebensweise und Lebensräume (Fische)"]}', 'evomentor-goals-2026-11-02'),
  ('73d2ca2c-95db-55d8-8448-70770de3ce80', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-8-wirbeltiere/angepasstheit-an-lebensweise-und-lebensraeume-lu-6', 'fee2bc8e-f8da-5355-995e-a8401fb62e63', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 6, 'Angepasstheit an Lebensweise und Lebensräume (Lurche)', 'Adaptation to way of life and habitat (amphibians)', 'Lernende erläutern am Beispiel der Lurche die äußere Befruchtung und wie sich aus dem Laich eine Larve entwickelt.', 'Using amphibians as the example, pupils explain external fertilisation and how a larva develops from the spawn.', NULL, NULL, '{"goals_in_evomentor": 2, "match": ["5/6", "2.2.8 Wirbeltiere", "Angepasstheit an Lebensweise und Lebensräume (Lurche)"]}', 'evomentor-goals-2026-11-02'),
  ('5abd631b-94a3-53b8-bdab-e14093aea69f', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-8-wirbeltiere/angepasstheit-an-lebensweise-und-lebensraeume-kr-7', 'fee2bc8e-f8da-5355-995e-a8401fb62e63', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 7, 'Angepasstheit an Lebensweise und Lebensräume (Kriechtiere)', 'Adaptation to way of life and habitat (reptiles)', 'Lernende erläutern am Beispiel der Kriechtiere, wie sich die Ringelnatter an Land fortbewegt und wie Hornschuppen den Körper bedecken.', 'Using reptiles as the example, pupils explain how the grass snake moves on land and how horny scales cover the body.', NULL, NULL, '{"goals_in_evomentor": 2, "match": ["5/6", "2.2.8 Wirbeltiere", "Angepasstheit an Lebensweise und Lebensräume (Kriechtiere)"]}', 'evomentor-goals-2026-11-02'),
  ('c9a2f7c3-c6a3-55ea-ab74-636dfe12fd30', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-8-wirbeltiere/angepasstheit-an-lebensweise-und-lebensraeume-vo-8', 'fee2bc8e-f8da-5355-995e-a8401fb62e63', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 8, 'Angepasstheit an Lebensweise und Lebensräume (Vögel)', 'Adaptation to way of life and habitat (birds)', 'Lernende erläutern am Beispiel der Vögel, wie sie fliegen und wie sie schwimmen.', 'Using birds as the example, pupils explain how they fly and how they swim.', NULL, NULL, '{"goals_in_evomentor": 2, "match": ["5/6", "2.2.8 Wirbeltiere", "Angepasstheit an Lebensweise und Lebensräume (Vögel)"]}', 'evomentor-goals-2026-11-02'),
  ('ab473749-f7b2-5908-b7ec-f915ef1ad98f', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-8-wirbeltiere/fachpraktische-arbeiten-angepasstheit-9', 'fee2bc8e-f8da-5355-995e-a8401fb62e63', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 9, 'Fachpraktische Arbeiten (Angepasstheit)', 'Practical work (adaptation)', 'Lernende untersuchen Körpermodelle in der Strömung, die Funktion von Flossen und den Aufbau von Federn samt ihren Eigenschaften.', 'Pupils investigate body models in a current of water, how fins work, and how feathers are built and what properties they have.', NULL, NULL, '{"goals_in_evomentor": 3, "match": ["5/6", "2.2.8 Wirbeltiere", "Fachpraktische Arbeiten (Angepasstheit)"]}', 'evomentor-goals-2026-11-02'),
  ('9dedcbd9-935f-59a6-b749-17da4181fe09', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-8-wirbeltiere/gegenueberstellung-und-ordnen-der-wirbeltierklas-10', 'fee2bc8e-f8da-5355-995e-a8401fb62e63', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 10, 'Gegenüberstellung und Ordnen der Wirbeltierklassen', 'Comparing and ordering the vertebrate classes', 'Lernende stellen die fünf Wirbeltierklassen nach Skelett, Atmung, Körperbedeckung und Körpertemperatur einander gegenüber.', 'Pupils set the five vertebrate classes side by side in terms of skeleton, breathing, body covering and body temperature.', NULL, NULL, '{"goals_in_evomentor": 6, "match": ["5/6", "2.2.8 Wirbeltiere", "Gegenüberstellung und Ordnen der Wirbeltierklassen"]}', 'evomentor-goals-2026-11-02'),
  ('97b92a39-9d6a-5eac-b6ec-cad9c8e4eaa5', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-8-wirbeltiere/schutz-von-wirbeltieren-11', 'fee2bc8e-f8da-5355-995e-a8401fb62e63', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 11, 'Schutz von Wirbeltieren', 'Protection of vertebrates', 'Lernende leiten Auswirkungen auf Lebensräume ab und begründen und bewerten Maßnahmen, die Lebensräume schützen.', 'Pupils work out effects on habitats and give reasons for and evaluate measures that protect habitats.', NULL, NULL, '{"goals_in_evomentor": 2, "match": ["5/6", "2.2.8 Wirbeltiere", "Schutz von Wirbeltieren"]}', 'evomentor-goals-2026-11-02'),
