  ('2fd8d580-bed3-59db-a89d-b53eaea6ca0d', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-9-der-mensch-gesunderhaltung/fachpraktische-arbeiten-bewegung-koerperhaltung-1', '43c1c8e9-878f-5ee0-ae8b-73011303e542', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 1, 'Fachpraktische Arbeiten (Bewegung/Körperhaltung)', 'Practical work (movement and posture)', 'Lernende gestalten ein Skelettmodell und untersuchen, wie ein Gelenk und die Hand funktionieren.', 'Pupils make a skeleton model and investigate how a joint and the hand work.', NULL, NULL, '{"goals_in_evomentor": 3, "match": ["5/6", "2.2.9 Der Mensch – Gesunderhaltung", "Fachpraktische Arbeiten (Bewegung/Körperhaltung)"]}', 'evomentor-goals-2026-11-02'),
  ('84b659cc-d795-5207-bf79-afe29c1c9100', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-9-der-mensch-gesunderhaltung/ernaehrung-2', '43c1c8e9-878f-5ee0-ae8b-73011303e542', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 2, 'Ernährung', 'Nutrition', 'Lernende nennen Nahrungsbestandteile und ihre Bedeutung und verfolgen den Weg der Nährstoffe von der Aufnahme über die Verdauung bis zum Transport im Blut.', 'Pupils name food components and their importance and follow nutrients from intake through digestion to transport in the blood.', NULL, NULL, '{"goals_in_evomentor": 8, "match": ["5/6", "2.2.9 Der Mensch – Gesunderhaltung", "Ernährung"]}', 'evomentor-goals-2026-11-02'),
  ('b8ff4957-ac10-5c9b-86c0-595e1c39dc96', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-9-der-mensch-gesunderhaltung/fachpraktische-arbeiten-ernaehrung-3', '43c1c8e9-878f-5ee0-ae8b-73011303e542', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 3, 'Fachpraktische Arbeiten (Ernährung)', 'Practical work (nutrition)', 'Lernende weisen in Lebensmitteln Stärke und Fett nach und erläutern ein Modell zur Verdauung von Stärke.', 'Pupils test foods for starch and fat and explain a model of how starch is digested.', NULL, NULL, '{"goals_in_evomentor": 2, "match": ["5/6", "2.2.9 Der Mensch – Gesunderhaltung", "Fachpraktische Arbeiten (Ernährung)"]}', 'evomentor-goals-2026-11-02'),
  ('3db8507d-9b18-564c-99c5-8f8548ec9eab', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-9-der-mensch-gesunderhaltung/sexualitaet-und-fortpflanzung-4', '43c1c8e9-878f-5ee0-ae8b-73011303e542', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 4, 'Sexualität und Fortpflanzung', 'Sexuality and reproduction', 'Lernende nennen Bau und Aufgaben der Geschlechtsorgane und besprechen die Veränderungen in der Pubertät, auch zu Menstruation, Pollution und sexueller Orientierung.', 'Pupils name the structure and tasks of the sex organs and discuss the changes of puberty, including menstruation, nocturnal emissions and sexual orientation.', NULL, NULL, '{"goals_in_evomentor": 7, "match": ["5/6", "2.2.9 Der Mensch – Gesunderhaltung", "Sexualität und Fortpflanzung"]}', 'evomentor-goals-2026-11-02'),
  ('619f29ff-29fa-5373-be72-385bbb07a41e', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-10-bionik-vom-entdecken-zum-erfinden', 'b4a47e21-cba0-578a-8a84-90fe8fc79b91', 'topic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 9, '2.2.10 Bionik - vom Entdecken zum Erfinden', '2.2.10 Bionics: from discovering to inventing', 'An vier Beispielen untersuchen Lernende Vorbilder in der Natur, bauen Funktionsmodelle und übertragen die Erkenntnisse auf technische Anwendungen.', 'Using four examples, pupils study models from nature, build working models and carry the findings over to technical applications.', NULL, NULL, '{"goals_in_evomentor": 22, "match": ["5/6", "2.2.10 Bionik - vom Entdecken zum Erfinden"]}', 'evomentor-goals-2026-11-02'),
