  ('8fb7c6da-effc-5f43-9120-ce13d3465a77', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-10-bionik-vom-entdecken-zum-erfinden/10-3-vom-nebeltrinkerkaefer-zur-trinkwassergewin-4', '619f29ff-29fa-5373-be72-385bbb07a41e', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 4, '10.3 Vom Nebeltrinkerkäfer zur Trinkwassergewinnung', '10.3 From the fog-drinking beetle to drinking water', 'Lernende untersuchen, wie der Nebeltrinkerkäfer Wasser gewinnt, entwickeln Funktionsmodelle und übertragen das Prinzip auf Nebelkollektoren.', 'Pupils study how the fog-drinking beetle collects water, build working models and apply the principle to fog collectors.', NULL, NULL, '{"goals_in_evomentor": 4, "match": ["5/6", "2.2.10 Bionik - vom Entdecken zum Erfinden", "10.3 Vom Nebeltrinkerkäfer zur Trinkwassergewinnung"]}', 'evomentor-goals-2026-11-02'),
