  ('8fe4d21d-ec6e-54df-afc5-5314725f1d7a', 'thuringia-curriculum-repository', 'DE-TH/mnt-gymnasium-2026/5-6/2-2-10-bionik-vom-entdecken-zum-erfinden/10-4-der-lotuseffekt-6', '619f29ff-29fa-5373-be72-385bbb07a41e', 'subtopic', 'mnt', 'Gymnasium', '5/6', NULL, NULL, 6, '10.4 Der Lotuseffekt', '10.4 The lotus effect', 'Lernende untersuchen Laubblätter mit ihren Wachsnoppen als Vorbild, entwickeln ein Funktionsmodell und übertragen das Prinzip auf Autolacke und Textilien.', 'Pupils study leaves with their wax bumps as a model from nature, build a working model and apply the principle to car paints and textiles.', NULL, NULL, '{"goals_in_evomentor": 4, "match": ["5/6", "2.2.10 Bionik - vom Entdecken zum Erfinden", "10.4 Der Lotuseffekt"]}', 'evomentor-goals-2026-11-02'),
