  ('4efa168b-e346-5782-8e4e-ceae7f9b6404', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/wirbellose-in-ihren-lebensraeumen/insekten-1', '51019147-1bce-5ca0-8234-a72f77ae1e73', 'subtopic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 1, 'Insekten', 'Insects', 'Lernende beschreiben Körpergliederung, Chitin-Außenskelett, Tracheensystem und Nervensystem der Insekten.', 'Pupils describe the body segmentation, chitin outer skeleton, tracheal system and nervous system of insects.', 'p. 19, 20', NULL, '{"goals_in_evomentor": 9, "match": ["7/8", "Wirbellose in ihren Lebensräumen", "Insekten"]}', 'evomentor-goals-2026-11-02'),
