  ('8afe6da3-ff19-50a4-b22c-961b08664dd5', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/zellen-als-lebensbausteine', '30cb399f-aa46-5293-ac43-1c2dddaf10ed', 'topic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 1, 'Zellen als Lebensbausteine', 'Cells as building blocks of life', 'Lernende untersuchen, wie Zellen aufgebaut sind, vergleichen pflanzliche und tierische Zellen, lernen Bakterien kennen und üben das Mikroskopieren.', 'Pupils study how cells are built, compare plant and animal cells, get to know bacteria and practise microscopy.', NULL, NULL, '{"goals_in_evomentor": 14, "match": ["7/8", "Zellen als Lebensbausteine"]}', 'evomentor-goals-2026-11-02'),
  ('b86c5867-e037-5f19-bbf4-19ccb0619e52', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/zellen-als-lebensbausteine/pflanzliche-und-tierische-zellen-0', '8afe6da3-ff19-50a4-b22c-961b08664dd5', 'subtopic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 0, 'Pflanzliche und tierische Zellen', 'Plant and animal cells', 'Lernende nennen Merkmale des Lebens, beschreiben Zellaufbau und Aufgaben der Organellen, vergleichen Pflanzen- und Tierzellen und verknüpfen Zellbau mit der Ernährungsweise.', 'Pupils name characteristics of life, describe cell structure and the tasks of organelles, compare plant and animal cells and link cell structure to the way of feeding.', 'p. 20, 21', NULL, '{"goals_in_evomentor": 7, "match": ["7/8", "Zellen als Lebensbausteine", "Pflanzliche und tierische Zellen"]}', 'evomentor-goals-2026-11-02'),
  ('d45f8a51-b09a-5880-89b6-5240b3878b94', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/zellen-als-lebensbausteine/bakterien-1', '8afe6da3-ff19-50a4-b22c-961b08664dd5', 'subtopic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 1, 'Bakterien', 'Bacteria', 'Lernende grenzen die Bakterienzelle von anderen Zellen ab und erläutern, welche Bedeutung Bakterien haben.', 'Pupils set the bacterial cell apart from other cells and explain why bacteria matter.', 'p. 21', NULL, '{"goals_in_evomentor": 2, "match": ["7/8", "Zellen als Lebensbausteine", "Bakterien"]}', 'evomentor-goals-2026-11-02'),
  ('9c19d5b9-023d-56dc-a121-a5dc66387c02', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/zellen-als-lebensbausteine/fachpraktisches-arbeiten-2', '8afe6da3-ff19-50a4-b22c-961b08664dd5', 'subtopic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 2, 'Fachpraktisches Arbeiten', 'Practical work', 'Lernende handhaben das Mikroskop sachgerecht, stellen Frischpräparate her, werten mikroskopische Bilder aus und fertigen Zeichnungen an.', 'Pupils handle the microscope correctly, prepare fresh specimens, interpret microscope images and make drawings.', NULL, NULL, '{"goals_in_evomentor": 5, "match": ["7/8", "Zellen als Lebensbausteine", "Fachpraktisches Arbeiten"]}', 'evomentor-goals-2026-11-02'),
  ('5915e621-f528-515c-b801-be2ec0e2f602', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/biologie-des-menschen', '30cb399f-aa46-5293-ac43-1c2dddaf10ed', 'topic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 2, 'Biologie des Menschen', 'Human biology', 'Lernende untersuchen die Organsysteme des Menschen, etwa Nerven, Verdauung, Atmung, Ausscheidung und Kreislauf, sowie Fortpflanzung und Abwehr von Krankheiten.', 'Pupils study the organ systems of humans, such as nerves, digestion, breathing, excretion and circulation, as well as reproduction and defence against disease.', NULL, NULL, '{"goals_in_evomentor": 58, "match": ["7/8", "Biologie des Menschen"]}', 'evomentor-goals-2026-11-02'),
  ('078a90b5-ebe8-5eff-991e-e35b2b8d46cf', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/biologie-des-menschen/fortpflanzung-entwicklung-und-sexualitaet-0', '5915e621-f528-515c-b801-be2ec0e2f602', 'subtopic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 0, 'Fortpflanzung, Entwicklung und Sexualität', 'Reproduction, development and sexuality', 'Lernende beschreiben das Hormonsystem als System der Informationsübertragung, die Pubertät, den Menstruationszyklus und die Entwicklung vor der Geburt.', 'Pupils describe the hormone system as a system for passing on information, puberty, the menstrual cycle and development before birth.', 'p. 22', NULL, '{"goals_in_evomentor": 7, "match": ["7/8", "Biologie des Menschen", "Fortpflanzung, Entwicklung und Sexualität"]}', 'evomentor-goals-2026-11-02'),
  ('1e4b16db-9834-5880-8f11-c13d261ddee1', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/biologie-des-menschen/nervensystem-1', '5915e621-f528-515c-b801-be2ec0e2f602', 'subtopic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 1, 'Nervensystem', 'Nervous system', 'Lernende ordnen Sinneszellen passende Reize zu, erklären Sinnesorgane und befassen sich mit der Reiz-Reaktions-Kette, unter anderem mit Sinneszellen und sensorischen Nerven.', 'Pupils match sensory cells with suitable stimuli, explain sense organs and work on the stimulus-response chain, including sensory cells and sensory nerves.', 'p. 22', NULL, '{"goals_in_evomentor": 12, "match": ["7/8", "Biologie des Menschen", "Nervensystem"]}', 'evomentor-goals-2026-11-02'),
  ('4c9ed327-2332-5e47-93ef-2ac757130697', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/biologie-des-menschen/verdauungssystem-2', '5915e621-f528-515c-b801-be2ec0e2f602', 'subtopic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 2, 'Verdauungssystem', 'Digestive system', 'Lernende erläutern die Zusammensetzung der Nahrung, die enzymatische Verdauung, die Aufnahme der Nährstoffe in den Körper und die Regelung des Blutzuckers.', 'Pupils explain what food is made of, enzymatic digestion, how nutrients are taken up into the body and how blood sugar is regulated.', 'p. 23', NULL, '{"goals_in_evomentor": 8, "match": ["7/8", "Biologie des Menschen", "Verdauungssystem"]}', 'evomentor-goals-2026-11-02'),
  ('097eb300-37e7-56a3-a291-7700a107a383', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/biologie-des-menschen/atmungssystem-3', '5915e621-f528-515c-b801-be2ec0e2f602', 'subtopic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 3, 'Atmungssystem', 'Respiratory system', 'Lernende beschreiben Atmungsorgane, Atembewegungen und den Austausch der Gase in der Lunge und formulieren die Gleichung der Zellatmung.', 'Pupils describe the breathing organs, breathing movements and the exchange of gases in the lung, and write the equation of cell respiration.', 'p. 23', NULL, '{"goals_in_evomentor": 7, "match": ["7/8", "Biologie des Menschen", "Atmungssystem"]}', 'evomentor-goals-2026-11-02'),
  ('c5fc9820-f4cb-5c7b-8494-cc07c4b62daf', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/biologie-des-menschen/ausscheidungssystem-4', '5915e621-f528-515c-b801-be2ec0e2f602', 'subtopic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 4, 'Ausscheidungssystem', 'Excretory system', 'Lernende charakterisieren die Ausscheidungsorgane, beschreiben Bau und Funktion der Niere und die Ableitung des Harns.', 'Pupils characterise the excretory organs and describe how the kidney is built and works and how urine is drained.', 'p. 23', NULL, '{"goals_in_evomentor": 3, "match": ["7/8", "Biologie des Menschen", "Ausscheidungssystem"]}', 'evomentor-goals-2026-11-02'),
  ('40d44479-fa3d-51ce-854b-db082e1c2190', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/biologie-des-menschen/blut-und-herz-kreislauf-system-5', '5915e621-f528-515c-b801-be2ec0e2f602', 'subtopic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 5, 'Blut und Herz-Kreislauf-System', 'Blood and the cardiovascular system', 'Lernende beschreiben Blutkreislauf, Herz und Blut mit seinen Bestandteilen und Aufgaben und erläutern Blutgruppen.', 'Pupils describe the blood circulation, the heart and blood with its components and tasks, and explain blood groups.', 'p. 23', NULL, '{"goals_in_evomentor": 6, "match": ["7/8", "Biologie des Menschen", "Blut und Herz-Kreislauf-System"]}', 'evomentor-goals-2026-11-02'),
  ('4fbf14ec-d3be-5cde-b1e6-e4f4ec52e20f', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/biologie-des-menschen/zusammenwirken-der-systeme-6', '5915e621-f528-515c-b801-be2ec0e2f602', 'subtopic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 6, 'Zusammenwirken der Systeme', 'Interplay of the systems', 'Lernende beschreiben den Menschen als Lebewesen und erläutern, wie die Organsysteme zusammenarbeiten, auch bei Ernährung und Zellatmung.', 'Pupils describe humans as living beings and explain how the organ systems work together, including in nutrition and cell respiration.', 'p. 24', NULL, '{"goals_in_evomentor": 3, "match": ["7/8", "Biologie des Menschen", "Zusammenwirken der Systeme"]}', 'evomentor-goals-2026-11-02'),
  ('c78567b1-1040-5963-a5c6-6e599009da74', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/biologie-des-menschen/abwehrsystem-7', '5915e621-f528-515c-b801-be2ec0e2f602', 'subtopic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 7, 'Abwehrsystem', 'Immune system', 'Lernende kennzeichnen Krankheitserreger und ihre Übertragungswege, erfahren, wo weiße Blutzellen vorkommen, und erläutern die unspezifische Abwehr.', 'Pupils characterise pathogens and how they spread, learn where white blood cells are found and explain the non-specific defence.', 'p. 24', NULL, '{"goals_in_evomentor": 7, "match": ["7/8", "Biologie des Menschen", "Abwehrsystem"]}', 'evomentor-goals-2026-11-02'),
  ('4aeee41d-7457-5a6b-b97f-fd0c58b732a1', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/7-8/biologie-des-menschen/fachpraktisches-arbeiten-8', '5915e621-f528-515c-b801-be2ec0e2f602', 'subtopic', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 8, 'Fachpraktisches Arbeiten', 'Practical work', 'Lernende weisen Glucose, Proteine, Stärkespaltung und Kohlenstoffdioxid in der Ausatemluft nach und zeigen im Modellexperiment die Oberflächenvergrößerung.', 'Pupils test for glucose, proteins, starch breakdown and carbon dioxide in exhaled air, and show surface enlargement in a model experiment.', NULL, NULL, '{"goals_in_evomentor": 5, "match": ["7/8", "Biologie des Menschen", "Fachpraktisches Arbeiten"]}', 'evomentor-goals-2026-11-02'),
  ('93ae7426-f6ce-5aee-8bc1-2fcc4716a718', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9', '851e36fe-3469-57bc-a46f-33bf8494544f', 'grade_band', 'biologie', 'Gymnasium', '9', NULL, NULL, 9, 'Klassenstufe 9', 'Grade 9', NULL, NULL, NULL, NULL, '{}', 'evomentor-goals-2026-11-02'),
  ('f6d84fff-dd5c-565d-af66-59e12414c6d1', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9/stoff-und-energiewechselprozesse-von-pilzen-und', '93ae7426-f6ce-5aee-8bc1-2fcc4716a718', 'topic', 'biologie', 'Gymnasium', '9', NULL, NULL, 0, 'Stoff- und Energiewechselprozesse von Pilzen und grünen Pflanzen', 'Matter and energy exchange in fungi and plants', 'Lernende untersuchen, wie grüne Pflanzen und Pilze Stoffe aufbauen und abbauen und Energie umwandeln, zum Beispiel bei Fotosynthese, Zellatmung und Gärung.', 'Pupils study how green plants and fungi build up and break down substances and convert energy, for example in photosynthesis, cell respiration and fermentation.', NULL, NULL, '{"goals_in_evomentor": 29, "match": ["9", "Stoff- und Energiewechselprozesse von Pilzen und grünen Pflanzen"]}', 'evomentor-goals-2026-11-02'),
  ('50ca4f17-32f8-55d4-a12d-5282b8ebc1e2', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9/stoff-und-energiewechselprozesse-von-pilzen-und/gruene-pflanzen-pflanzenphysiologie-0', 'f6d84fff-dd5c-565d-af66-59e12414c6d1', 'subtopic', 'biologie', 'Gymnasium', '9', NULL, NULL, 0, 'Grüne Pflanzen: Pflanzenphysiologie', 'Green plants: plant physiology', 'Lernende beschreiben die Organe der Sprosspflanze, erklären Wasseraufnahme und Stofftransport und den Bau des Laubblattes.', 'Pupils describe the organs of a shoot plant, explain water uptake and transport of substances, and describe how the leaf is built.', NULL, NULL, '{"goals_in_evomentor": 3, "match": ["9", "Stoff- und Energiewechselprozesse von Pilzen und grünen Pflanzen", "Grüne Pflanzen: Pflanzenphysiologie"]}', 'evomentor-goals-2026-11-02'),
  ('d1ac3ffc-a671-526d-9db2-83d279bd1ac7', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9/stoff-und-energiewechselprozesse-von-pilzen-und/gruene-pflanzen-fotosynthese-1', 'f6d84fff-dd5c-565d-af66-59e12414c6d1', 'subtopic', 'biologie', 'Gymnasium', '9', NULL, NULL, 1, 'Grüne Pflanzen: Fotosynthese', 'Green plants: photosynthesis', 'Lernende erklären, dass die Fotosynthese im Chloroplasten abläuft, wie Energie umgewandelt und Stoff aufgebaut wird, und formulieren Wort- und Summengleichung.', 'Pupils explain that photosynthesis takes place in the chloroplast and how energy is converted and substance is built up, and write the word and summary equations.', NULL, NULL, '{"goals_in_evomentor": 9, "match": ["9", "Stoff- und Energiewechselprozesse von Pilzen und grünen Pflanzen", "Grüne Pflanzen: Fotosynthese"]}', 'evomentor-goals-2026-11-02'),
  ('125735ee-c665-5fb5-8ffd-9540e7145efa', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9/stoff-und-energiewechselprozesse-von-pilzen-und/gruene-pflanzen-zellatmung-2', 'f6d84fff-dd5c-565d-af66-59e12414c6d1', 'subtopic', 'biologie', 'Gymnasium', '9', NULL, NULL, 2, 'Grüne Pflanzen: Zellatmung', 'Green plants: cell respiration', 'Lernende erklären, dass die Zellatmung im Mitochondrium abläuft, wie Energie umgewandelt wird und welche Rolle ATP spielt, formulieren die Gleichung und deuten den Temperatureinfluss.', 'Pupils explain that cell respiration takes place in the mitochondrion, how energy is converted and what role ATP plays, write the equation and interpret the effect of temperature.', NULL, NULL, '{"goals_in_evomentor": 7, "match": ["9", "Stoff- und Energiewechselprozesse von Pilzen und grünen Pflanzen", "Grüne Pflanzen: Zellatmung"]}', 'evomentor-goals-2026-11-02'),
  ('5ce47ebc-6003-5886-a22d-7fe987478458', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9/stoff-und-energiewechselprozesse-von-pilzen-und/pilze-3', 'f6d84fff-dd5c-565d-af66-59e12414c6d1', 'subtopic', 'biologie', 'Gymnasium', '9', NULL, NULL, 3, 'Pilze', 'Fungi', 'Lernende teilen Pilze nach Formen ein, vergleichen Hefezellen mit Tier- und Pflanzenzellen, beschreiben Pilze als heterotrophe Organismen und untersuchen Zellatmung und Gärung bei Bäckerhefe.', 'Pupils sort fungi by form, compare yeast cells with animal and plant cells, describe fungi as heterotrophic organisms and study cell respiration and fermentation in baker''s yeast.', NULL, NULL, '{"goals_in_evomentor": 4, "match": ["9", "Stoff- und Energiewechselprozesse von Pilzen und grünen Pflanzen", "Pilze"]}', 'evomentor-goals-2026-11-02'),
  ('dc950a0a-a30e-535f-99c5-1271cde3edb7', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9/stoff-und-energiewechselprozesse-von-pilzen-und/systematisierung-4', 'f6d84fff-dd5c-565d-af66-59e12414c6d1', 'subtopic', 'biologie', 'Gymnasium', '9', NULL, NULL, 4, 'Systematisierung', 'Systematisation', 'Lernende ordnen Assimilation, Dissimilation, Autotrophie, Heterotrophie, Zellatmung und Gärung ein und erklären, wie Assimilation und Dissimilation zusammenhängen.', 'Pupils classify assimilation, dissimilation, autotrophy, heterotrophy, cell respiration and fermentation and explain how assimilation and dissimilation are connected.', NULL, NULL, '{"goals_in_evomentor": 3, "match": ["9", "Stoff- und Energiewechselprozesse von Pilzen und grünen Pflanzen", "Systematisierung"]}', 'evomentor-goals-2026-11-02'),
  ('fecd8199-4d01-5c41-b8eb-1e518f5747d2', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9/stoff-und-energiewechselprozesse-von-pilzen-und/fachpraktisches-arbeiten-5', 'f6d84fff-dd5c-565d-af66-59e12414c6d1', 'subtopic', 'biologie', 'Gymnasium', '9', NULL, NULL, 5, 'Fachpraktisches Arbeiten', 'Practical work', 'Lernende mikroskopieren einen Laubblattquerschnitt und weisen pflanzliche Inhaltsstoffe sowie Kohlenstoffdioxid bei Pflanzenatmung und Gärung nach.', 'Pupils look at a leaf cross-section under the microscope and test for plant substances and for carbon dioxide in plant respiration and fermentation.', NULL, NULL, '{"goals_in_evomentor": 3, "match": ["9", "Stoff- und Energiewechselprozesse von Pilzen und grünen Pflanzen", "Fachpraktisches Arbeiten"]}', 'evomentor-goals-2026-11-02'),
  ('e7090a5e-3bc3-5be8-84e4-05c791810613', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9/weitere-lernziele', '93ae7426-f6ce-5aee-8bc1-2fcc4716a718', 'topic', 'biologie', 'Gymnasium', '9', NULL, NULL, 1, 'Weitere Lernziele', 'Further goals', 'Sammelgruppe für zwei Lernziele ohne eigene Überschrift. Es geht um die optimale Temperatur für den Ertrag und um Konkurrenz zwischen Lebewesen.', 'A group for two goals that have no heading of their own. They cover the best temperature for crop yield and competition between organisms.', NULL, NULL, '{"goals_in_evomentor": 2, "match": ["9", ""]}', 'evomentor-goals-2026-11-02'),
  ('ed826d86-58b0-5f22-ad90-cd84b30f0a90', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9/weitere-lernziele/ohne-titel-0', 'e7090a5e-3bc3-5be8-84e4-05c791810613', 'subtopic', 'biologie', 'Gymnasium', '9', NULL, NULL, 0, 'Weitere Lernziele', 'Further goals', 'Lernende begründen eine optimale Temperatur zur Ertragssteigerung und betrachten Konkurrenz als Wechselbeziehung zwischen Lebewesen.', 'Pupils give reasons for an optimal temperature to raise yield and look at competition as an interaction between organisms.', NULL, NULL, '{"goals_in_evomentor": 2, "match": ["9", "", ""]}', 'evomentor-goals-2026-11-02'),
  ('5ecf7db9-3b52-5b9e-adeb-26511c01226c', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9/oekologie', '93ae7426-f6ce-5aee-8bc1-2fcc4716a718', 'topic', 'biologie', 'Gymnasium', '9', NULL, NULL, 2, 'Ökologie', 'Ecology', 'Lernende untersuchen, wie Organismen und Umwelt sich gegenseitig beeinflussen, wie ein Ökosystem aufgebaut ist und wie menschliche Einflüsse auf Ökosysteme wirken.', 'Pupils study how organisms and their environment affect each other, how an ecosystem is built and how human influences act on ecosystems.', NULL, NULL, '{"goals_in_evomentor": 17, "match": ["9", "Ökologie"]}', 'evomentor-goals-2026-11-02'),
  ('8281010a-2c71-540b-b22c-67e544a0d681', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9/oekologie/wechselwirkungen-zwischen-organismen-und-ihrer-u-0', '5ecf7db9-3b52-5b9e-adeb-26511c01226c', 'subtopic', 'biologie', 'Gymnasium', '9', NULL, NULL, 0, 'Wechselwirkungen zwischen Organismen und ihrer Umwelt', 'Interactions between organisms and their environment', 'Lernende definieren abiotische und biotische Umweltfaktoren, erklären ökologische Potenz und Angepasstheit (Licht- und Schattenblätter) und betrachten die Räuber-Beute-Beziehung.', 'Pupils define abiotic and biotic environmental factors, explain ecological potency and adaptation (sun and shade leaves) and look at predator-prey relationships.', 'p. 27', NULL, '{"goals_in_evomentor": 6, "match": ["9", "Ökologie", "Wechselwirkungen zwischen Organismen und ihrer Umwelt"]}', 'evomentor-goals-2026-11-02'),
  ('37a87bbd-de88-5c12-be44-5b19bd669dad', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9/oekologie/oekosystem-1', '5ecf7db9-3b52-5b9e-adeb-26511c01226c', 'subtopic', 'biologie', 'Gymnasium', '9', NULL, NULL, 1, 'Ökosystem', 'Ecosystem', 'Lernende beschreiben das Ökosystem als Einheit aus Biotop und Biozönose, als offenes System mit räumlicher und zeitlicher Struktur sowie Stoffkreislauf und Energiefluss.', 'Pupils describe the ecosystem as a unit of biotope and biocoenosis, as an open system with spatial and temporal structure, and as a place of matter cycling and energy flow.', 'p. 27', NULL, '{"goals_in_evomentor": 6, "match": ["9", "Ökologie", "Ökosystem"]}', 'evomentor-goals-2026-11-02'),
  ('92aa987a-127c-5bbf-bb3d-5b1f4e195901', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9/oekologie/anthropogene-einfluesse-auf-oekosysteme-und-dere-2', '5ecf7db9-3b52-5b9e-adeb-26511c01226c', 'subtopic', 'biologie', 'Gymnasium', '9', NULL, NULL, 2, 'Anthropogene Einflüsse auf Ökosysteme und deren Folgen', 'Human influences on ecosystems and their consequences', 'Lernende begründen, warum Struktur- und Artenvielfalt Ökosysteme stabil halten, erläutern ökologische Nachhaltigkeit und vergleichen naturnahe mit intensiv genutzten Ökosystemen.', 'Pupils explain why structural and species diversity keep ecosystems stable, explain ecological sustainability and compare near-natural with intensively used ecosystems.', 'p. 27', NULL, '{"goals_in_evomentor": 3, "match": ["9", "Ökologie", "Anthropogene Einflüsse auf Ökosysteme und deren Folgen"]}', 'evomentor-goals-2026-11-02'),
  ('72d10b8b-f947-54a3-b973-a855311e6d58', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/9/oekologie/fachpraktisches-arbeiten-3', '5ecf7db9-3b52-5b9e-adeb-26511c01226c', 'subtopic', 'biologie', 'Gymnasium', '9', NULL, NULL, 3, 'Fachpraktisches Arbeiten', 'Practical work', 'Lernende mikroskopieren Licht- und Schattenblätter und untersuchen auf einer Exkursion die Struktur eines Ökosystems.', 'Pupils look at sun and shade leaves under the microscope and, on a field trip, study the structure of an ecosystem.', NULL, NULL, '{"goals_in_evomentor": 2, "match": ["9", "Ökologie", "Fachpraktisches Arbeiten"]}', 'evomentor-goals-2026-11-02'),
  ('ea4f9c7a-5837-5b99-b0cc-bd1874c58f27', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/10', '851e36fe-3469-57bc-a46f-33bf8494544f', 'grade_band', 'biologie', 'Gymnasium', '10', NULL, NULL, 10, 'Klassenstufe 10', 'Grade 10', NULL, NULL, NULL, NULL, '{}', 'evomentor-goals-2026-11-02'),
  ('9566df09-9201-52aa-b42a-aec938604e3f', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/10/genetik', 'ea4f9c7a-5837-5b99-b0cc-bd1874c58f27', 'topic', 'biologie', 'Gymnasium', '10', NULL, NULL, 0, 'Genetik', 'Genetics', 'Lernende befassen sich damit, wie Erbinformation gespeichert, weitergegeben und umgesetzt wird, woher Variabilität stammt und wie Humangenetik und Gentechnik angewendet werden.', 'Pupils work on how genetic information is stored, passed on and put into effect, where variability comes from and how human genetics and genetic engineering are applied.', NULL, NULL, '{"goals_in_evomentor": 32, "match": ["10", "Genetik"]}', 'evomentor-goals-2026-11-02'),
  ('ae2a62e1-abd7-5d6f-87ca-e71ba2ee9128', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/10/genetik/speicherung-genetischer-information-0', '9566df09-9201-52aa-b42a-aec938604e3f', 'subtopic', 'biologie', 'Gymnasium', '10', NULL, NULL, 0, 'Speicherung genetischer Information', 'Storage of genetic information', 'Lernende beschreiben Zellkern, Chromatin und den Chromosomensatz des Menschen und erklären die Bedeutung der Versuche von Griffith und Avery.', 'Pupils describe the cell nucleus, chromatin and the human chromosome set and explain the significance of the experiments by Griffith and Avery.', 'p. 29', NULL, '{"goals_in_evomentor": 5, "match": ["10", "Genetik", "Speicherung genetischer Information"]}', 'evomentor-goals-2026-11-02'),
  ('b214e467-2e1d-5ff9-94fc-09245532ced6', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/10/genetik/weitergabe-genetischer-information-1', '9566df09-9201-52aa-b42a-aec938604e3f', 'subtopic', 'biologie', 'Gymnasium', '10', NULL, NULL, 1, 'Weitergabe genetischer Information', 'Passing on genetic information', 'Lernende erklären die semikonservative Replikation samt Fehlerkontrolle und Reparatur, den Zellzyklus mit Mitose sowie Meiose und die Bildung von Keimzellen.', 'Pupils explain semi-conservative replication with error checking and repair, the cell cycle with mitosis, and meiosis and the formation of germ cells.', 'p. 29', NULL, '{"goals_in_evomentor": 11, "match": ["10", "Genetik", "Weitergabe genetischer Information"]}', 'evomentor-goals-2026-11-02'),
  ('68ec2ea0-4c1c-5c44-b95a-dac64e45817a', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/10/genetik/realisierung-genetischer-information-2', '9566df09-9201-52aa-b42a-aec938604e3f', 'subtopic', 'biologie', 'Gymnasium', '10', NULL, NULL, 2, 'Realisierung genetischer Information', 'Expression of genetic information', 'Lernende erklären den genetischen Code, die Proteinbiosynthese mit Transkription und Translation und den Zusammenhang von Proteinen und Merkmalen.', 'Pupils explain the genetic code, protein biosynthesis with transcription and translation, and how proteins and traits are linked.', 'p. 29', NULL, '{"goals_in_evomentor": 3, "match": ["10", "Genetik", "Realisierung genetischer Information"]}', 'evomentor-goals-2026-11-02'),
  ('a6c93c31-ea0d-5d53-972f-f4e512ee2197', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/10/genetik/variabilitaet-von-merkmalen-3', '9566df09-9201-52aa-b42a-aec938604e3f', 'subtopic', 'biologie', 'Gymnasium', '10', NULL, NULL, 3, 'Variabilität von Merkmalen', 'Variability of traits', 'Lernende erläutern Rekombination, Mutation und Modifikation als Ursachen dafür, dass Merkmale variieren.', 'Pupils explain recombination, mutation and modification as causes of variation in traits.', 'p. 30', NULL, '{"goals_in_evomentor": 3, "match": ["10", "Genetik", "Variabilität von Merkmalen"]}', 'evomentor-goals-2026-11-02'),
  ('74567b23-4982-54b4-87e9-44da8283e441', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/10/genetik/humangenetik-anwendung-genetischer-erkenntnisse-4', '9566df09-9201-52aa-b42a-aec938604e3f', 'subtopic', 'biologie', 'Gymnasium', '10', NULL, NULL, 4, 'Humangenetik (Anwendung genetischer Erkenntnisse)', 'Human genetics (applying genetic knowledge)', 'Lernende betrachten Erbgänge beim Menschen, etwa bei Mukoviszidose und Rot-Grün-Sehschwäche, die Trisomie 21 und die Möglichkeiten der Pränataldiagnostik.', 'Pupils look at inheritance patterns in humans, for example in cystic fibrosis and red-green colour blindness, at trisomy 21 and at the possibilities of prenatal diagnosis.', NULL, NULL, '{"goals_in_evomentor": 4, "match": ["10", "Genetik", "Humangenetik (Anwendung genetischer Erkenntnisse)"]}', 'evomentor-goals-2026-11-02'),
  ('f2c1ee6b-c6a6-53a9-850e-c120e64a746a', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/10/genetik/gentechnik-anwendung-genetischer-erkenntnisse-5', '9566df09-9201-52aa-b42a-aec938604e3f', 'subtopic', 'biologie', 'Gymnasium', '10', NULL, NULL, 5, 'Gentechnik (Anwendung genetischer Erkenntnisse)', 'Genetic engineering (applying genetic knowledge)', 'Lernende lernen Modellorganismen kennen, betrachten gentechnische Verfahren wie die Herstellung von Humaninsulin und transgenem Mais und bewerten Anwendungen der Gentechnik.', 'Pupils get to know model organisms, look at genetic engineering methods such as producing human insulin and transgenic maize, and evaluate uses of genetic engineering.', NULL, NULL, '{"goals_in_evomentor": 4, "match": ["10", "Genetik", "Gentechnik (Anwendung genetischer Erkenntnisse)"]}', 'evomentor-goals-2026-11-02'),
  ('8417ddea-df4b-57d0-9796-a5c97dcd14f3', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/10/genetik/fachpraktisches-arbeiten-6', '9566df09-9201-52aa-b42a-aec938604e3f', 'subtopic', 'biologie', 'Gymnasium', '10', NULL, NULL, 6, 'Fachpraktisches Arbeiten', 'Practical work', 'Lernende mikroskopieren Riesenchromosomen und Mitosestadien an Präparaten.', 'Pupils look at giant chromosomes and stages of mitosis in prepared specimens under the microscope.', NULL, NULL, '{"goals_in_evomentor": 2, "match": ["10", "Genetik", "Fachpraktisches Arbeiten"]}', 'evomentor-goals-2026-11-02'),
  ('257cb19f-c497-5d5f-94ea-0d2d55e96ced', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/10/evolution', 'ea4f9c7a-5837-5b99-b0cc-bd1874c58f27', 'topic', 'biologie', 'Gymnasium', '10', NULL, NULL, 1, 'Evolution', 'Evolution', 'Lernende befassen sich mit Mechanismen und Belegen der Evolution und mit der Evolution des Menschen.', 'Pupils work on the mechanisms of evolution, the evidence for it and the evolution of humans.', NULL, NULL, '{"goals_in_evomentor": 12, "match": ["10", "Evolution"]}', 'evomentor-goals-2026-11-02'),
  ('51a6ba53-339b-5725-b957-69440fe812ac', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/10/evolution/evolutionsbiologische-zusammenhaenge-0', '257cb19f-c497-5d5f-94ea-0d2d55e96ced', 'subtopic', 'biologie', 'Gymnasium', '10', NULL, NULL, 0, 'Evolutionsbiologische Zusammenhänge', 'Connections in evolutionary biology', 'Lernende erklären Mechanismen der Synthetischen Evolutionstheorie und Artbildung, begründen Angepasstheit mit Evolution und befassen sich mit der Bedeutung von Darwins Theorie.', 'Pupils explain mechanisms of the synthetic theory of evolution and speciation, account for adaptation through evolution and look at the significance of Darwin''s theory.', 'p. 31', NULL, '{"goals_in_evomentor": 4, "match": ["10", "Evolution", "Evolutionsbiologische Zusammenhänge"]}', 'evomentor-goals-2026-11-02'),
  ('4eb10786-573c-5753-ba94-c954bc696e4b', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/10/evolution/belege-fuer-die-evolution-1', '257cb19f-c497-5d5f-94ea-0d2d55e96ced', 'subtopic', 'biologie', 'Gymnasium', '10', NULL, NULL, 1, 'Belege für die Evolution', 'Evidence for evolution', 'Lernende betrachten Fossilien, Mosaikformen, den DNA-Vergleich fossiler und heutiger Organismen sowie Homologien und Konvergenzen als Belege für Evolution.', 'Pupils look at fossils, mosaic forms, DNA comparison of fossil and present-day organisms, and homologies and convergences as evidence for evolution.', 'p. 31', NULL, '{"goals_in_evomentor": 4, "match": ["10", "Evolution", "Belege für die Evolution"]}', 'evomentor-goals-2026-11-02'),
  ('d9f1eedb-dea2-5782-9bcb-62887b46fb8a', 'thuringia-curriculum-repository', 'DE-TH/biologie-gymnasium-2026/10/evolution/evolution-des-menschen-2', '257cb19f-c497-5d5f-94ea-0d2d55e96ced', 'subtopic', 'biologie', 'Gymnasium', '10', NULL, NULL, 2, 'Evolution des Menschen', 'Human evolution', 'Lernende arbeiten mit einem Kladogramm der Hominiden, mit Belegen zur Menschwerdung und mit der kulturellen und sozialen Evolution und erklären, warum das Rassenkonzept biologisch widerlegt ist.', 'Pupils work with a cladogram of the hominids, with evidence for human origins and with cultural and social evolution, and explain why the race concept is refuted in biology.', 'p. 31', NULL, '{"goals_in_evomentor": 4, "match": ["10", "Evolution", "Evolution des Menschen"]}', 'evomentor-goals-2026-11-02'),
  ('3b31c458-dc44-5823-a205-6146ef85fb4e', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di', NULL, 'edition', 'biologie', 'Gymnasium', NULL, NULL, NULL, 0, 'Biologie, Gymnasium · Online-Ausgabe, gelesen am 2026-10-28', 'Biology, Gymnasium · online edition, read 2026-10-28', NULL, NULL, NULL, NULL, '{"units": 22, "edition": "Online edition of the LehrplanPLUS as displayed at lehrplanplus.bayern.de and read on 2026-10-28; the pages carry no edition number (portal footer: 2026 ISB)"}', 'unit-records-195'),
  ('efb60fa7-3dde-5349-81bd-e027cdeef111', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/5', '3b31c458-dc44-5823-a205-6146ef85fb4e', 'grade_band', 'biologie', 'Gymnasium', '5', NULL, NULL, 5, 'Klassenstufe 5', 'Grade 5', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('7b1fbb3b-e288-5aa8-92a1-e2651447487d', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/5/de-by-lp-bio-nut5-erkenntnisse', 'efb60fa7-3dde-5349-81bd-e027cdeef111', 'unit', 'biologie', 'Gymnasium', '5', NULL, 'DE-BY-LP-BIO-nut5-erkenntnisse', 0, 'Erkenntnisse gewinnen – kommunizieren – bewerten', 'Gaining knowledge, communicating, evaluating', NULL, 'Pupils learn the steps of a scientific investigation, basic lab and field techniques and microscopy, and see that scientific knowledge changes over time. They also learn what a model is and what it leaves out, and how to document and explain results with tables and diagrams.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/5/nt_gym', '{"unitNumber": "NT5 2.1", "topicTags": ["nature_of_science"]}', 'unit-records-195'),
  ('409614a2-1880-5691-8b4d-db3066e229fa', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/6', '3b31c458-dc44-5823-a205-6146ef85fb4e', 'grade_band', 'biologie', 'Gymnasium', '6', NULL, NULL, 6, 'Klassenstufe 6', 'Grade 6', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('388b7d63-09cb-56cd-be30-f292385a83b7', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/6/de-by-lp-bio-nut6-erkenntnisse', '409614a2-1880-5691-8b4d-db3066e229fa', 'unit', 'biologie', 'Gymnasium', '6', NULL, 'DE-BY-LP-BIO-nut6-erkenntnisse', 0, 'Erkenntnisse gewinnen – kommunizieren – bewerten', 'Gaining knowledge, communicating, evaluating', NULL, 'Builds on the investigation steps with variables, constants and control experiments, error sources, structured observation and species identification. Pupils compare models with what they stand for and judge simple sources, separating descriptive from evaluative statements.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/6/nt_gym', '{"unitNumber": "NT6 1.1", "topicTags": ["nature_of_science"]}', 'unit-records-195'),
  ('99045e29-c9e5-52af-8d46-e7d99c96cb4c', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/6/de-by-lp-bio-nut6-wirbeltiere-angepasstheit', '409614a2-1880-5691-8b4d-db3066e229fa', 'unit', 'biologie', 'Gymnasium', '6', NULL, 'DE-BY-LP-BIO-nut6-wirbeltiere-angepasstheit', 1, 'Biodiversität bei Wirbeltieren – Variabilität und Angepasstheit', 'Biodiversity in vertebrates: variability and adaptedness', NULL, 'Pupils compare vertebrate classes for adaptations in movement, feeding and energy use, reproduction and senses. Topics include temperature regulation, signals within a species, parental investment, and telling species-specific traits from traits of the wider group.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/6/nt_gym', '{"unitNumber": "NT6 1.3", "hours": 26, "topicTags": ["selection_adaptation", "diversity_systematics", "behavior_cognition"]}', 'unit-records-195'),
  ('0c5002aa-8f58-5847-a880-0107fa646094', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/6/de-by-lp-bio-nut6-verwandtschaft-evolution', '409614a2-1880-5691-8b4d-db3066e229fa', 'unit', 'biologie', 'Gymnasium', '6', NULL, 'DE-BY-LP-BIO-nut6-verwandtschaft-evolution', 2, 'Verwandtschaft der Wirbeltiere und Evolution', 'Relatedness of vertebrates and evolution', NULL, 'Pupils sort vertebrates into classes by characteristic features and meet a simplified model of evolution in which varied traits can bring advantages. They compare selective breeding by humans with natural evolutionary processes and judge keeping pets and farm animals.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/6/nt_gym', '{"unitNumber": "NT6 1.4", "hours": 8, "topicTags": ["evolution", "selection_adaptation", "diversity_systematics"]}', 'unit-records-195'),
  ('c7f33aa4-07d4-5473-b342-017b860aabcf', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/8', '3b31c458-dc44-5823-a205-6146ef85fb4e', 'grade_band', 'biologie', 'Gymnasium', '8', NULL, NULL, 8, 'Klassenstufe 8', 'Grade 8', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('1bf97d01-3c70-55f7-9203-a322de13cc3c', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/8/de-by-lp-bio-b8-erkenntnisse', 'c7f33aa4-07d4-5473-b342-017b860aabcf', 'unit', 'biologie', 'Gymnasium', '8', NULL, 'DE-BY-LP-BIO-b8-erkenntnisse', 0, 'Erkenntnisse gewinnen – kommunizieren – bewerten', 'Gaining knowledge, communicating, evaluating', NULL, 'Pupils formulate biological questions, plan simple investigations and interpret data with possible error sources. They discuss how scientific knowledge grows, what models can and cannot show, and weigh consequences of human action for sustainability and health.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/8/biologie', '{"unitNumber": "B8 Lernbereich 1", "topicTags": ["nature_of_science"]}', 'unit-records-195'),
  ('3bb50f13-4580-5b4a-8ec6-52b63a65b648', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/8/de-by-lp-bio-b8-verhalten', 'c7f33aa4-07d4-5473-b342-017b860aabcf', 'unit', 'biologie', 'Gymnasium', '8', NULL, 'DE-BY-LP-BIO-b8-verhalten', 1, 'Verhalten – genetisch bedingt und erlernt', 'Behaviour: genetically based and learned', NULL, 'Pupils observe and compare simple behaviours, including dummy experiments, as the outcome of inner factors and triggering stimuli. They judge from observation data whether a behaviour is mainly inherited or learned and plan experiments on classical and operant conditioning.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/8/biologie', '{"unitNumber": "B8 Lernbereich 4", "hours": 10, "topicTags": ["behavior_cognition", "inheritance_variation"]}', 'unit-records-195'),
  ('6237b920-a43f-5388-aa82-8645f73bbfd4', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/9', '3b31c458-dc44-5823-a205-6146ef85fb4e', 'grade_band', 'biologie', 'Gymnasium', '9', NULL, NULL, 9, 'Klassenstufe 9', 'Grade 9', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('1350fdfd-a88d-57f5-b88b-9e2e40f3e6d8', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/9/de-by-lp-bio-b9-erkenntnisse', '6237b920-a43f-5388-aa82-8645f73bbfd4', 'unit', 'biologie', 'Gymnasium', '9', NULL, 'DE-BY-LP-BIO-b9-erkenntnisse', 0, 'Erkenntnisse gewinnen – kommunizieren – bewerten', 'Gaining knowledge, communicating, evaluating', NULL, 'Pupils plan hypothesis-driven investigations, compare organisms to infer causes of similarity and judge the validity of data. They describe features of scientific knowledge, for example in evolution research, and develop alternative models while noting strengths and limits.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/9/biologie', '{"unitNumber": "B9 Lernbereich 1", "topicTags": ["nature_of_science"]}', 'unit-records-195'),
  ('e6454969-1d29-56bc-aec0-537161077285', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/9/de-by-lp-bio-b9-genetik', '6237b920-a43f-5388-aa82-8645f73bbfd4', 'unit', 'biologie', 'Gymnasium', '9', NULL, 'DE-BY-LP-BIO-b9-genetik', 1, 'Genetik und Gentechnik', 'Genetics and genetic engineering', NULL, 'Pupils link DNA structure, protein synthesis and traits, then cover chromosome organisation, replication and the cell cycle. They explain meiosis and fertilisation as sources of genetic variety, genome mutations such as trisomy 21, and weigh ethical aspects of diagnostics and genetic engineering.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/9/biologie', '{"unitNumber": "B9 Lernbereich 3", "hours": 18, "topicTags": ["inheritance_variation"]}', 'unit-records-195'),
  ('3cd003d2-ea88-5e60-bd4b-e82fcbbc6c8d', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/9/de-by-lp-bio-b9-evolution', '6237b920-a43f-5388-aa82-8645f73bbfd4', 'unit', 'biologie', 'Gymnasium', '9', NULL, 'DE-BY-LP-BIO-b9-evolution', 2, 'Evolution', 'Evolution', NULL, 'Pupils describe the history of life as continuing evolution supported by scientific evidence. They explain how a present-day species arose through genetic variability, natural selection and geographic isolation, and explain adaptations as selective advantages.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/9/biologie', '{"unitNumber": "B9 Lernbereich 4", "hours": 8, "topicTags": ["evolution", "selection_adaptation", "diversity_systematics"]}', 'unit-records-195'),
  ('4879d358-b9f2-5326-b7b4-f48b7fb686de', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/9/de-by-lp-bio-b9-wirbellose', '6237b920-a43f-5388-aa82-8645f73bbfd4', 'unit', 'biologie', 'Gymnasium', '9', NULL, 'DE-BY-LP-BIO-b9-wirbellose', 3, 'Biodiversität bei Wirbellosen – Variabilität und Angepasstheit', 'Biodiversity in invertebrates: variability and adaptedness', NULL, 'Pupils compare insects with vertebrates and other invertebrates in movement, metabolism, reproduction and nervous system, describing the diversity found as evolutionary adaptation. Topics include metamorphosis, mouthparts, senses and signals such as mimicry and pheromones.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/9/biologie', '{"unitNumber": "B9 Lernbereich 5", "hours": 16, "topicTags": ["diversity_systematics", "selection_adaptation", "behavior_cognition"]}', 'unit-records-195'),
  ('18e82951-b7ab-56d5-b41f-f68180bac295', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/10', '3b31c458-dc44-5823-a205-6146ef85fb4e', 'grade_band', 'biologie', 'Gymnasium', '10', NULL, NULL, 10, 'Klassenstufe 10', 'Grade 10', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('0d8bd4e4-dcb5-579a-b810-31d711aeff08', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/10/de-by-lp-bio-b10-erkenntnisse', '18e82951-b7ab-56d5-b41f-f68180bac295', 'unit', 'biologie', 'Gymnasium', '10', NULL, 'DE-BY-LP-BIO-b10-erkenntnisse', 0, 'Erkenntnisse gewinnen – kommunizieren – bewerten', 'Gaining knowledge, communicating, evaluating', NULL, 'Pupils derive questions from complex phenomena, run their own investigations and judge the validity of data. They reflect on the limits, provisional status and subjectivity of scientific knowledge, revise alternative models and use systematic decision strategies.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/10/biologie', '{"unitNumber": "B10 Lernbereich 1", "topicTags": ["nature_of_science"]}', 'unit-records-195'),
  ('10ff5eea-420a-5c0a-be61-6d2aefac3eb9', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/10/de-by-lp-bio-b10-oekosystem-mensch', '18e82951-b7ab-56d5-b41f-f68180bac295', 'unit', 'biologie', 'Gymnasium', '10', NULL, 'DE-BY-LP-BIO-b10-oekosystem-mensch', 1, 'Ökosystem Mensch', 'The human body as an ecosystem', NULL, 'Pupils study the human body as a habitat with symbionts, parasites and pathogens, immune defence and vaccination. The unit mentions population growth of disease-causing bacteria, their adaptation to the human host and the formation of antibiotic resistance.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/10/biologie', '{"unitNumber": "B10 Lernbereich 2", "hours": 16, "topicTags": ["human_biology", "ecology_populations", "selection_adaptation"]}', 'unit-records-195'),
  ('366547b2-0b74-5b4c-b2c8-af0c1387bb3c', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/10/de-by-lp-bio-b10-vergangenheit-zukunft-mensch', '18e82951-b7ab-56d5-b41f-f68180bac295', 'unit', 'biologie', 'Gymnasium', '10', NULL, 'DE-BY-LP-BIO-b10-vergangenheit-zukunft-mensch', 2, 'Vergangenheit und Zukunft des Menschen', 'Past and future of humans', NULL, 'Pupils outline the history of life and place modern humans in the natural system of classification using anatomical and molecular features. They derive hypotheses on human evolution from fossil finds and consider cultural evolution and the future population of humans.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/10/biologie', '{"unitNumber": "B10 Lernbereich 4", "hours": 7, "topicTags": ["evolution", "diversity_systematics", "human_biology"]}', 'unit-records-195'),
  ('70d10955-b317-5032-8944-3779a9520a53', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12-13', '3b31c458-dc44-5823-a205-6146ef85fb4e', 'grade_band', 'biologie', 'Gymnasium', '12/13', NULL, NULL, 12, 'Klassenstufe 12/13', 'Grade 12/13', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('126fc0de-d269-58a9-9a47-ccafaf3b39f7', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12-13/de-by-lp-bio-b12-13-kompetenzrahmen', '70d10955-b317-5032-8944-3779a9520a53', 'unit', 'biologie', 'Gymnasium', '12/13', NULL, 'DE-BY-LP-BIO-b12-13-kompetenzrahmen', 0, 'Biologische Sachverhalte und Zusammenhänge betrachten – Erkenntnisse gewinnen – kommunizieren – bewerten', 'Viewing biological facts and connections: gaining knowledge, communicating, evaluating', NULL, 'Competence frame for the Qualifikationsphase. Pupils form hypotheses, plan and evaluate investigations and models, and reflect on criteria of scientific knowledge such as falsifiability and provisional status. It also covers proximate and ultimate explanation, communication and evaluation skills.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/biologie/grundlegend', '{"unitNumber": "B12/B13 Lernbereich 1", "topicTags": ["nature_of_science"]}', 'unit-records-195'),
  ('0fb949e6-80df-501c-a518-fdd6c1ca4648', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12', '3b31c458-dc44-5823-a205-6146ef85fb4e', 'grade_band', 'biologie', 'Gymnasium', '12', NULL, NULL, 12, 'Klassenstufe 12', 'Grade 12', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('7e3b292d-fe40-5aa5-b9e0-ec88c2287495', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12/de-by-lp-bio-b12-genetik-ga', '0fb949e6-80df-501c-a518-fdd6c1ca4648', 'unit', 'biologie', 'Gymnasium', '12', NULL, 'DE-BY-LP-BIO-b12-genetik-gA', 0, 'Genetik und Gentechnik', 'Genetics and genetic engineering', NULL, 'Pupils study how genetic information is stored and read, how gene activity is regulated and how DNA is copied. They cover meiosis, mutations and their role in evolution and biodiversity, gene technology, Mendelian crosses, pedigrees and ethical aspects of DNA analysis.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/biologie/grundlegend', '{"unitNumber": "B12 Lernbereich 2", "hours": 51, "courseLevel": "basic", "topicTags": ["inheritance_variation", "evolution"]}', 'unit-records-195'),
  ('ee3eb717-9f0d-5978-b6d3-fe3d1bd6733a', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12/de-by-lp-bio-b12-genetik-ea', '0fb949e6-80df-501c-a518-fdd6c1ca4648', 'unit', 'biologie', 'Gymnasium', '12', NULL, 'DE-BY-LP-BIO-b12-genetik-eA', 1, 'Genetik und Gentechnik', 'Genetics and genetic engineering', NULL, 'Pupils study storage and reading of genetic information with alternative splicing, regulation of gene activity including epigenetics, DNA repair and tumour formation. They cover meiosis, mutations and their role in evolution, gene technology, crosses with gene linkage, epigenetic inheritance and pedigrees.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/biologie/erhoeht', '{"unitNumber": "B12 Lernbereich 2", "hours": 86, "courseLevel": "advanced", "topicTags": ["inheritance_variation", "evolution"]}', 'unit-records-195'),
  ('180a49ca-cf38-53f7-b66e-112b1c03daf1', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12/de-by-lp-bio-b12-evolution-ga', '0fb949e6-80df-501c-a518-fdd6c1ca4648', 'unit', 'biologie', 'Gymnasium', '12', NULL, 'DE-BY-LP-BIO-b12-evolution-gA', 2, 'Evolution', 'Evolution', NULL, 'Pupils build phylogenetic trees and cladograms from molecular and other traits and compare approaches to classifying life. They apply the synthetic theory of evolution (variation, selection, drift, isolation) to explain speciation and biodiversity, and describe coevolution.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/biologie/grundlegend', '{"unitNumber": "B12 Lernbereich 3", "hours": 18, "courseLevel": "basic", "topicTags": ["evolution", "selection_adaptation", "diversity_systematics"]}', 'unit-records-195'),
  ('1ad60012-74ce-53e9-a06d-3968381fa198', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12/de-by-lp-bio-b12-evolution-ea', '0fb949e6-80df-501c-a518-fdd6c1ca4648', 'unit', 'biologie', 'Gymnasium', '12', NULL, 'DE-BY-LP-BIO-b12-evolution-eA', 3, 'Evolution', 'Evolution', NULL, 'Covers trees and cladograms, human evolution, and the synthetic theory of evolution applied to speciation including primates, plus coevolution. Pupils also treat cultural and social evolution of humans and the limits and dangers of human intervention in evolutionary processes.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/biologie/erhoeht', '{"unitNumber": "B12 Lernbereich 3", "hours": 30, "courseLevel": "advanced", "topicTags": ["evolution", "selection_adaptation", "diversity_systematics", "human_biology"]}', 'unit-records-195'),
  ('87a79c89-9ad1-5085-96ba-7c8d1aa61975', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12/de-by-lp-bio-b12-verhaltensoekologie-ga', '0fb949e6-80df-501c-a518-fdd6c1ca4648', 'unit', 'biologie', 'Gymnasium', '12', NULL, 'DE-BY-LP-BIO-b12-verhaltensoekologie-gA', 4, 'Verhaltensökologie – Evolution und Angepasstheit von Verhalten', 'Behavioural ecology: evolution and adaptedness of behaviour', NULL, 'Pupils explain behaviours through their effect on fitness and apply methods of behavioural ecology such as cost-benefit analysis and optimality models. Topics are cooperation and altruism, aggression, mate choice and parental investment.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/biologie/grundlegend', '{"unitNumber": "B12 Lernbereich 4", "hours": 15, "courseLevel": "basic", "topicTags": ["behavior_cognition", "selection_adaptation", "evolution"]}', 'unit-records-195'),
  ('3ff1e6d9-d5bf-5597-b6f4-a79af2128176', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12/de-by-lp-bio-b12-verhaltensoekologie-ea', '0fb949e6-80df-501c-a518-fdd6c1ca4648', 'unit', 'biologie', 'Gymnasium', '12', NULL, 'DE-BY-LP-BIO-b12-verhaltensoekologie-eA', 5, 'Verhaltensökologie – Evolution und Angepasstheit von Verhalten', 'Behavioural ecology: evolution and adaptedness of behaviour', NULL, 'Adds communication and signal forgery to the basic-level topics, and analyses primate social behaviour including humans. Pupils weigh inner and outer causes and treat one-sided biological explanations of human behaviour critically.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/biologie/erhoeht', '{"unitNumber": "B12 Lernbereich 4", "hours": 24, "courseLevel": "advanced", "topicTags": ["behavior_cognition", "selection_adaptation", "evolution", "human_biology"]}', 'unit-records-195'),
  ('429c381e-2377-56c1-8634-9653e139d770', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/13', '3b31c458-dc44-5823-a205-6146ef85fb4e', 'grade_band', 'biologie', 'Gymnasium', '13', NULL, NULL, 13, 'Klassenstufe 13', 'Grade 13', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('1e0bcfb5-5158-5129-b985-0d1919893709', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/13/de-by-lp-bio-b13-oekologie-ga', '429c381e-2377-56c1-8634-9653e139d770', 'unit', 'biologie', 'Gymnasium', '13', NULL, 'DE-BY-LP-BIO-b13-oekologie-gA', 0, 'Ökologie und Biodiversität', 'Ecology and biodiversity', NULL, 'Pupils study biotopes and communities, food webs, tolerance to abiotic factors, ecological niches and population growth. They then cover ecosystem services, the value of biodiversity and value conflicts between economic and ecological demands.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/13/biologie/grundlegend', '{"unitNumber": "B13 Lernbereich 4", "hours": 21, "courseLevel": "basic", "topicTags": ["ecology_populations", "diversity_systematics"]}', 'unit-records-195'),
  ('3bd6d558-b9e6-516a-84c7-b3e9f806b4de', 'germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/13/de-by-lp-bio-b13-oekologie-ea', '429c381e-2377-56c1-8634-9653e139d770', 'unit', 'biologie', 'Gymnasium', '13', NULL, 'DE-BY-LP-BIO-b13-oekologie-eA', 1, 'Ökologie und Biodiversität', 'Ecology and biodiversity', NULL, 'Adds quantitative field data, r and K strategies, the Lotka-Volterra predator-prey model and population estimation to the basic-level topics. Pupils also study interactions between biomes, invasive species and the effect of ecosystem change on biodiversity.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/13/biologie/erhoeht', '{"unitNumber": "B13 Lernbereich 4", "hours": 34, "courseLevel": "advanced", "topicTags": ["ecology_populations", "diversity_systematics", "selection_adaptation"]}', 'unit-records-195'),
  ('1b83a8e2-1bae-5878-8006-65da2d244ebd', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de', NULL, 'edition', 'informatik', 'Gymnasium', NULL, NULL, NULL, 0, 'Informatik, Gymnasium · Online-Ausgabe, gelesen am 2026-10-28', 'Computer science, Gymnasium · online edition, read 2026-10-28', NULL, NULL, NULL, NULL, '{"units": 42, "edition": "Online edition on lehrplanplus.bayern.de as read on 2026-10-28; the pages print no edition date"}', 'unit-records-195'),
  ('928b7d45-5857-5527-8427-df96156abdcc', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/6', '1b83a8e2-1bae-5878-8006-65da2d244ebd', 'grade_band', 'informatik', 'Gymnasium', '6', NULL, NULL, 6, 'Klassenstufe 6', 'Grade 6', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('b10a0496-80ca-54fa-820e-ce394af8f5bb', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/6/de-by-lp-inf-nt6-informationsdarstellung', '928b7d45-5857-5527-8427-df96156abdcc', 'unit', 'informatik', 'Gymnasium', '6', NULL, 'DE-BY-LP-INF-nt6-informationsdarstellung', 0, 'Informationsdarstellung mit Grafik-, Text- und Multimediadokumenten', 'Representing information with graphic, text and multimedia documents', NULL, 'Students treat graphic, text and multimedia documents as collections of objects with properties, model them with class and object diagrams, compare vector and pixel graphics, and use standard software to present information clearly.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/6/nt_gym', '{"unitNumber": "2.1", "hours": 18, "topicTags": ["information_data", "modelling_simulation"]}', 'unit-records-195'),
  ('6d6e832e-3252-564e-9c9e-8276f185e829', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/6/de-by-lp-inf-nt6-projekt-multimediapraesentation', '928b7d45-5857-5527-8427-df96156abdcc', 'unit', 'informatik', 'Gymnasium', '6', NULL, 'DE-BY-LP-INF-nt6-projekt-multimediapraesentation', 1, 'Projekt: Erstellen einer Multimediapräsentation', 'Project: creating a multimedia presentation', NULL, 'Within a set time frame, students produce a multimedia presentation on a given topic, apply quality criteria for slide design, and respect basic copyright rules when assembling content.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/6/nt_gym', '{"unitNumber": "2.2", "hours": 5, "topicTags": ["media_society", "information_data"]}', 'unit-records-195'),
  ('8e244957-c524-5291-9811-6f90d2494a14', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/6/de-by-lp-inf-nt6-hierarchische-informationsstrukturen', '928b7d45-5857-5527-8427-df96156abdcc', 'unit', 'informatik', 'Gymnasium', '6', NULL, 'DE-BY-LP-INF-nt6-hierarchische-informationsstrukturen', 2, 'Hierarchische Informationsstrukturen – Dateisystem', 'Hierarchical information structures: the file system', NULL, 'Students order information hierarchically, draw tree diagrams, analyse a file system as objects and classes, and use folders and paths to organise and locate files.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/6/nt_gym', '{"unitNumber": "2.3", "hours": 5, "topicTags": ["information_data", "modelling_simulation"]}', 'unit-records-195'),
  ('cca94c00-4fab-5d89-bee4-fa5b4de58209', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/7', '1b83a8e2-1bae-5878-8006-65da2d244ebd', 'grade_band', 'informatik', 'Gymnasium', '7', NULL, NULL, 7, 'Klassenstufe 7', 'Grade 7', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('1ac75277-ae3d-5225-adce-4dde25e73d51', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/7/de-by-lp-inf-nt7-vernetzte-informationsstrukturen', 'cca94c00-4fab-5d89-bee4-fa5b4de58209', 'unit', 'informatik', 'Gymnasium', '7', NULL, 'DE-BY-LP-INF-nt7-vernetzte-informationsstrukturen', 0, 'Vernetzte Informationsstrukturen', 'Networked information structures', NULL, 'Students model hypertext as linked objects and graphs, build a hypertext with a simple editor, search the internet with a critical eye for source quality, and describe how documents travel between clients and servers.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/7/nt_gym', '{"unitNumber": "2.1", "hours": 8, "topicTags": ["information_data", "systems_networks"]}', 'unit-records-195'),
  ('d7808c06-5e22-5520-b348-675681338805', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/7/de-by-lp-inf-nt7-chancen-risiken-digitaler-kommunikation', 'cca94c00-4fab-5d89-bee4-fa5b4de58209', 'unit', 'informatik', 'Gymnasium', '7', NULL, 'DE-BY-LP-INF-nt7-chancen-risiken-digitaler-kommunikation', 1, 'Chancen und Risiken digitaler Kommunikation', 'Opportunities and risks of digital communication', NULL, 'Students weigh opportunities and risks of digital communication for individuals and society, protect their own devices, and learn rules on personality rights and data protection in online exchanges.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/7/nt_gym', '{"unitNumber": "2.2", "hours": 5, "topicTags": ["media_society"]}', 'unit-records-195'),
  ('91b7be67-1fe4-519c-bec3-0d5b7c85642d', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/7/de-by-lp-inf-nt7-ablaeufe-durch-algorithmen', 'cca94c00-4fab-5d89-bee4-fa5b4de58209', 'unit', 'informatik', 'Gymnasium', '7', NULL, 'DE-BY-LP-INF-nt7-ablaeufe-durch-algorithmen', 2, 'Beschreibung von Abläufen durch Algorithmen', 'Describing processes with algorithms', NULL, 'Students analyse everyday problems, design algorithms from sequences, conditional statements and loops, and carry out simple algorithms with a suitable programming tool.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/7/nt_gym', '{"unitNumber": "2.3", "hours": 11, "topicTags": ["algorithms_programming"]}', 'unit-records-195'),
  ('6cf2f1be-403f-5479-b412-2fabae418e8e', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/7/de-by-lp-inf-nt7-projekt', 'cca94c00-4fab-5d89-bee4-fa5b4de58209', 'unit', 'informatik', 'Gymnasium', '7', NULL, 'DE-BY-LP-INF-nt7-projekt', 3, 'Projekt', 'Project', NULL, 'In a team and within a fixed time, students build a hypertext on a given topic or solve an algorithmic task such as a physical computing problem, and keep records of their intermediate results.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/7/nt_gym', '{"unitNumber": "2.4", "hours": 4, "topicTags": ["algorithms_programming", "information_data"]}', 'unit-records-195'),
  ('3cda4481-616c-53d1-a42c-94fddf0d9438', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/9', '1b83a8e2-1bae-5878-8006-65da2d244ebd', 'grade_band', 'informatik', 'Gymnasium', '9', NULL, NULL, 9, 'Klassenstufe 9', 'Grade 9', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('0d33d933-ada0-506e-9490-a354222acb4a', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/9/de-by-lp-inf-inf9-funktionen-datenfluesse-tabellenkalkulation', '3cda4481-616c-53d1-a42c-94fddf0d9438', 'unit', 'informatik', 'Gymnasium', '9', NULL, 'DE-BY-LP-INF-inf9-funktionen-datenfluesse-tabellenkalkulation', 0, 'Funktionen und Datenflüsse, Tabellenkalkulationsprogramm', 'Functions and data flows, spreadsheets', NULL, 'Students describe data-processing steps as functions, draw data-flow diagrams, chain functions together, and implement them as spreadsheet formulas to solve practical tasks.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/9/informatik', '{"unitNumber": "1", "hours": 14, "topicTags": ["information_data", "modelling_simulation"]}', 'unit-records-195'),
  ('03c43811-08ca-5dfc-83ea-069d94916825', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/9/de-by-lp-inf-inf9-datenmodellierung-datenbanksysteme', '3cda4481-616c-53d1-a42c-94fddf0d9438', 'unit', 'informatik', 'Gymnasium', '9', NULL, 'DE-BY-LP-INF-inf9-datenmodellierung-datenbanksysteme', 1, 'Grundlagen der Datenmodellierung und relationaler Datenbanksysteme', 'Basics of data modelling and relational database systems', NULL, 'Students model data sets with objects and classes, turn the model into table schemas in a database system, and write simple SQL queries to retrieve information from one table.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/9/informatik', '{"unitNumber": "2", "hours": 10, "topicTags": ["information_data", "modelling_simulation"]}', 'unit-records-195'),
  ('5cfb52ba-aaca-516e-adf5-6e7f37f6ba78', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/9/de-by-lp-inf-inf9-oo-modellierung-programmierung', '3cda4481-616c-53d1-a42c-94fddf0d9438', 'unit', 'informatik', 'Gymnasium', '9', NULL, 'DE-BY-LP-INF-inf9-oo-modellierung-programmierung', 2, 'Grundlagen der objektorientierten Modellierung und Programmierung', 'Basics of object-oriented modelling and programming', NULL, 'Students abstract objects into classes, declare classes with attributes and methods in an object-oriented language, use assignments and control structures to implement algorithms, and build simple inheritance hierarchies.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/9/informatik', '{"unitNumber": "3", "hours": 26, "topicTags": ["algorithms_programming", "modelling_simulation"]}', 'unit-records-195'),
