  ('09268cde-6865-5d04-9870-5349fa69658f', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ea-funktionsweise-rechner', 'b52c2e60-e531-5e6d-a683-20cdf7b613b9', 'unit', 'informatik', 'Gymnasium', '12', NULL, 'DE-BY-LP-INF-inf12-eA-funktionsweise-rechner', 9, 'Funktionsweise eines Rechners', 'How a computer works', NULL, 'Students compare computer components with the Von Neumann model, represent integers with two''s complement, build logic circuits from gates, and explain a register machine and write simple assembly programs for it.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/informatik/erhoeht', '{"unitNumber": "4", "hours": 26, "courseLevel": "advanced", "topicTags": ["systems_networks"]}', 'unit-records-195'),
  ('0e05204c-59cf-5b35-ab08-14d68af59e67', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ga-nebenlaeufige-prozesse', 'b52c2e60-e531-5e6d-a683-20cdf7b613b9', 'unit', 'informatik', 'Gymnasium', '12', NULL, 'DE-BY-LP-INF-inf12-gA-nebenlaeufige-prozesse', 10, 'Nebenläufige Prozesse', 'Concurrent processes', NULL, 'Students analyse parallel activities that share resources, model resource use and deadlocks, describe threads with sequence diagrams, and implement simple concurrent programs synchronised with a monitor.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/informatik/grundlegend', '{"unitNumber": "4", "hours": 9, "courseLevel": "basic", "topicTags": ["systems_networks", "algorithms_programming"]}', 'unit-records-195'),
  ('058120d0-339a-5352-9bad-4fc15765de3e', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-spaet-graphen', 'b52c2e60-e531-5e6d-a683-20cdf7b613b9', 'unit', 'informatik', 'Gymnasium', '12', NULL, 'DE-BY-LP-INF-inf12-spaet-graphen', 11, 'Graphen', 'Graphs', NULL, 'Students model networked structures as graphs, implement a graph with an adjacency matrix, and work with depth-first search and Dijkstra''s shortest-path algorithm.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/informatik/grundlegend-spaet', '{"unitNumber": "4", "hours": 10, "courseLevel": "basic", "topicTags": ["information_data", "algorithms_programming"]}', 'unit-records-195'),
  ('54ac24a7-8477-57be-8112-01d9904fa71d', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ea-betriebssysteme-nebenlaeufigkeit', 'b52c2e60-e531-5e6d-a683-20cdf7b613b9', 'unit', 'informatik', 'Gymnasium', '12', NULL, 'DE-BY-LP-INF-inf12-eA-betriebssysteme-nebenlaeufigkeit', 12, 'Betriebssysteme, Prozesse und Nebenläufigkeit', 'Operating systems, processes and concurrency', NULL, 'Students explain operating-system tasks and security mechanisms, compare scheduling strategies, model shared resources and deadlocks, and implement synchronised concurrent processes with monitors or semaphores.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/informatik/erhoeht', '{"unitNumber": "5", "hours": 23, "courseLevel": "advanced", "topicTags": ["systems_networks", "algorithms_programming"]}', 'unit-records-195'),
  ('c85cf336-dbc2-59ec-936a-cef5bc6f61c1', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ga-informationssicherheit', 'b52c2e60-e531-5e6d-a683-20cdf7b613b9', 'unit', 'informatik', 'Gymnasium', '12', NULL, 'DE-BY-LP-INF-inf12-gA-informationssicherheit', 13, 'Informationssicherheit', 'Information security', NULL, 'Students analyse an information system against the main security goals, describe threat categories and attack scenarios, explain protective measures with their limits, and discuss questions such as disclosing vulnerabilities.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/informatik/grundlegend', '{"unitNumber": "5", "hours": 6, "courseLevel": "basic", "topicTags": ["systems_networks", "media_society"]}', 'unit-records-195'),
  ('f9efeaa1-82e2-5572-b902-87c9aa40f34a', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-spaet-informationssicherheit', 'b52c2e60-e531-5e6d-a683-20cdf7b613b9', 'unit', 'informatik', 'Gymnasium', '12', NULL, 'DE-BY-LP-INF-inf12-spaet-informationssicherheit', 14, 'Informationssicherheit', 'Information security', NULL, 'Students weigh data-protection rules against personal and public interests, analyse an information system against the main security goals, describe threats, and explain protective measures with their limits.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/informatik/grundlegend-spaet', '{"unitNumber": "5", "hours": 6, "courseLevel": "basic", "topicTags": ["systems_networks", "media_society"]}', 'unit-records-195'),
  ('bba86828-a0dc-5761-b791-5f64d8f41f98', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ea-informationssicherheit', 'b52c2e60-e531-5e6d-a683-20cdf7b613b9', 'unit', 'informatik', 'Gymnasium', '12', NULL, 'DE-BY-LP-INF-inf12-eA-informationssicherheit', 15, 'Informationssicherheit', 'Information security', NULL, 'Students analyse an information system against the main security goals, describe threat categories and attack scenarios, explain protective measures with their limits, and discuss questions such as disclosing vulnerabilities.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/informatik/erhoeht', '{"unitNumber": "6", "hours": 6, "courseLevel": "advanced", "topicTags": ["systems_networks", "media_society"]}', 'unit-records-195'),
  ('be39d142-32b7-528c-8199-ff114737deda', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ga-softwareentwicklung-projekt', 'b52c2e60-e531-5e6d-a683-20cdf7b613b9', 'unit', 'informatik', 'Gymnasium', '12', NULL, 'DE-BY-LP-INF-inf12-gA-softwareentwicklung-projekt', 16, 'Praktische Softwareentwicklung, Projekt', 'Practical software development, project', NULL, 'Students use library classes and their documentation, explain the model-view-controller idea, test and refactor given software, compare the waterfall model with an agile model, and complete a team software project.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/informatik/grundlegend', '{"unitNumber": "6", "hours": 26, "courseLevel": "basic", "topicTags": ["algorithms_programming", "other"]}', 'unit-records-195'),
  ('ad6db279-5628-527b-b88c-e6e58c4588a0', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-spaet-softwareentwicklung-projekt', 'b52c2e60-e531-5e6d-a683-20cdf7b613b9', 'unit', 'informatik', 'Gymnasium', '12', NULL, 'DE-BY-LP-INF-inf12-spaet-softwareentwicklung-projekt', 17, 'Praktische Softwareentwicklung, Projekt', 'Practical software development, project', NULL, 'Students use library classes, for instance for a graphical interface, compare the waterfall model with an agile model, and complete a team software project on a simple practical task.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/informatik/grundlegend-spaet', '{"unitNumber": "6", "hours": 15, "courseLevel": "basic", "topicTags": ["algorithms_programming", "other"]}', 'unit-records-195'),
  ('843a5a20-9656-5c93-9aaa-9294aabd787e', 'germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ea-softwareentwicklung-projekt', 'b52c2e60-e531-5e6d-a683-20cdf7b613b9', 'unit', 'informatik', 'Gymnasium', '12', NULL, 'DE-BY-LP-INF-inf12-eA-softwareentwicklung-projekt', 18, 'Praktische Softwareentwicklung, Projekt', 'Practical software development, project', NULL, 'Students judge software quality and usability, design simple graphical interfaces, compare the waterfall model with agile methods, use design patterns and test and refactor code, and complete a team software project.', NULL, 'https://www.lehrplanplus.bayern.de/fachlehrplan/gymnasium/12/informatik/erhoeht', '{"unitNumber": "7", "hours": 40, "courseLevel": "advanced", "topicTags": ["algorithms_programming", "other"]}', 'unit-records-195'),
  ('f41f5220-aaa4-51cd-8e7e-446bcd0e7163', 'india-curriculum-repository', 'IN/computer-science/x/national-council-of-educational-research', NULL, 'edition', 'computer-science', NULL, NULL, NULL, NULL, 0, NULL, 'Computer science · NCERT', NULL, NULL, NULL, NULL, '{"units": 1, "edition": "National Council of Educational Research and Training (NCERT), under the Ministr"}', 'unit-records-195'),
  ('f0c72df3-6425-5a68-acd6-f5c910fe1441', 'india-curriculum-repository', 'IN/computer-science/x/national-council-of-educational-research/9-12', 'f41f5220-aaa4-51cd-8e7e-446bcd0e7163', 'grade_band', 'computer-science', NULL, '9-12', NULL, NULL, 9, NULL, 'Grade 9-12', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('f8786f77-a017-5de3-9c94-b476c6485c2a', 'india-curriculum-repository', 'IN/computer-science/x/national-council-of-educational-research/9-12/in-unit-ncert-ct-ai-module-grades-9-12-2026', 'f0c72df3-6425-5a68-acd6-f5c910fe1441', 'unit', 'computer-science', NULL, '9-12', NULL, 'IN-UNIT-ncert-ct-ai-module-grades-9-12-2026', 0, NULL, 'NCERT, Introductory Module on Computational Thinking and AI for the Secondary Stage (Classes 9 to 12), October 2026', NULL, 'NCERT''s introductory module of 20 class hours serves Classes 9 to 12 together. Its five units cover spotting AI in daily life, how machines learn from examples, how AI goes wrong, protecting personal data, and using AI tools with care. Students tell fixed-rule automation from learning systems, meet supervised, unsupervised and reinforcement learning, train a simple image classifier and try to break it, and learn that recognising a pattern differs from understanding it.', NULL, 'https://ncert.nic.in/pdf/An_Introductory_Module_AI_CT_UN514.pdf', '{"topicTags": ["artificial-intelligence", "machine-learning", "ai-ethics", "data-privacy", "verification", "unplugged"]}', 'unit-records-195'),
  ('dc1c232d-b146-5554-b91d-00f2c9d12b7d', 'india-curriculum-repository', 'IN/science/x/ncert', NULL, 'edition', 'science', NULL, NULL, NULL, NULL, 0, NULL, 'Science · NCERT', NULL, NULL, NULL, NULL, '{"units": 3, "edition": "NCERT"}', 'unit-records-195'),
  ('90c5a3c5-3474-5fb9-904a-e7985b833525', 'india-curriculum-repository', 'IN/science/x/ncert/6', 'dc1c232d-b146-5554-b91d-00f2c9d12b7d', 'grade_band', 'science', NULL, '6', NULL, NULL, 6, NULL, 'Grade 6', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('be307cdf-1c13-5308-8d21-a34818039512', 'india-curriculum-repository', 'IN/science/x/ncert/6/in-unit-ncert-curiosity-class-6-science-scientific-method-and-adaptati', '90c5a3c5-3474-5fb9-904a-e7985b833525', 'unit', 'science', NULL, '6', NULL, 'IN-UNIT-ncert-curiosity-class-6-science-scientific-method-and-adaptation', 0, NULL, 'scientific method, variation among living things, adaptation', NULL, 'Chapter 1 presents the scientific method as observing, wondering, guessing a cause, testing the guess and analysing the result, using a pen that stops writing as the example. Chapter 2 has pupils record differences among plants and animals on a nature walk and group them by shared features. It calls features that help living things survive in a place, such as a camel''s humps, adaptations, without saying how they arise.', NULL, 'https://ncert.nic.in/textbook/pdf/fecu102.pdf', '{"topicTags": ["class 6", "scientific method", "diversity of life", "grouping", "adaptation", "habitat"]}', 'unit-records-195'),
  ('3979d45e-13ce-5bf8-86c2-a2cb97c782e0', 'india-curriculum-repository', 'IN/science/x/ncert/8', 'dc1c232d-b146-5554-b91d-00f2c9d12b7d', 'grade_band', 'science', NULL, '8', NULL, NULL, 8, NULL, 'Grade 8', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('0e546cd1-c451-5f22-b134-123ac16b4f6a', 'india-curriculum-repository', 'IN/science/x/ncert/8/in-unit-ncert-curiosity-class-8-science-testing-ideas-and-genes-and-va', '3979d45e-13ce-5bf8-86c2-a2cb97c782e0', 'unit', 'science', NULL, '8', NULL, 'IN-UNIT-ncert-curiosity-class-8-science-testing-ideas-and-genes-and-variation', 0, NULL, 'testing ideas, antibiotic resistance, genes and variation', NULL, 'Chapter 13 tells pupils that genes pass instructions from parents to offspring, that reproduction can change those instructions slightly, and that over many generations such changes can add up to new kinds of living things. Camels and antibiotic-resistant bacteria are the examples. Chapter 1 teaches changing one factor at a time in an investigation, and Chapter 3 sets out Jenner''s smallpox work as observation, hypothesis, test and result.', NULL, 'https://ncert.nic.in/textbook/pdf/hecu113.pdf', '{"topicTags": ["class 8", "genes", "variation", "reproduction", "antibiotic resistance", "controlled investigation", "hypothesis"]}', 'unit-records-195'),
  ('30cc33bb-74fa-5f00-b868-7333c831ec70', 'india-curriculum-repository', 'IN/science/x/ncert/9', 'dc1c232d-b146-5554-b91d-00f2c9d12b7d', 'grade_band', 'science', NULL, '9', NULL, NULL, 9, NULL, 'Grade 9', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('ed12134e-d8b3-59c7-972c-4bc38a43e862', 'india-curriculum-repository', 'IN/science/x/ncert/9/in-unit-ncert-exploration-class-9-science-variation-and-biodiversity', '30cc33bb-74fa-5f00-b868-7333c831ec70', 'unit', 'science', NULL, '9', NULL, 'IN-UNIT-ncert-exploration-class-9-science-variation-and-biodiversity', 0, NULL, 'variation, adaptation and how biodiversity evolved', NULL, 'Section 12.2 says that slight differences between individuals changed how well each one survived and reproduced, and that these differences built up across many generations to produce new forms of life. Section 12.3 says similar features suggest descent from common ancestors, and section 12.7 links animal adaptations to changes in body structure. Chapter 11 says meiosis creates variation that helps some individuals adapt and, over time, contributes to evolution.', NULL, 'https://ncert.nic.in/textbook/pdf/iesc112.pdf', '{"topicTags": ["class 9", "variation", "meiosis", "adaptation", "common ancestry", "classification", "biodiversity"]}', 'unit-records-195'),
  ('8125c2ac-19f1-5f70-b6fd-11fe791a2971', 'india-curriculum-repository', 'IN/science/x/ncert-textbook-and-cbse-syllabus', NULL, 'edition', 'science', NULL, NULL, NULL, NULL, 0, NULL, 'Science · NCERT (textbook) and CBSE (syllabus)', NULL, NULL, NULL, NULL, '{"units": 2, "edition": "NCERT (textbook) and CBSE (syllabus)"}', 'unit-records-195'),
  ('7c6ff8e7-0721-582c-a889-95a88b7c5fc1', 'india-curriculum-repository', 'IN/science/x/ncert-textbook-and-cbse-syllabus/10', '8125c2ac-19f1-5f70-b6fd-11fe791a2971', 'grade_band', 'science', NULL, '10', NULL, NULL, 10, NULL, 'Grade 10', NULL, NULL, NULL, NULL, '{}', 'unit-records-195')
) AS v(id, project_slug, node_key, parent_id, level, subject, school_type, grade_band, edition_source_id, record_source_id, sort_order, label_de, label_en, summary_de, summary_en, source_pages, source_url, facts, origin)
JOIN projects p ON p.slug = v.project_slug
ON CONFLICT (project_id, node_key) DO NOTHING;

INSERT INTO curriculum_repository_structure_nodes (id, project_id, node_key, parent_id, level, subject, school_type, grade_band, edition_record_id, record_id, sort_order, label_de, label_en, summary_de, summary_en, source_pages, source_url, facts, access_tier, review_status, origin)
SELECT v.id::uuid, p.id, v.node_key, v.parent_id::uuid, v.level, v.subject, v.school_type, v.grade_band,
       (SELECT r.id FROM curriculum_repository_records r WHERE r.project_id = p.id AND r.source_record_id = v.edition_source_id),
       (SELECT r.id FROM curriculum_repository_records r WHERE r.project_id = p.id AND r.source_record_id = v.record_source_id),
       v.sort_order::integer, v.label_de, v.label_en, v.summary_de, v.summary_en, v.source_pages, v.source_url, v.facts::jsonb,
       'summary-only', 'ai-draft', v.origin
FROM (VALUES
  ('898aebe5-bff8-506f-b34e-1a458fc4a37f', 'india-curriculum-repository', 'IN/science/x/ncert-textbook-and-cbse-syllabus/10/in-unit-ncert-class-10-science-heredity-and-cbse-class-10-evolution-to', '7c6ff8e7-0721-582c-a889-95a88b7c5fc1', 'unit', 'science', NULL, '10', NULL, 'IN-UNIT-ncert-class-10-science-heredity-and-cbse-class-10-evolution-topics', 0, NULL, 'where evolution stands', NULL, 'NCERT''s Class 10 chapter Heredity covers variation arising in reproduction, Mendel''s rules, how traits are expressed and sex determination. It says selection of variants by the environment is the basis of evolution, then points to later sections that this edition does not have. CBSE''s 2026-27 Class 10 syllabus lists evolution topics such as speciation, fossils and human evolution as formatively assessed only.', NULL, 'https://ncert.nic.in/textbook/pdf/jesc108.pdf', '{"topicTags": ["class 10", "heredity", "mendel", "evolution", "rationalisation", "formative assessment"]}', 'unit-records-195'),
  ('ce7001fc-b248-569e-a909-0910ffc27e2f', 'india-curriculum-repository', 'IN/science/x/ncert-textbook-and-cbse-syllabus/12', '8125c2ac-19f1-5f70-b6fd-11fe791a2971', 'grade_band', 'science', NULL, '12', NULL, NULL, 12, NULL, 'Grade 12', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('aa3f83d7-527d-5c36-9079-e08307ccb8dc', 'india-curriculum-repository', 'IN/science/x/ncert-textbook-and-cbse-syllabus/12/in-unit-ncert-class-12-biology-evolution-chapter-and-cbse-unit-vii', 'ce7001fc-b248-569e-a909-0910ffc27e2f', 'unit', 'science', NULL, '12', NULL, 'IN-UNIT-ncert-class-12-biology-evolution-chapter-and-cbse-unit-vii', 0, NULL, 'NCERT Class 12 Biology, Chapter 6 Evolution, and the CBSE Class 12 Biology syllabus 2026-27, Unit VII', NULL, 'The NCERT Class 12 Biology book hosted for 2026-27 still has a 17-page Evolution chapter. It covers Darwin and Wallace, natural selection, adaptive radiation, the Hardy-Weinberg principle, gene flow, genetic drift, the founder effect, speciation and human evolution. CBSE''s 2026-27 Class 12 syllabus lists the chapter in Unit VII, Genetics and Evolution, which also holds the inheritance and molecular-basis chapters and is worth 20 of 70 theory marks.', NULL, 'https://ncert.nic.in/textbook/pdf/lebo106.pdf', '{"topicTags": ["class 12", "evolution", "natural selection", "hardy-weinberg", "genetic drift", "speciation", "darwin"]}', 'unit-records-195'),
  ('20586b34-8af0-5bd3-90dc-2392cdd337a3', 'india-curriculum-repository', 'IN/social-science/x/ncert', NULL, 'edition', 'social-science', NULL, NULL, NULL, NULL, 0, NULL, 'Social science · NCERT', NULL, NULL, NULL, NULL, '{"units": 5, "edition": "NCERT"}', 'unit-records-195'),
  ('fa5ef0d1-baaf-50c3-a571-2c15b946ac19', 'india-curriculum-repository', 'IN/social-science/x/ncert/6', '20586b34-8af0-5bd3-90dc-2392cdd337a3', 'grade_band', 'social-science', NULL, '6', NULL, NULL, 6, NULL, 'Grade 6', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('9891c192-76a4-5296-ad35-3ba8aa89d024', 'india-curriculum-repository', 'IN/social-science/x/ncert/6/in-unit-ncert-class6-unity-in-diversity', 'fa5ef0d1-baaf-50c3-a571-2c15b946ac19', 'unit', 'social-science', NULL, '6', NULL, 'IN-UNIT-ncert-class6-unity-in-diversity', 0, NULL, 'India and Beyond (Class 6), Chapter 8 on unity in diversity', NULL, 'The chapter asks what holds India together despite visible differences. Students list classmates'' birthplaces and languages, then look at shared threads in food grains, the sari in many forms, a harvest festival with different regional names, and the Panchatantra and the two epics retold in many languages and tribal traditions. It closes by saying diversity enriches the shared culture.', NULL, 'https://ncert.nic.in/textbook/pdf/fees108.pdf', '{"topicTags": ["unity in diversity", "culture", "languages", "festivals", "literature", "communities"]}', 'unit-records-195'),
  ('db9b370d-852f-5c33-a212-e4ff6c364c59', 'india-curriculum-repository', 'IN/social-science/x/ncert/6/in-unit-ncert-class6-family-and-community', 'fa5ef0d1-baaf-50c3-a571-2c15b946ac19', 'unit', 'social-science', NULL, '6', NULL, 'IN-UNIT-ncert-class6-family-and-community', 1, NULL, 'India and Beyond (Class 6), Chapter 9 Family and Community', NULL, 'Students study the family as a unit where members have roles and duties, cooperate and depend on each other, and compare family types near them. They then meet communities: groups of families that share festivals and, in many villages and tribal communities, long-standing unwritten rules on water, grazing land and forest produce that give each family duties. Residents'' welfare associations show people making their own rules. Questions ask which rules may be unfair.', NULL, 'https://ncert.nic.in/textbook/pdf/fees109.pdf', '{"topicTags": ["family", "community", "roles", "rules", "cooperation", "shared resources", "interdependence"]}', 'unit-records-195'),
  ('2a77d97c-d54b-5ab7-b8cb-16082ff9582b', 'india-curriculum-repository', 'IN/social-science/x/ncert/6/in-unit-ncert-class6-grassroots-democracy-governance-and-local-governm', 'fa5ef0d1-baaf-50c3-a571-2c15b946ac19', 'unit', 'social-science', NULL, '6', NULL, 'IN-UNIT-ncert-class6-grassroots-democracy-governance-and-local-government', 2, NULL, 'India and Beyond (Class 6), Chapters 10-12 Grassroots Democracy: governance and local government', NULL, 'Three chapters explain why larger groups need rules and who makes them. Students learn governance, government and laws, the three organs that make, carry out and judge laws, and the three levels of government. They then study village councils (Gram Sabha, Gram Panchayat, block and district bodies, one-third of seats reserved for women, children''s Bal Panchayats) and urban local bodies, and are asked how citizens can help them work.', NULL, 'https://ncert.nic.in/textbook/pdf/fees110.pdf', '{"topicTags": ["governance", "democracy", "rules and laws", "separation of powers", "panchayati raj", "local government", "citizen participation"]}', 'unit-records-195'),
  ('f4dc9756-f678-507f-8dc1-ee091047fe61', 'india-curriculum-repository', 'IN/social-science/x/ncert/8', '20586b34-8af0-5bd3-90dc-2392cdd337a3', 'grade_band', 'social-science', NULL, '8', NULL, NULL, 8, NULL, 'Grade 8', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('b349c952-26ee-5009-a49f-10b6b2ad8da0', 'india-curriculum-repository', 'IN/social-science/x/ncert/8/in-unit-ncert-class8-part2-judiciary-and-citizenship-rights-and-duties', 'f4dc9756-f678-507f-8dc1-ee091047fe61', 'unit', 'social-science', NULL, '8', NULL, 'IN-UNIT-ncert-class8-part2-judiciary-and-citizenship-rights-and-duties', 0, NULL, 'India and Beyond (Class 8 Part 2), Chapters 4 and 5: Judiciary; Citizenship, Rights and Duties', NULL, 'In the revised June 2026 edition, Chapter 4 explains justice, how courts are organised and other ways to settle disputes, such as mediation. Chapter 5 defines citizen, rights, duties, discrimination and inclusion, covers the six groups of Fundamental Rights, lists the Fundamental Duties with school examples, and uses a festival story and an equality versus equity picture to show why support may differ between people. It says rights are protected by law while duties are moral and social responsibilities.', NULL, 'https://ncert.nic.in/textbook/pdf/hees205.pdf', '{"topicTags": ["judiciary", "citizenship", "rights and duties", "discrimination", "inclusion", "equity", "dispute resolution"]}', 'unit-records-195'),
  ('b20669b1-5be9-5f79-90dc-e533a6bc96ca', 'india-curriculum-repository', 'IN/social-science/x/ncert/9', '20586b34-8af0-5bd3-90dc-2392cdd337a3', 'grade_band', 'social-science', NULL, '9', NULL, NULL, 9, NULL, 'Grade 9', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('51364213-5714-550c-bf15-c8c2a3066ac2', 'india-curriculum-repository', 'IN/social-science/x/ncert/9/in-unit-ncert-class9-governance-and-public-policy', 'b20669b1-5be9-5f79-90dc-e533a6bc96ca', 'unit', 'social-science', NULL, '9', NULL, 'IN-UNIT-ncert-class9-governance-and-public-policy', 0, NULL, 'India and Beyond (Class 9 Part 2), Chapter 4 Governance and Public Policy', NULL, 'The chapter separates government (the institutions) from governance (how decisions are made, carried out and checked). Students analyse a flood response in which municipal staff, police, health workers, schools and neighbours act together, learn features of good governance, study e-governance, and learn how public policy is made, with citizens, media, civil society and private bodies named as contributors. It also traces governance ideas from the Vedic period to the Constitution.', NULL, 'https://ncert.nic.in/textbook/pdf/iest204.pdf', '{"topicTags": ["governance", "public policy", "good governance", "e-governance", "citizen participation", "collective response"]}', 'unit-records-195'),
  ('53009f71-9f4a-5198-879a-f8c8c0b25b76', 'karnataka-curriculum-repository', 'IN-KA/science/x/karnataka-textbook-society-r-government', NULL, 'edition', 'science', NULL, NULL, NULL, NULL, 0, NULL, 'Science · Karnataka Textbook Society (R), Government of Karnataka', NULL, NULL, NULL, NULL, '{"units": 3, "edition": "Karnataka Textbook Society (R), Government of Karnataka"}', 'unit-records-195'),
  ('d1851456-9e8d-5602-9ff8-610a200c62a9', 'karnataka-curriculum-repository', 'IN-KA/science/x/karnataka-textbook-society-r-government/6', '53009f71-9f4a-5198-879a-f8c8c0b25b76', 'grade_band', 'science', NULL, '6', NULL, NULL, 6, NULL, 'Grade 6', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('ea13f026-5e73-564f-aaca-5d6e48cadd55', 'karnataka-curriculum-repository', 'IN-KA/science/x/karnataka-textbook-society-r-government/6/in-ka-unit-class6-science-habitats-and-adaptation', 'd1851456-9e8d-5602-9ff8-610a200c62a9', 'unit', 'science', NULL, '6', NULL, 'IN-KA-UNIT-class6-science-habitats-and-adaptation', 0, NULL, 'Characteristics and Habitats'' (2018-19)', NULL, 'Class 6 students learn that different places hold different living things, and that features such as a camel''s long legs or a fish''s streamlined body, scales and gills help an organism live in its habitat. The chapter calls such features adaptation, separates it from short-term acclimatisation, and says adaptation takes a long time. It also introduces land and water habitats and the living and non-living parts of a habitat.', NULL, 'https://cdn1.byjus.com/wp-content/uploads/2019/08/Karnataka-Board-Class-6-science-english-medium.pdf', '{"topicTags": ["adaptation", "habitat", "acclimatisation", "diversity-of-life"]}', 'unit-records-195'),
  ('bb47cc4b-7289-5c6a-9058-0f647650cc8d', 'karnataka-curriculum-repository', 'IN-KA/science/x/karnataka-textbook-society-r-government/8', '53009f71-9f4a-5198-879a-f8c8c0b25b76', 'grade_band', 'science', NULL, '8', NULL, NULL, 8, NULL, 'Grade 8', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('5cf844b0-45b6-5f2a-9cc9-ca930221c69a', 'karnataka-curriculum-repository', 'IN-KA/science/x/karnataka-textbook-society-r-government/8/in-ka-unit-class8-science-evolution-of-life', 'bb47cc4b-7289-5c6a-9058-0f647650cc8d', 'unit', 'science', NULL, '8', NULL, 'IN-KA-UNIT-class8-science-evolution-of-life', 0, NULL, 'Karnataka Textbook Society, Class 8 Science Part 2 (Revised), chapter 22 ''Evolution of life'' (pages 127 to 137)', NULL, 'Class 8 students meet a full chapter on evolution. It covers chemical evolution and the first cells, organic evolution as descent with change, Lamarck''s use-and-disuse idea and Weismann''s tail-cutting experiment against it, Darwin''s account of variation, overproduction, competition and natural selection, de Vries''s mutation idea, and neo-Darwinism as a combination with Mendel''s heredity.', NULL, 'https://cdn1.byjus.com/wp-content/uploads/2019/07/kseeb-Class-8-Science-Part-2.pdf', '{"topicTags": ["evolution", "natural-selection", "lamarck", "darwin", "mutation", "origin-of-life"]}', 'unit-records-195'),
  ('0fad859f-64a4-50cf-abbe-7ffb01491803', 'karnataka-curriculum-repository', 'IN-KA/science/x/karnataka-textbook-society-r-government/10', '53009f71-9f4a-5198-879a-f8c8c0b25b76', 'grade_band', 'science', NULL, '10', NULL, NULL, 10, NULL, 'Grade 10', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('2ff7b625-e680-54b2-987c-0659f1670be7', 'karnataka-curriculum-repository', 'IN-KA/science/x/karnataka-textbook-society-r-government/10/in-ka-unit-class10-science-heredity-and-evolution', '0fad859f-64a4-50cf-abbe-7ffb01491803', 'unit', 'science', NULL, '10', NULL, 'IN-KA-UNIT-class10-science-heredity-and-evolution', 0, NULL, 'Karnataka Textbook Society, Class 10 Science Part 2, chapter ''Heredity and Evolution'' (NCERT chapter 9, pages 52 to 69)', NULL, 'Class 10 students study how variation arises in reproduction and how traits pass from parents, using Mendel''s pea experiments, dominant and recessive traits and sex determination. The chapter then teaches evolution: a beetle example of natural selection and genetic drift, speciation by isolation, fossils, evolutionary trees, and the point that evolution does not mean progress. It states that all humans are one species with an African origin.', NULL, 'https://cdn1.byjus.com/wp-content/uploads/2022/09/KSEEB-Class-10-Science-Part-2-Textbook.pdf', '{"topicTags": ["heredity", "variation", "mendel", "natural-selection", "genetic-drift", "speciation", "fossils", "human-evolution"]}', 'unit-records-195'),
  ('6130e723-ae84-5c20-83f9-6d57b1754f36', 'karnataka-curriculum-repository', 'IN-KA/social-science/x/karnataka-textbook-society-r-government', NULL, 'edition', 'social-science', NULL, NULL, NULL, NULL, 0, NULL, 'Social science · Karnataka Textbook Society (R), Government of Karnataka', NULL, NULL, NULL, NULL, '{"units": 1, "edition": "Karnataka Textbook Society (R), Government of Karnataka"}', 'unit-records-195'),
  ('8f6cda67-d46b-5bca-9bd6-61412f56f218', 'karnataka-curriculum-repository', 'IN-KA/social-science/x/karnataka-textbook-society-r-government/8', '6130e723-ae84-5c20-83f9-6d57b1754f36', 'grade_band', 'social-science', NULL, '8', NULL, NULL, 8, NULL, 'Grade 8', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('13d6cb0b-69f8-5168-8ce9-24ede8da4cce', 'karnataka-curriculum-repository', 'IN-KA/social-science/x/karnataka-textbook-society-r-government/8/in-ka-unit-class8-social-science-sociology-social-institutions', '8f6cda67-d46b-5bca-9bd6-61412f56f218', 'unit', 'social-science', NULL, '8', NULL, 'IN-KA-UNIT-class8-social-science-sociology-social-institutions', 0, NULL, 'Karnataka Textbook Society, Class 8 Social Science (Revised Textbook), Sociology chapter 3 ''Social Institutions'' (pages 149 to 153)', NULL, 'Class 8 students learn that social institutions such as the family, marriage, the court and the school are lasting structures of roles and rules that meet human needs. The chapter says institutions have both written rules (courts, schools, governments) and unwritten ones (customs, traditions), depend on each other, carry culture across generations, give members roles by age, and correct breaches of their rules. It works through family, marriage and religion.', NULL, 'https://cdn1.byjus.com/wp-content/uploads/2020/01/KSEEB-Class-8-Social-Science-Textbook.pdf', '{"topicTags": ["social-institutions", "norms", "rules", "roles", "culture", "sociology"]}', 'unit-records-195'),
  ('c5401cd8-4f9c-556f-8d36-88877e17e53e', 'kerala-school-curriculum-repository', 'IN-KL/computer-science/x/state-council-of-educational-research-an', NULL, 'edition', 'computer-science', NULL, NULL, NULL, NULL, 0, NULL, 'Computer science · SCERT', NULL, NULL, NULL, NULL, '{"units": 2, "edition": "State Council of Educational Research and Training (SCERT) Kerala, textbooks pre"}', 'unit-records-195'),
  ('9e688d02-6291-54fa-96dc-a78b3e97bd5c', 'kerala-school-curriculum-repository', 'IN-KL/computer-science/x/state-council-of-educational-research-an/1-7', 'c5401cd8-4f9c-556f-8d36-88877e17e53e', 'grade_band', 'computer-science', NULL, '1-7', NULL, NULL, 1, NULL, 'Grade 1-7', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('7bfc63de-5cdd-547a-8aba-ecedd046b112', 'kerala-school-curriculum-repository', 'IN-KL/computer-science/x/state-council-of-educational-research-an/1-7/in-kl-unit-ict-textbooks-classes-1-to-7-logic-games-scratch-spreadshee', '9e688d02-6291-54fa-96dc-a78b3e97bd5c', 'unit', 'computer-science', NULL, '1-7', NULL, 'IN-KL-UNIT-ict-textbooks-classes-1-to-7-logic-games-scratch-spreadsheets-vision', 0, NULL, 'logic games, Scratch, spreadsheets, vision', NULL, 'The ICT textbooks for Classes 1 to 4 are built around GCompris and similar games for logic, sorting, pattern and number work. Class 4 adds a first short Scratch activity. Class 5 draws patterns with a forever loop, Class 6 builds a game with conditions and introduces spreadsheets, and Class 7 makes spreadsheet charts and uses a ready-made AI model that detects facial expressions.', NULL, 'https://samagra.kite.kerala.gov.in/#/textbook/page/', '{"topicTags": ["ict", "scratch", "block-coding", "spreadsheets", "charts", "computer-vision", "games"]}', 'unit-records-195'),
  ('6c7f0687-73ff-5985-8dc5-3ad949227651', 'kerala-school-curriculum-repository', 'IN-KL/computer-science/x/state-council-of-educational-research-an/8-10', 'c5401cd8-4f9c-556f-8d36-88877e17e53e', 'grade_band', 'computer-science', NULL, '8-10', NULL, NULL, 8, NULL, 'Grade 8-10', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('c56b6880-ff1e-5ee3-b93a-81d68e878de7', 'kerala-school-curriculum-repository', 'IN-KL/computer-science/x/state-council-of-educational-research-an/8-10/in-kl-unit-ict-textbooks-classes-8-to-10-machine-learning-python-datab', '6c7f0687-73ff-5985-8dc5-3ad949227651', 'unit', 'computer-science', NULL, '8-10', NULL, 'IN-KL-UNIT-ict-textbooks-classes-8-to-10-machine-learning-python-databases-robotics', 0, NULL, 'machine learning, AI, Python, databases, robotics', NULL, 'The 2025 ICT textbooks for Classes 8 to 10 teach how a computer learns to classify images from labelled examples (Class 8), AI, language models and responsible use (Class 9), and Python programs, database tables and Arduino robotics (Class 10). Classes 8 and 9 also teach spreadsheet data analysis. The books describe AI as imitating human intelligence.', NULL, 'https://samagra.kite.kerala.gov.in/#/textbook/page/', '{"topicTags": ["machine-learning", "artificial-intelligence", "python", "databases", "robotics", "spreadsheets", "responsible-ai"]}', 'unit-records-195'),
  ('875405a9-d6b5-5b88-afd6-fd39f087fa31', 'kerala-school-curriculum-repository', 'IN-KL/science/x/state-council-of-educational-research-an', NULL, 'edition', 'science', NULL, NULL, NULL, NULL, 0, NULL, 'Science · SCERT', NULL, NULL, NULL, NULL, '{"units": 5, "edition": "State Council of Educational Research and Training (SCERT) Kerala, Department of"}', 'unit-records-195'),
  ('148ceeb9-c9c8-58f8-baee-3daf26474d7f', 'kerala-school-curriculum-repository', 'IN-KL/science/x/state-council-of-educational-research-an/5-7', '875405a9-d6b5-5b88-afd6-fd39f087fa31', 'grade_band', 'science', NULL, '5-7', NULL, NULL, 5, NULL, 'Grade 5-7', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('9dfbd6c2-61f5-5d19-a7d4-410aab95dfc4', 'kerala-school-curriculum-repository', 'IN-KL/science/x/state-council-of-educational-research-an/5-7/in-kl-unit-scert-kerala-class5-and-class7-basic-science-diverse-organi', '148ceeb9-c9c8-58f8-baee-3daf26474d7f', 'unit', 'science', NULL, '5-7', NULL, 'IN-KL-UNIT-scert-kerala-class5-and-class7-basic-science-diverse-organisms-and-hybridization-2024', 0, NULL, 'diverse organisms, hybridization', NULL, 'In Class 5, Diverse Organisms covers life cycles, how fish and tadpoles are adapted to water, groups of animals sorted by body features, and creatures that have become extinct. In Class 7, a chapter on better yields teaches grafting, budding and hybridization, in which two varieties are crossed by hand pollination to produce seeds with chosen qualities.', NULL, 'https://scert.kerala.gov.in/textbook2024part2/', '{"topicTags": ["adaptation", "extinction", "classification of animals", "hybridization", "plant breeding", "life cycles"]}', 'unit-records-195'),
  ('77968cb8-e1d9-5b2f-a1b0-7a41e5781b63', 'kerala-school-curriculum-repository', 'IN-KL/science/x/state-council-of-educational-research-an/8', '875405a9-d6b5-5b88-afd6-fd39f087fa31', 'grade_band', 'science', NULL, '8', NULL, NULL, 8, NULL, 'Grade 8', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('6b7c82d3-3283-5324-8e34-ad9941be1b6d', 'kerala-school-curriculum-repository', 'IN-KL/science/x/state-council-of-educational-research-an/8/in-kl-unit-scert-kerala-class8-basic-science-origin-of-life-and-divers', '77968cb8-e1d9-5b2f-a1b0-7a41e5781b63', 'unit', 'science', NULL, '8', NULL, 'IN-KL-UNIT-scert-kerala-class8-basic-science-origin-of-life-and-diversity-2025', 0, NULL, 'origin of life, tree of life, biodiversity', NULL, 'Chapter 8 introduces evolution as change in living things linked to changes in their surroundings, using a fossil whale ancestor, two theories of the origin of life and a timeline. Chapter 16 covers the history of classification and says modern classification uses evolutionary and genetic relationships. Chapter 17 covers biodiversity at three levels: variation within a species, species, and ecosystems.', NULL, 'https://scert.kerala.gov.in/2-8-tb/', '{"topicTags": ["evolution", "origin of life", "classification", "biodiversity", "adaptation", "deep time"]}', 'unit-records-195'),
  ('b68661ad-2fd0-5032-bae3-69481e7cdf63', 'kerala-school-curriculum-repository', 'IN-KL/science/x/state-council-of-educational-research-an/9', '875405a9-d6b5-5b88-afd6-fd39f087fa31', 'grade_band', 'science', NULL, '9', NULL, NULL, 9, NULL, 'Grade 9', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('daf84de6-ece0-5ab1-b75b-2799d6391903', 'kerala-school-curriculum-repository', 'IN-KL/science/x/state-council-of-educational-research-an/9/in-kl-unit-scert-kerala-class9-biology-evolution-evidence-and-classifi', 'b68661ad-2fd0-5032-bae3-69481e7cdf63', 'unit', 'science', NULL, '9', NULL, 'IN-KL-UNIT-scert-kerala-class9-biology-evolution-evidence-and-classification-2024', 0, NULL, 'evolution in ''Behind Movements'' and Chapter 6 Classification', NULL, 'A short section in the movement chapter says the picture of evolution is built from genetics, embryology and fossils, and uses body frameworks, bipedal walking and ancient DNA as examples. Chapter 6 on classification covers the three-domain system, how an evolutionary tree is drawn from shared features (pupils analyse a given tree), and DNA barcoding.', NULL, 'https://scert.kerala.gov.in/textbook2024part2/', '{"topicTags": ["evolution", "fossils", "evolutionary tree", "classification", "DNA barcoding", "evidence"]}', 'unit-records-195'),
  ('d77fc03d-1e24-5841-80bd-8a8859a84778', 'kerala-school-curriculum-repository', 'IN-KL/science/x/state-council-of-educational-research-an/10', '875405a9-d6b5-5b88-afd6-fd39f087fa31', 'grade_band', 'science', NULL, '10', NULL, NULL, 10, NULL, 'Grade 10', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('7f3144bb-e7ab-5eed-9060-1d1a81794dd6', 'kerala-school-curriculum-repository', 'IN-KL/science/x/state-council-of-educational-research-an/10/in-kl-unit-scert-kerala-class10-biology-genetics-of-life-2025', 'd77fc03d-1e24-5841-80bd-8a8859a84778', 'unit', 'science', NULL, '10', NULL, 'IN-KL-UNIT-scert-kerala-class10-biology-genetics-of-life-2025', 0, NULL, 'DNA, Mendel and sources of variation', NULL, 'Chapter 1 teaches the structure of DNA, chromosomes, genes and RNA, and how proteins are made. It then explains heredity and variation through Mendel''s pea experiments, alleles, monohybrid and dihybrid crosses, and patterns that depart from Mendel''s, such as incomplete dominance and multiple alleles. It names crossing over and mutation as sources of variation and says mutation matters in evolution.', NULL, 'https://scert.kerala.gov.in/class-x/', '{"topicTags": ["heredity", "variation", "genes", "alleles", "Mendel", "mutation", "crossing over", "non-Mendelian inheritance"]}', 'unit-records-195'),
  ('c0638056-ff9e-519e-9b13-952b4ab1b21f', 'kerala-school-curriculum-repository', 'IN-KL/science/x/state-council-of-educational-research-an/10/in-kl-unit-scert-kerala-class10-biology-paths-of-evolution-2025', 'd77fc03d-1e24-5841-80bd-8a8859a84778', 'unit', 'science', NULL, '10', NULL, 'IN-KL-UNIT-scert-kerala-class10-biology-paths-of-evolution-2025', 1, NULL, 'resistance, Lamarck, Darwin, speciation', NULL, 'Chapter 2 opens with a tuberculosis case in which resistant bacteria arose by mutation, then compares Lamarck''s and Darwin''s accounts of the giraffe''s neck and sets out natural selection with the Galapagos finches. It adds later genetic findings, explains speciation by isolation, gives molecular, anatomical and fossil evidence, and presents the human evolutionary tree. The second half of the chapter covers the nervous system.', NULL, 'https://scert.kerala.gov.in/class-x/', '{"topicTags": ["evolution", "natural selection", "Lamarck", "Darwin", "speciation", "fossils", "antibiotic resistance", "human evolution"]}', 'unit-records-195'),
  ('0ef355a6-59b2-54b8-acba-49a1444e0856', 'kerala-school-curriculum-repository', 'IN-KL/science/x/text-of-ncert-s-earlier-16-chapter-class', NULL, 'edition', 'science', NULL, NULL, NULL, NULL, 0, NULL, 'Science · Text of NCERT''s earlier 16-chapter Class 12 Biology book,...', NULL, NULL, NULL, NULL, '{"units": 1, "edition": "Text of NCERT''s earlier 16-chapter Class 12 Biology book, hosted on the Kerala S"}', 'unit-records-195'),
  ('f0b4984e-ac71-5341-a48e-109c48a753da', 'kerala-school-curriculum-repository', 'IN-KL/science/x/text-of-ncert-s-earlier-16-chapter-class/12', '0ef355a6-59b2-54b8-acba-49a1444e0856', 'grade_band', 'science', NULL, '12', NULL, NULL, 12, NULL, 'Grade 12', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('4ec842b1-302a-54ab-bcac-ba10c2c7a36b', 'kerala-school-curriculum-repository', 'IN-KL/science/x/text-of-ncert-s-earlier-16-chapter-class/12/in-kl-unit-samagra-kerala-class12-biology-file-inheritance-and-evoluti', 'f0b4984e-ac71-5341-a48e-109c48a753da', 'unit', 'science', NULL, '12', NULL, 'IN-KL-UNIT-samagra-kerala-class12-biology-file-inheritance-and-evolution', 0, NULL, 'Class XII Biology file listed for Botany and Zoology, chapters on inheritance, DNA and Evolution', NULL, 'A 286-page Class XII Biology file on Kerala''s Samagra portal covers Mendel''s laws, mutation and genetic disorders (Chapter 5), the molecular basis of inheritance (Chapter 6) and Evolution (Chapter 7). Chapter 7 covers origin of life, evidence, adaptive radiation, natural selection, the Hardy-Weinberg principle with five factors that change allele frequencies, and human origins.', NULL, 'https://samagra.kite.kerala.gov.in/files/samagra-resource/uploads/tbookscmq/Class_XII/Biology/Biology.pdf', '{"topicTags": ["evolution", "Hardy-Weinberg", "allele frequency", "genetic drift", "natural selection", "inheritance", "adaptive radiation"]}', 'unit-records-195'),
  ('c106b764-1748-550f-8dcd-2205d55881b6', 'kerala-school-curriculum-repository', 'IN-KL/social-science/x/state-council-of-educational-research-an', NULL, 'edition', 'social-science', NULL, NULL, NULL, NULL, 0, NULL, 'Social science · SCERT', NULL, NULL, NULL, NULL, '{"units": 4, "edition": "State Council of Educational Research and Training (SCERT) Kerala, Department of"}', 'unit-records-195'),
  ('246b9b6d-b3f0-5084-a4fc-16f6dc5ce8b6', 'kerala-school-curriculum-repository', 'IN-KL/social-science/x/state-council-of-educational-research-an/5-7', 'c106b764-1748-550f-8dcd-2205d55881b6', 'grade_band', 'social-science', NULL, '5-7', NULL, NULL, 5, NULL, 'Grade 5-7', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('df11ddbb-9dcf-5a33-aa6a-11f209dcf8c8', 'kerala-school-curriculum-repository', 'IN-KL/social-science/x/state-council-of-educational-research-an/5-7/in-kl-unit-scert-classes5-7-social-science-rules-law-state-constitutio', '246b9b6d-b3f0-5084-a4fc-16f6dc5ce8b6', 'unit', 'social-science', NULL, '5-7', NULL, 'IN-KL-UNIT-scert-classes5-7-social-science-rules-law-state-constitution-and-culture', 0, NULL, 'rules and law, state, Constitution, culture, justice', NULL, 'Class 5 teaches game and school rules, law as the accepted rules of a society, and two sources of law: unwritten social norms, and legislatures and courts. Class 6 defines the state and government with its three organs, explains culture as learnt, shared and changing, and introduces the Constitution and its Preamble. Class 7 covers how the Constitution was made, its main features, marginalisation and the struggles for justice, and a chapter on discrimination set in South Africa.', NULL, 'https://samagra.kite.kerala.gov.in/#/textbook/page/', '{"topicTags": ["rules and laws", "social norms", "state and government", "constitution", "preamble", "culture", "socialisation", "marginalisation", "democracy"]}', 'unit-records-195'),
  ('4fa48043-a42d-5148-a075-4146b15e5e5c', 'kerala-school-curriculum-repository', 'IN-KL/social-science/x/state-council-of-educational-research-an/5-10', 'c106b764-1748-550f-8dcd-2205d55881b6', 'grade_band', 'social-science', NULL, '5-10', NULL, NULL, 5, NULL, 'Grade 5-10', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('7a44dfb0-43db-510e-ae5c-6387740fb54f', 'kerala-school-curriculum-repository', 'IN-KL/social-science/x/state-council-of-educational-research-an/5-10/in-kl-unit-scert-classes5-10-social-science-local-government-peoples-p', '4fa48043-a42d-5148-a075-4146b15e5e5c', 'unit', 'social-science', NULL, '5-10', NULL, 'IN-KL-UNIT-scert-classes5-10-social-science-local-government-peoples-planning-and-cooperative-institutions', 0, NULL, 'grama sabhas, People''s Planning, Kudumbashree and cooperative institutions', NULL, 'Class 5 introduces grama sabhas and the local self-government bodies. Class 7 teaches decentralisation, the 73rd and 74th Amendments, Kerala''s People''s Planning from 1996 as the book dates it, and the limits local bodies face, with a class sabha role play. Kudumbashree appears in Classes 5, 7, 8 and 10, co-operative banks in Classes 6 and 10, and farmers'' associations and cooperative credit societies in Class 8.', NULL, 'https://samagra.kite.kerala.gov.in/#/textbook/page/', '{"topicTags": ["local self-government", "grama sabha", "people''s planning", "decentralisation", "kudumbashree", "cooperative banks", "farmers'' groups", "land reform"]}', 'unit-records-195'),
  ('96c2b3eb-8567-5e50-894a-aeb0fb2e10fb', 'kerala-school-curriculum-repository', 'IN-KL/social-science/x/state-council-of-educational-research-an/8-10', 'c106b764-1748-550f-8dcd-2205d55881b6', 'grade_band', 'social-science', NULL, '8-10', NULL, NULL, 8, NULL, 'Grade 8-10', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('a6b30d75-31e0-5557-b4d2-7f839fcb2c2f', 'kerala-school-curriculum-repository', 'IN-KL/social-science/x/state-council-of-educational-research-an/8-10/in-kl-unit-scert-classes8-10-social-science-rights-democracy-instituti', '96c2b3eb-8567-5e50-894a-aeb0fb2e10fb', 'unit', 'social-science', NULL, '8-10', NULL, 'IN-KL-UNIT-scert-classes8-10-social-science-rights-democracy-institutions-and-movements', 0, NULL, 'rights, democracy, institutions, public opinion, movements', NULL, 'Class 8 covers fundamental rights and duties, media, and democracy with its forms, parties and basic values. Class 9 covers how the Constitution divides power and how bodies such as the Election Commission and human rights commissions extend democracy. Class 10 covers public opinion, politics in India after independence including the Emergency, and movements by backward-class, Dalit and women''s groups.', NULL, 'https://samagra.kite.kerala.gov.in/#/textbook/page/', '{"topicTags": ["fundamental rights", "democracy", "federalism", "election commission", "public opinion", "political parties", "popular movements", "media"]}', 'unit-records-195'),
  ('64a6b3a6-0d35-555f-adcc-071c89da55a4', 'kerala-school-curriculum-repository', 'IN-KL/social-science/x/state-council-of-educational-research-an/9-10', 'c106b764-1748-550f-8dcd-2205d55881b6', 'grade_band', 'social-science', NULL, '9/10', NULL, NULL, 9, NULL, 'Grade 9/10', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('75af26ad-c540-53ad-9ee6-9dd4961e6fd4', 'kerala-school-curriculum-repository', 'IN-KL/social-science/x/state-council-of-educational-research-an/9-10/in-kl-unit-scert-classes9-10-social-science-roles-norms-stratification', '64a6b3a6-0d35-555f-adcc-071c89da55a4', 'unit', 'social-science', NULL, '9/10', NULL, 'IN-KL-UNIT-scert-classes9-10-social-science-roles-norms-stratification-and-social-institutions', 0, NULL, 'gender roles and norms, sociological imagination, social institutions', NULL, 'Class 9 teaches status and role, social stratification, the difference between laws and unwritten social norms, and gender stereotypes. Class 10 introduces sociological imagination to tell personal problems from social causes. It then treats social institutions as parts of a social system that regulate behaviour, with the caste system and religion as worked cases.', NULL, 'https://samagra.kite.kerala.gov.in/#/textbook/page/', '{"topicTags": ["social norms", "gender roles", "stereotypes", "social stratification", "sociological imagination", "social institutions", "social control", "caste system"]}', 'unit-records-195'),
  ('dc32567b-63eb-5017-bdbc-44bbff8c217e', 'maharashtra-curriculum-repository', 'IN-MH/science/x/maharashtra-state-bureau-of-textbook-pro', NULL, 'edition', 'science', NULL, NULL, NULL, NULL, 0, NULL, 'Science · Maharashtra State Bureau of Textbook Production and Curri...', NULL, NULL, NULL, NULL, '{"units": 2, "edition": "Maharashtra State Bureau of Textbook Production and Curriculum Research (Balbhar"}', 'unit-records-195'),
  ('000bedc4-1208-50b7-8ab9-9fe0f7798acb', 'maharashtra-curriculum-repository', 'IN-MH/science/x/maharashtra-state-bureau-of-textbook-pro/7', 'dc32567b-63eb-5017-bdbc-44bbff8c217e', 'grade_band', 'science', NULL, '7', NULL, NULL, 7, NULL, 'Grade 7', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('4a9c40f7-2302-55bc-a2f0-7fe94a40975f', 'maharashtra-curriculum-repository', 'IN-MH/science/x/maharashtra-state-bureau-of-textbook-pro/7/in-mh-unit-balbharati-general-science-class-7-living-world-adaptations', '000bedc4-1208-50b7-8ab9-9fe0f7798acb', 'unit', 'science', NULL, '7', NULL, 'IN-MH-UNIT-balbharati-general-science-class-7-living-world-adaptations-and-classification', 0, NULL, 'Adaptations and Classification'' (2017, reprint 2022)', NULL, 'A nine-page chapter for Class 7. It defines adaptation as gradual changes in the organs and behaviour of organisms that help them live in their habitat, gives examples from plants and animals, and has a short box on Darwin''s survival of the fittest and natural selection. The second half teaches the classification hierarchy and two-part scientific names.', NULL, 'https://ebooks.ebalbharati.in/pdfs/703020012.pdf', '{"topicTags": ["adaptation", "diversity-of-life", "classification", "binomial-nomenclature", "natural-selection", "habitat"]}', 'unit-records-195'),
  ('ad087adc-6083-5874-b3e6-8f625e192a7f', 'maharashtra-curriculum-repository', 'IN-MH/science/x/maharashtra-state-bureau-of-textbook-pro/10', 'dc32567b-63eb-5017-bdbc-44bbff8c217e', 'grade_band', 'science', NULL, '10', NULL, NULL, 10, NULL, 'Grade 10', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('066823d4-dec9-5fce-a84a-b5fe068bb5fa', 'maharashtra-curriculum-repository', 'IN-MH/science/x/maharashtra-state-bureau-of-textbook-pro/10/in-mh-unit-balbharati-science-technology-class-10-part-2-heredity-and', 'ad087adc-6083-5874-b3e6-8f625e192a7f', 'unit', 'science', NULL, '10', NULL, 'IN-MH-UNIT-balbharati-science-technology-class-10-part-2-heredity-and-evolution', 0, NULL, 'Balbharati, Science and Technology Std X Part 2, Chapter 1 ''Heredity and Evolution'' (2018, reprint 2022)', NULL, 'An 11-page chapter for Class 10. It covers heredity (a one-sentence mention of Mendel, then DNA, how genes make proteins, and mutation), the idea of gradual evolution, six kinds of evidence (body form, bone structure, vestigial organs, fossils, connecting links, embryos), Darwin''s natural selection, Lamarck''s use and disuse, speciation through isolation, and the stages of human evolution.', NULL, 'https://ebooks.ebalbharati.in/pdfs/1003000270.pdf', '{"topicTags": ["heredity", "mutation", "evolution", "natural-selection", "darwin", "lamarck", "speciation", "human-evolution", "fossils"]}', 'unit-records-195'),
  ('599cf581-79d0-560a-8e82-d108fe0dac9e', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa', NULL, 'edition', 'biologie', 'Gymnasium', NULL, NULL, NULL, 0, 'Biologie, Gymnasium · Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022)', 'Biology, Gymnasium · Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022)', NULL, NULL, NULL, NULL, '{"units": 13, "edition": "Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022)"}', 'unit-records-195'),
  ('732e8b28-12de-51b3-8227-88a2848f2bb0', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/5-6', '599cf581-79d0-560a-8e82-d108fe0dac9e', 'grade_band', 'biologie', 'Gymnasium', '5/6', NULL, NULL, 5, 'Klassenstufe 5/6', 'Grade 5/6', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('31b1d77a-6404-5d92-af08-aee0e563feb3', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/5-6/de-st-lp-bio-sjg5-6-angepasstheit-wirbeltiere', '732e8b28-12de-51b3-8227-88a2848f2bb0', 'unit', 'biologie', 'Gymnasium', '5/6', NULL, 'DE-ST-LP-BIO-sjg5-6-angepasstheit-wirbeltiere', 0, 'Angepasstheit der Wirbeltiere an Lebensweise und Lebensraum erläutern', 'Explain the adaptedness of vertebrates to their way of life and habitat', NULL, 'Students compare how the body structure of vertebrates suits their way of life and habitat, sort animals into vertebrate classes by typical features, and follow relatedness between two classes. Model experiments and dissection (hands-on or on screen) are required.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf', '{"topicTags": ["selection_adaptation", "diversity_systematics"]}', 'unit-records-195'),
  ('fb2cf013-427c-53af-a00d-a04f2fcbe346', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/7-8', '599cf581-79d0-560a-8e82-d108fe0dac9e', 'grade_band', 'biologie', 'Gymnasium', '7/8', NULL, NULL, 7, 'Klassenstufe 7/8', 'Grade 7/8', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('fe3e3320-e218-5360-8ac9-ab7df42ea9f8', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/7-8/de-st-lp-bio-sjg7-8-angepasstheit-wirbellose', 'fb2cf013-427c-53af-a00d-a04f2fcbe346', 'unit', 'biologie', 'Gymnasium', '7/8', NULL, 'DE-ST-LP-BIO-sjg7-8-angepasstheit-wirbellose', 0, 'Angepasstheit von wirbellosen Tieren an Lebensweise und Lebensraum erläutern', 'Explain the adaptedness of invertebrates to their way of life and habitat', NULL, 'Students explain the variety of invertebrates as a result of adaptation to way of life and habitat, assign animals to groups by their features, and link insect population growth to environmental conditions. Simple behavior experiments and an excursion are part of it.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf', '{"topicTags": ["selection_adaptation", "diversity_systematics", "ecology_populations"]}', 'unit-records-195'),
  ('96cb490b-5d00-504f-976e-654ed4d6472a', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/9', '599cf581-79d0-560a-8e82-d108fe0dac9e', 'grade_band', 'biologie', 'Gymnasium', '9', NULL, NULL, 9, 'Klassenstufe 9', 'Grade 9', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('dbe45eda-24dd-55ac-b37a-0feb379927f4', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/9/de-st-lp-bio-sjg9-oekosystem-wald', '96cb490b-5d00-504f-976e-654ed4d6472a', 'unit', 'biologie', 'Gymnasium', '9', NULL, 'DE-ST-LP-BIO-sjg9-oekosystem-wald', 0, 'Wechselwirkungen zwischen Organismen untereinander und mit ihrer Umwelt im Ökosystem Wald erläutern', 'Explain the interactions among organisms and with their environment in the forest ecosystem', NULL, 'Students describe the forest ecosystem: biotic and abiotic factors, tolerance ranges, adaptation of plants to light and of animals to temperature, relationships between species, populations and food webs. They evaluate human impact, invasive species and sustainability.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf', '{"topicTags": ["ecology_populations", "selection_adaptation"]}', 'unit-records-195'),
  ('a01529ce-2cdb-5306-abac-1020c6ee4017', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/9/de-st-lp-bio-sjg9-mensch-umwelt-reiz-verhalten', '96cb490b-5d00-504f-976e-654ed4d6472a', 'unit', 'biologie', 'Gymnasium', '9', NULL, 'DE-ST-LP-BIO-sjg9-mensch-umwelt-reiz-verhalten', 1, 'Wechselwirkungen zwischen Mensch und Umwelt darstellen', 'Present the interactions between humans and their environment', NULL, 'Students connect stimulus and response in organisms, compare nervous systems and sense organs, and run behavior experiments, including explaining behavior as adapted to circumstances. Human brain function, addiction, stress and the nerve-hormone link complete the unit.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf', '{"topicTags": ["behavior_cognition", "human_biology"]}', 'unit-records-195'),
  ('16e39a5c-b27a-5920-ae61-c18f43b49ba9', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/10', '599cf581-79d0-560a-8e82-d108fe0dac9e', 'grade_band', 'biologie', 'Gymnasium', '10', NULL, NULL, 10, 'Klassenstufe 10', 'Grade 10', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('3c0c63e5-218c-5d33-a23a-69f022f22121', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/10/de-st-lp-bio-sjg10-evolution', '16e39a5c-b27a-5920-ae61-c18f43b49ba9', 'unit', 'biologie', 'Gymnasium', '10', NULL, 'DE-ST-LP-BIO-sjg10-evolution', 0, 'Biologische Phänomene auf der Grundlage der Evolution interpretieren', 'Interpret biological phenomena on the basis of evolution', NULL, 'Students interpret biological phenomena through evolution: variation and selection as the mechanism, evidence from fossils and homologous organs, relatedness of humans and apes, and the difference between ultimate and proximate explanations. They also weigh scientific against non-scientific views such as creationism.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf', '{"topicTags": ["evolution", "selection_adaptation", "nature_of_science"]}', 'unit-records-195'),
  ('52444b1d-9b71-5218-b973-2f1ad23544d6', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/10/de-st-lp-bio-sjg10-vererbung', '16e39a5c-b27a-5920-ae61-c18f43b49ba9', 'unit', 'biologie', 'Gymnasium', '10', NULL, 'DE-ST-LP-BIO-sjg10-vererbung', 1, 'Vererbungsvorgänge als Merkmal des Lebens darstellen und deren Gesetzmäßigkeiten anwenden', 'Present inheritance processes as a feature of life and apply their regularities', NULL, 'Students explain how traits are inherited and how variation arises through recombination, mutation and modification, and apply Mendel''s rules to breeding and to human traits. Selective breeding is compared with genetic engineering, and ethical questions of gene technology are discussed.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf', '{"topicTags": ["inheritance_variation"]}', 'unit-records-195'),
  ('b5c56b48-3c8d-574a-96d6-84e67102f895', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12', '599cf581-79d0-560a-8e82-d108fe0dac9e', 'grade_band', 'biologie', 'Gymnasium', '11/12', NULL, NULL, 11, 'Klassenstufe 11/12', 'Grade 11/12', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('f07d260f-9691-5cd4-9293-1a63a78ac362', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12/de-st-lp-bio-sjg11-12-gan-dna-zum-merkmal', 'b5c56b48-3c8d-574a-96d6-84e67102f895', 'unit', 'biologie', 'Gymnasium', '11/12', NULL, 'DE-ST-LP-BIO-sjg11-12-gan-dna-zum-merkmal', 0, 'Von der DNA zum Merkmal – Konstanz und Variabilität der genetischen Information interpretieren', 'From DNA to trait: interpret constancy and variability of genetic information', NULL, 'Students link DNA structure, replication and protein synthesis to traits, compare genetic and environmental variation in the light of biodiversity and evolution, and analyse inheritance with pedigrees and crosses. Gene tests, gene therapy and stem cells are discussed with ethical criteria.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf', '{"courseLevel": "basic", "topicTags": ["inheritance_variation"]}', 'unit-records-195'),
  ('8578d757-eb17-5f8b-b8a6-c0a253c7d962', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12/de-st-lp-bio-sjg11-12-ean-dna-zum-merkmal', 'b5c56b48-3c8d-574a-96d6-84e67102f895', 'unit', 'biologie', 'Gymnasium', '11/12', NULL, 'DE-ST-LP-BIO-sjg11-12-ean-dna-zum-merkmal', 1, 'Von der DNA zum Merkmal – Konstanz und Variabilität der genetischen Information interpretieren', 'From DNA to trait: interpret constancy and variability of genetic information', NULL, 'Students cover DNA structure, replication, protein synthesis, epigenetic regulation, telomeres, cancer genes, CRISPR/Cas9 and other gene technology tools, and DNA fingerprinting. They compare genetic and environmental variation for biodiversity and evolution and evaluate uses of human genetics.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf', '{"courseLevel": "advanced", "topicTags": ["inheritance_variation"]}', 'unit-records-195'),
  ('4e8d3610-7d40-5741-91aa-452a867cfccc', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12/de-st-lp-bio-sjg11-12-gan-umweltfaktor-oekosystem', 'b5c56b48-3c8d-574a-96d6-84e67102f895', 'unit', 'biologie', 'Gymnasium', '11/12', NULL, 'DE-ST-LP-BIO-sjg11-12-gan-umweltfaktor-oekosystem', 2, 'Vom Umweltfaktor zum Ökosystem – Variabilität und Angepasstheit von Organismen begründen', 'From environmental factor to ecosystem: justify variability and adaptedness of organisms', NULL, 'Students explain how combined environmental factors shape where organisms occur and how adapted they are, using tolerance range, ecological niche and species relationships. Plant water balance and photosynthesis, matter cycles and the protection of biodiversity are covered as well.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf', '{"courseLevel": "basic", "topicTags": ["ecology_populations", "selection_adaptation"]}', 'unit-records-195'),
  ('6f693515-8fce-5331-9c52-3d0778225880', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12/de-st-lp-bio-sjg11-12-ean-umweltfaktor-oekosystem', 'b5c56b48-3c8d-574a-96d6-84e67102f895', 'unit', 'biologie', 'Gymnasium', '11/12', NULL, 'DE-ST-LP-BIO-sjg11-12-ean-umweltfaktor-oekosystem', 3, 'Vom Umweltfaktor zum Ökosystem – Variabilität und Angepasstheit von Organismen begründen', 'From environmental factor to ecosystem: justify variability and adaptedness of organisms', NULL, 'Students explain how environmental factors shape occurrence and adaptation of organisms, model population growth (exponential and logistic growth, r and K strategies, Lotka-Volterra rules) and species coexistence through the niche. An ecosystem excursion and simulations of population interactions are included.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf', '{"courseLevel": "advanced", "topicTags": ["ecology_populations", "selection_adaptation"]}', 'unit-records-195'),
  ('e6a5517a-2a30-5fbb-af1b-42ba9e210c69', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12/de-st-lp-bio-sjg11-12-ean-reiz-reaktion-verhalten', 'b5c56b48-3c8d-574a-96d6-84e67102f895', 'unit', 'biologie', 'Gymnasium', '11/12', NULL, 'DE-ST-LP-BIO-sjg11-12-ean-reiz-reaktion-verhalten', 4, 'Vom Reiz zur Reaktion – Prozesse der Informationsverarbeitung erklären', 'From stimulus to response: explain information processing', NULL, 'Students explain how neurons, synapses and receptors process information and approach behavior on the proximate level, covering reflexes, key stimuli, conditioning and learning. Addiction, stress and hormones are included, with attention to how behavior research is designed.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf', '{"courseLevel": "advanced", "topicTags": ["behavior_cognition", "human_biology"]}', 'unit-records-195'),
  ('a71e9f84-45ae-5d96-9858-60175d3a4ae3', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12/de-st-lp-bio-sjg11-12-gan-entstehung-biodiversitaet', 'b5c56b48-3c8d-574a-96d6-84e67102f895', 'unit', 'biologie', 'Gymnasium', '11/12', NULL, 'DE-ST-LP-BIO-sjg11-12-gan-entstehung-biodiversitaet', 5, 'Von der Entstehung des Lebens zur Biodiversität – Geschichte und Verwandtschaft von Organismen erläutern', 'From the origin of life to biodiversity: explain the history and relatedness of organisms', NULL, 'Students explain the origin and change of species with the synthetic theory of evolution: gene pool, kinds of selection, drift, speciation, phylogenetic trees, fitness and kin selection. They examine evidence and how knowledge about the adaptive value of behavior is produced.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf', '{"courseLevel": "basic", "topicTags": ["evolution", "selection_adaptation", "diversity_systematics", "behavior_cognition", "nature_of_science"]}', 'unit-records-195'),
  ('a63eaf2b-ac28-5ed3-a947-c7a1fc62d9b0', 'saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12/de-st-lp-bio-sjg11-12-ean-entstehung-biodiversitaet', 'b5c56b48-3c8d-574a-96d6-84e67102f895', 'unit', 'biologie', 'Gymnasium', '11/12', NULL, 'DE-ST-LP-BIO-sjg11-12-ean-entstehung-biodiversitaet', 6, 'Von der Entstehung des Lebens zur Biodiversität – Geschichte und Verwandtschaft von Organismen erläutern', 'From the origin of life to biodiversity: explain the history and relatedness of organisms', NULL, 'Students explain species change with the synthetic theory of evolution, including kinds of selection, drift, speciation, fitness and kin selection, and test hypotheses on human evolution. They also treat climate rules, antibiotic resistance, cultural evolution, primate social behavior and the evaluation of racism.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf', '{"courseLevel": "advanced", "topicTags": ["evolution", "selection_adaptation", "diversity_systematics", "behavior_cognition", "nature_of_science"]}', 'unit-records-195'),
  ('e30e9753-4ca2-5f5d-a307-37f8275f8628', 'saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung', NULL, 'edition', 'informatik', 'Gymnasium', NULL, NULL, NULL, 0, 'Informatik, Gymnasium · 01.08.2022 (In Kraft seit 2017, Anpassung 2022)', 'Computer science, Gymnasium · 01.08.2022 (In Kraft seit 2017, Anpassung 2022)', NULL, NULL, NULL, NULL, '{"units": 8, "edition": "01.08.2022 (In Kraft seit 2017, Anpassung 2022)"}', 'unit-records-195'),
  ('b277dcaf-3bca-559b-b331-a3e3005cf16c', 'saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/9', 'e30e9753-4ca2-5f5d-a307-37f8275f8628', 'grade_band', 'informatik', 'Gymnasium', '9', NULL, NULL, 9, 'Klassenstufe 9', 'Grade 9', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('f2b4987f-6e0e-58ac-8c16-8157bd21f1e8', 'saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/9/de-st-lp-inf-sjg9-daten-codieren-verarbeitung', 'b277dcaf-3bca-559b-b331-a3e3005cf16c', 'unit', 'informatik', 'Gymnasium', '9', NULL, 'DE-ST-LP-INF-sjg9-daten-codieren-verarbeitung', 0, 'Daten codieren und ihre Verarbeitung verstehen', 'Encode data and understand how it is processed', NULL, 'Students map information onto data, work with units and number systems, and analyse how computers work using the input-process-output principle and the von Neumann model. They look at file formats, operating systems, networks, logic gates and the sustainability of devices.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Informatik_Gym_01082022_swd.pdf', '{"topicTags": ["information_data", "systems_networks"]}', 'unit-records-195'),
  ('9d38b734-fa08-5fe7-aefb-8bccb6b54457', 'saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/9/de-st-lp-inf-sjg9-algorithmen-interpretieren-entwickeln', 'b277dcaf-3bca-559b-b331-a3e3005cf16c', 'unit', 'informatik', 'Gymnasium', '9', NULL, 'DE-ST-LP-INF-sjg9-algorithmen-interpretieren-entwickeln', 1, 'Algorithmen interpretieren und entwickeln', 'Interpret and develop algorithms', NULL, 'Students formulate procedures, design and test algorithms built from basic building blocks in a visual programming language, and model state-based systems as finite automata. They discuss uses, risks and resource needs of algorithms in daily life.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Informatik_Gym_01082022_swd.pdf', '{"topicTags": ["algorithms_programming", "modelling_simulation"]}', 'unit-records-195'),
  ('da3f6371-10ec-54d3-903d-c77466fcc245', 'saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/10', 'e30e9753-4ca2-5f5d-a307-37f8275f8628', 'grade_band', 'informatik', 'Gymnasium', '10', NULL, NULL, 10, 'Klassenstufe 10', 'Grade 10', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('d62a8e36-6e59-5812-b036-3f5d97629989', 'saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/10/de-st-lp-inf-sjg10-algorithmen-datenstrukturen-implementieren', 'da3f6371-10ec-54d3-903d-c77466fcc245', 'unit', 'informatik', 'Gymnasium', '10', NULL, 'DE-ST-LP-INF-sjg10-algorithmen-datenstrukturen-implementieren', 0, 'Algorithmen- und Datenstrukturen implementieren und testen', 'Implement and test algorithms and data structures', NULL, 'Students implement and test classes, objects and methods in a text-based programming language, use data types and variables, and work through a search, sorting or encryption method as a problem-solving cycle. UML class diagrams and error handling are introduced.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Informatik_Gym_01082022_swd.pdf', '{"topicTags": ["algorithms_programming", "information_data"]}', 'unit-records-195'),
  ('4bd70046-a97b-5cdc-a57b-fa926dd77339', 'saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/10/de-st-lp-inf-sjg10-grundlagen-informatiksysteme', 'da3f6371-10ec-54d3-903d-c77466fcc245', 'unit', 'informatik', 'Gymnasium', '10', NULL, 'DE-ST-LP-INF-sjg10-grundlagen-informatiksysteme', 1, 'Technische und theoretische Grundlagen von Informatiksystemen verstehen', 'Understand the technical and theoretical foundations of computing systems', NULL, 'Students write rules for simple formal languages and build acceptors, distinguish formal from natural languages, and learn how TCP/IP networks work with layers, protocols and addressing. They model and simulate home or school networks with security measures and reflect on limits of automated systems.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Informatik_Gym_01082022_swd.pdf', '{"topicTags": ["systems_networks", "algorithms_programming"]}', 'unit-records-195'),
  ('e9a1fd6f-b885-5e34-a064-be7f7d5dacee', 'saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/11-12', 'e30e9753-4ca2-5f5d-a307-37f8275f8628', 'grade_band', 'informatik', 'Gymnasium', '11/12', NULL, NULL, 11, 'Klassenstufe 11/12', 'Grade 11/12', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('2a532981-2395-5ae5-9c6b-a771432ea466', 'saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/11-12/de-st-lp-inf-sjg11-12-kurs1-objektorientiertes-modellieren', 'e9a1fd6f-b885-5e34-a064-be7f7d5dacee', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-ST-LP-INF-sjg11-12-kurs1-objektorientiertes-modellieren', 0, 'Objektorientiertes Modellieren', 'Object-oriented modelling', NULL, 'Students analyse problems with use case diagrams, derive classes and relations for an object-oriented design, and implement them in a programming language, including inheritance, dynamic data structures and file storage. Possible projects are simulations, games or distributed applications.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Informatik_Gym_01082022_swd.pdf', '{"unitNumber": "Kurs 1", "topicTags": ["modelling_simulation", "algorithms_programming"]}', 'unit-records-195'),
  ('3099f7a2-b0a8-5938-b82b-216e41805b7a', 'saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/11-12/de-st-lp-inf-sjg11-12-kurs2-daten-erfassen-strukturieren', 'e9a1fd6f-b885-5e34-a064-be7f7d5dacee', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-ST-LP-INF-sjg11-12-kurs2-daten-erfassen-strukturieren', 1, 'Daten erfassen, strukturieren und verarbeiten', 'Collect, structure and process data', NULL, 'Students design relational databases with entity-relationship models, convert them to relational schemas up to third normal form, and query data with a query language. They also weigh lawful handling of data and compare database modelling with object-oriented modelling.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Informatik_Gym_01082022_swd.pdf', '{"unitNumber": "Kurs 2", "topicTags": ["information_data"]}', 'unit-records-195'),
  ('e107310a-9789-50c6-ad6d-ad0ed9fb0bc0', 'saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/11-12/de-st-lp-inf-sjg11-12-kurs3-software-engineering-projektarbeit', 'e9a1fd6f-b885-5e34-a064-be7f7d5dacee', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-ST-LP-INF-sjg11-12-kurs3-software-engineering-projektarbeit', 2, 'Software Engineering und Projektarbeit', 'Software engineering and project work', NULL, 'Students carry out a software project as a team: analysis, specification, design, implementation, testing and quality assurance. They plan and document the work, coordinate with a client, and justify choices of algorithms, data handling and sustainability.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Informatik_Gym_01082022_swd.pdf', '{"unitNumber": "Kurs 3", "topicTags": ["algorithms_programming", "other"]}', 'unit-records-195'),
  ('184be823-d680-56d8-ad23-2af00843cecf', 'saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/11-12/de-st-lp-inf-sjg11-12-kurs4-aktuelle-entwicklungen-gesellschaft', 'e9a1fd6f-b885-5e34-a064-be7f7d5dacee', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-ST-LP-INF-sjg11-12-kurs4-aktuelle-entwicklungen-gesellschaft', 3, 'Aktuelle Entwicklungen der Informatik im gesellschaftlichen Kontext', 'Current developments in computing in their social context', NULL, 'Students examine current developments in computing and their effects on society and the environment, choosing topics such as artificial intelligence, social networks, virtual worlds or resource use of devices. They assess chances, risks and sustainability, and may build or train a small AI system.', NULL, 'https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Informatik_Gym_01082022_swd.pdf', '{"unitNumber": "Kurs 4", "topicTags": ["media_society", "ai_ml"]}', 'unit-records-195'),
  ('260971e7-d6df-598e-aa91-3e2f13f27a4c', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition', NULL, 'edition', 'biologie', 'Gymnasium', NULL, NULL, NULL, 0, 'Biologie, Gymnasium · 2004, Überarbeitung 2025', 'Biology, Gymnasium · 2004, revised 2025', NULL, NULL, NULL, NULL, '{"units": 25, "edition": "2004, Überarbeitung 2025 (portal edition line: 2004/2007/2009/2011/2017/2019/2022/2025)"}', 'unit-records-195'),
  ('bdd4b71b-3e6d-54fe-8582-d58c80707a85', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/5', '260971e7-d6df-598e-aa91-3e2f13f27a4c', 'grade_band', 'biologie', 'Gymnasium', '5', NULL, NULL, 5, 'Klassenstufe 5', 'Grade 5', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('dd5ef5f1-ac26-5fec-a4d5-ef9191937cd8', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/5/de-sn-lp-bio-bio-k5-lb1-merkmale-des-lebens', 'bdd4b71b-3e6d-54fe-8582-d58c80707a85', 'unit', 'biologie', 'Gymnasium', '5', NULL, 'DE-SN-LP-BIO-bio-k5-lb1-merkmale-des-lebens', 0, 'Merkmale des Lebens', 'Characteristics of life', NULL, 'Pupils get a first look at the subject of biology and at how biologists work, using observation, examination and comparison. They learn selected characteristics of life and set organisms against lifeless objects.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "1", "hours": 3, "topicTags": ["nature_of_science", "other"]}', 'unit-records-195'),
  ('ecc3f10e-421f-54f6-9579-6beec6b2e8fa', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/5/de-sn-lp-bio-bio-k5-lb2-fische', 'bdd4b71b-3e6d-54fe-8582-d58c80707a85', 'unit', 'biologie', 'Gymnasium', '5', NULL, 'DE-SN-LP-BIO-bio-k5-lb2-fische', 1, 'Fische in ihren Lebensräumen', 'Fishes in their habitats', NULL, 'Pupils meet the diversity of fishes through about six local species. They treat body form, scales and gills as adaptations to life in water, learn about reproduction and food chains, and assess measures that protect fish stocks.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "2", "hours": 8, "topicTags": ["selection_adaptation", "diversity_systematics", "ecology_populations"]}', 'unit-records-195'),
  ('bb98731a-7bd9-5950-86b3-733034a8260f', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/5/de-sn-lp-bio-bio-k5-lb5-voegel', 'bdd4b71b-3e6d-54fe-8582-d58c80707a85', 'unit', 'biologie', 'Gymnasium', '5', NULL, 'DE-SN-LP-BIO-bio-k5-lb5-voegel', 2, 'Vögel in ihren Lebensräumen', 'Birds in their habitats', NULL, 'Pupils survey local birds and relate body form, skeleton, lungs and beak shape to flight and feeding. They also look at behaviour such as territory, courtship, song and brood care, and discuss how to protect native birds.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "5", "hours": 9, "topicTags": ["selection_adaptation", "diversity_systematics", "behavior_cognition"]}', 'unit-records-195'),
  ('98b0fea3-c64a-519e-b2ad-4ee88eda5d81', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/5/de-sn-lp-bio-bio-k5-lb6-saeugetiere', 'bdd4b71b-3e6d-54fe-8582-d58c80707a85', 'unit', 'biologie', 'Gymnasium', '5', NULL, 'DE-SN-LP-BIO-bio-k5-lb6-saeugetiere', 3, 'Säugetiere in ihren Lebensräumen', 'Mammals in their habitats', NULL, 'Pupils compare wild and domestic mammals, including how breeds were bred from wild animals. They observe communication, cooperation, rank order and territory, and relate limb skeletons, teeth and lungs to habitat and diet.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "6", "hours": 13, "topicTags": ["selection_adaptation", "behavior_cognition", "diversity_systematics"]}', 'unit-records-195'),
  ('db43a18f-c14c-5606-8a3b-1cca6cf7c725', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/5/de-sn-lp-bio-bio-k5-lb7-systematisierung', 'bdd4b71b-3e6d-54fe-8582-d58c80707a85', 'unit', 'biologie', 'Gymnasium', '5', NULL, 'DE-SN-LP-BIO-bio-k5-lb7-systematisierung', 4, 'Systematisierung', 'Systematisation of vertebrates', NULL, 'Pupils draw together what they know about the vertebrate groups by comparing breathing organs, body covering and reproduction in relation to habitat. The unit prepares the idea of evolutionary development (Entwicklungsgedanke).', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "7", "hours": 3, "topicTags": ["diversity_systematics", "selection_adaptation", "evolution"]}', 'unit-records-195'),
  ('31596f5c-154d-5f51-bc46-ccd68140ee9c', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/5/de-sn-lp-bio-bio-k5-wb2-kriechtiere-vergangener-zeiten', 'bdd4b71b-3e6d-54fe-8582-d58c80707a85', 'unit', 'biologie', 'Gymnasium', '5', NULL, 'DE-SN-LP-BIO-bio-k5-wb2-kriechtiere-vergangener-zeiten', 5, 'Kriechtiere vergangener Zeiten', 'Reptiles of past ages', NULL, 'An optional unit in which pupils prepare a presentation on dinosaurs as extinct reptiles, drawing on fossils and basic palaeontology and using digital media.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "Wahlbereich 2", "topicTags": ["evolution", "diversity_systematics"]}', 'unit-records-195'),
  ('3111ff5e-4687-5ae0-8676-cb2c12c21200', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/6', '260971e7-d6df-598e-aa91-3e2f13f27a4c', 'grade_band', 'biologie', 'Gymnasium', '6', NULL, NULL, 6, 'Klassenstufe 6', 'Grade 6', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('6a0409be-517e-5093-8967-a8a2b3ba513f', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/6/de-sn-lp-bio-bio-k6-lb2-wirbellose-tiere', '3111ff5e-4687-5ae0-8676-cb2c12c21200', 'unit', 'biologie', 'Gymnasium', '6', NULL, 'DE-SN-LP-BIO-bio-k6-lb2-wirbellose-tiere', 0, 'Wirbellose Tiere in ihren Lebensräumen', 'Invertebrates in their habitats', NULL, 'Pupils survey invertebrate groups and apply adaptation and reproduction to the earthworm and to insects, including metamorphosis and mouthparts. The honey bee shows a social insect state with division of labour and communication. Parasites are touched on.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "2", "hours": 16, "topicTags": ["selection_adaptation", "diversity_systematics", "behavior_cognition"]}', 'unit-records-195'),
  ('0a8ce018-6e64-5060-89be-df9107c227d8', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/6/de-sn-lp-bio-bio-k6-lb3-systematisierung', '3111ff5e-4687-5ae0-8676-cb2c12c21200', 'unit', 'biologie', 'Gymnasium', '6', NULL, 'DE-SN-LP-BIO-bio-k6-lb3-systematisierung', 1, 'Systematisierung', 'Systematisation of invertebrates and vertebrates', NULL, 'Pupils compare invertebrate and vertebrate groups by skeleton, breathing organs and reproduction, linking structure and function to adaptation to habitat.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "3", "hours": 4, "topicTags": ["diversity_systematics", "selection_adaptation"]}', 'unit-records-195'),
  ('66436a23-72f7-5776-b4f4-511334310f81', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/6/de-sn-lp-bio-bio-k6-lb4-wald-lebensgemeinschaft', '3111ff5e-4687-5ae0-8676-cb2c12c21200', 'unit', 'biologie', 'Gymnasium', '6', NULL, 'DE-SN-LP-BIO-bio-k6-lb4-wald-lebensgemeinschaft', 2, 'Wald als Lebensgemeinschaft', 'The forest as a living community', NULL, 'Pupils study the layers of a near-natural mixed forest and the organisms living in them, trace food webs linking plants, animals and fungi, and learn about forest damage in Saxony and measures to protect forests.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "4", "hours": 10, "topicTags": ["ecology_populations"]}', 'unit-records-195'),
  ('c97ce357-4cc8-5c48-93b1-88a4f97c48d5', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/9', '260971e7-d6df-598e-aa91-3e2f13f27a4c', 'grade_band', 'biologie', 'Gymnasium', '9', NULL, NULL, 9, 'Klassenstufe 9', 'Grade 9', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('149e8cc1-0e53-516e-8e29-0bcfccabc0c1', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/9/de-sn-lp-bio-bio-k9-lb2-zusammenhaenge-im-oekosystem', 'c97ce357-4cc8-5c48-93b1-88a4f97c48d5', 'unit', 'biologie', 'Gymnasium', '9', NULL, 'DE-SN-LP-BIO-bio-k9-lb2-zusammenhaenge-im-oekosystem', 0, 'Zusammenhänge im Ökosystem', 'Connections in the ecosystem', NULL, 'A lake serves as the example ecosystem: food webs, ecological niches, succession, tolerance to light and temperature, and relations within and between species such as competition, symbiosis, parasitism and predation. Carbon cycle, climate change and human impact are included.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "2", "hours": 25, "topicTags": ["ecology_populations", "selection_adaptation", "behavior_cognition"]}', 'unit-records-195'),
  ('1a77d681-f772-563a-b27f-e186bc79d145', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/10', '260971e7-d6df-598e-aa91-3e2f13f27a4c', 'grade_band', 'biologie', 'Gymnasium', '10', NULL, NULL, 10, 'Klassenstufe 10', 'Grade 10', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('9535317c-cc4b-57ef-bae8-1f3ca5306d80', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/10/de-sn-lp-bio-bio-k10-lb1-genetik', '1a77d681-f772-563a-b27f-e186bc79d145', 'unit', 'biologie', 'Gymnasium', '10', NULL, 'DE-SN-LP-BIO-bio-k10-lb1-genetik', 0, 'Genetik', 'Genetics', NULL, 'Pupils link genotype and phenotype, separate mutation from modification, and work with Mendelian crosses, chromosomes, DNA and protein synthesis. They cover human genetics such as pedigrees and inherited disorders, then breeding and gene technology with their ethical questions.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "1", "hours": 25, "topicTags": ["inheritance_variation", "human_biology"]}', 'unit-records-195'),
  ('4f671928-8213-5f88-a45b-0360cd5c0c2d', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/10/de-sn-lp-bio-bio-k10-lb2-entstehung-der-artenvielfalt', '1a77d681-f772-563a-b27f-e186bc79d145', 'unit', 'biologie', 'Gymnasium', '10', NULL, 'DE-SN-LP-BIO-bio-k10-lb2-entstehung-der-artenvielfalt', 1, 'Entstehung der Artenvielfalt', 'Origin of species diversity', NULL, 'Pupils meet historical ideas of evolution (Linnaeus, Lamarck, Darwin) and the combined action of mutation, recombination, selection and isolation, with species and population concepts. Adaptation trends and evidence such as fossils and homologies are examined.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "2", "hours": 16, "topicTags": ["evolution", "selection_adaptation", "diversity_systematics"]}', 'unit-records-195'),
  ('1b3d555f-acb5-5b85-ad6b-7f7d7a364125', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/10/de-sn-lp-bio-bio-k10-lb3-stammesgeschichte-des-menschen', '1a77d681-f772-563a-b27f-e186bc79d145', 'unit', 'biologie', 'Gymnasium', '10', NULL, 'DE-SN-LP-BIO-bio-k10-lb3-stammesgeschichte-des-menschen', 2, 'Stammesgeschichte des Menschen', 'Evolutionary history of humans', NULL, 'Pupils compare humans with great apes in anatomy and behaviour and follow human evolution from early hominins to Homo sapiens. They consider biological and cultural evolution, social behaviour, and the shared biology of all modern humans.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "3", "hours": 9, "topicTags": ["evolution", "human_biology"]}', 'unit-records-195'),
  ('eea6c7fa-c23a-535c-9c89-4edbce04a2cd', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/10/de-sn-lp-bio-bio-k10-wb2-entstehung-des-lebens', '1a77d681-f772-563a-b27f-e186bc79d145', 'unit', 'biologie', 'Gymnasium', '10', NULL, 'DE-SN-LP-BIO-bio-k10-wb2-entstehung-des-lebens', 3, 'Entstehung des Lebens auf der Erde', 'Origin of life on Earth', NULL, 'An optional unit on competing hypotheses for the origin of life: the early atmosphere, chemical and biological evolution, and creation accounts, with the work of Oparin, Miller and Fox.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "Wahlbereich 2", "topicTags": ["evolution", "nature_of_science"]}', 'unit-records-195'),
  ('0f05b696-ba3f-5bc2-8e6d-9e8328d3082a', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/10/de-sn-lp-bio-bio-k10-wb3-lernen-und-gedaechtnis', '1a77d681-f772-563a-b27f-e186bc79d145', 'unit', 'biologie', 'Gymnasium', '10', NULL, 'DE-SN-LP-BIO-bio-k10-wb3-lernen-und-gedaechtnis', 4, 'Lernen und Gedächtnis', 'Learning and memory', NULL, 'An optional unit that applies knowledge of the nervous system to learning: short-term and long-term memory, learning strategies and problem solving, and how cerebrum and cerebellum work together.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "Wahlbereich 3", "topicTags": ["behavior_cognition", "human_biology"]}', 'unit-records-195'),
  ('46d91ce7-9921-5cf3-b731-a5090c7829f1', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/11', '260971e7-d6df-598e-aa91-3e2f13f27a4c', 'grade_band', 'biologie', 'Gymnasium', '11', NULL, NULL, 11, 'Klassenstufe 11', 'Grade 11', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('03028631-3727-5397-b92d-f8d98df57734', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/11/de-sn-lp-bio-bio-gk11-lb3-oekologie-und-nachhaltigkeit', '46d91ce7-9921-5cf3-b731-a5090c7829f1', 'unit', 'biologie', 'Gymnasium', '11', NULL, 'DE-SN-LP-BIO-bio-gk11-lb3-oekologie-und-nachhaltigkeit', 0, 'Ökologie und Nachhaltigkeit', 'Ecology and sustainability', NULL, 'Students study a near-natural land ecosystem: tolerance ranges, adaptation to abiotic factors, competition, niches, food webs and energy flow. They assess pest control, monocultures, climate change and protection measures, and plan a field excursion with measurements.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "3", "hours": 13, "courseLevel": "basic", "topicTags": ["ecology_populations", "selection_adaptation"]}', 'unit-records-195'),
  ('16436a83-572b-536f-9044-8d3e44985515', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/11/de-sn-lp-bio-bio-lk11-lb3-oekologie-und-nachhaltigkeit', '46d91ce7-9921-5cf3-b731-a5090c7829f1', 'unit', 'biologie', 'Gymnasium', '11', NULL, 'DE-SN-LP-BIO-bio-lk11-lb3-oekologie-und-nachhaltigkeit', 1, 'Ökologie und Nachhaltigkeit', 'Ecology and sustainability', NULL, 'Extends the basic course with population growth (density-dependent factors, r- and K-strategies, exponential and logistic growth, Lotka-Volterra rules), nutrient cycles and monocultures. Students weigh ecosystem management and carry out a field excursion with documentation.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "3", "hours": 35, "courseLevel": "advanced", "topicTags": ["ecology_populations", "selection_adaptation"]}', 'unit-records-195'),
  ('8b1ce946-15d0-5b1b-89ca-9fb84b498ae8', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12', '260971e7-d6df-598e-aa91-3e2f13f27a4c', 'grade_band', 'biologie', 'Gymnasium', '12', NULL, NULL, 12, 'Klassenstufe 12', 'Grade 12', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('35e9014e-ef89-56ab-9d55-57f61dd5d0c1', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-gk12-lb1-genetik', '8b1ce946-15d0-5b1b-89ca-9fb84b498ae8', 'unit', 'biologie', 'Gymnasium', '12', NULL, 'DE-SN-LP-BIO-bio-gk12-lb1-genetik', 0, 'Grundlagen, Anwendungen und Perspektiven der Genetik', 'Foundations, applications and perspectives of genetics', NULL, 'Students apply Mendelian rules to unlinked inheritance and trace how gene mutations cause inherited diseases. They learn techniques such as PCR, sequencing and gel electrophoresis, then somatic gene therapy and the ethics of therapy and embryo diagnosis.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "1", "hours": 18, "courseLevel": "basic", "topicTags": ["inheritance_variation", "human_biology"]}', 'unit-records-195'),
  ('856b1f5b-48f7-5488-966b-e5fa09a7dc42', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-lk12-lb1-genetik', '8b1ce946-15d0-5b1b-89ca-9fb84b498ae8', 'unit', 'biologie', 'Gymnasium', '12', NULL, 'DE-SN-LP-BIO-bio-lk12-lb1-genetik', 1, 'Grundlagen, Anwendungen und Perspektiven der Genetik', 'Foundations, applications and perspectives of genetics', NULL, 'Students link genetics to constancy and variability through mutation, recombination, meiosis and linked inheritance. They study human-genetic techniques and diagnostics, cancer genes, gene transfer in bacteria and viruses, stem cells and gene therapy, and discuss the ethics.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "1", "hours": 34, "courseLevel": "advanced", "topicTags": ["inheritance_variation", "human_biology"]}', 'unit-records-195'),
  ('cd7ec503-ab67-5aa2-a4bd-9b1ab1ddbacb', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-gk12-lb3-biodiversitaet', '8b1ce946-15d0-5b1b-89ca-9fb84b498ae8', 'unit', 'biologie', 'Gymnasium', '12', NULL, 'DE-SN-LP-BIO-bio-gk12-lb3-biodiversitaet', 2, 'Biodiversität und ihre Entstehung', 'Biodiversity and its origin', NULL, 'Students use the population-genetic species concept and the interplay of mutation, recombination, selection, isolation, migration, drift and coevolution. They study proximate and ultimate causes of behaviour, molecular evidence and phylogenetic trees, and set evolutionary theory apart from views outside science.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "3", "hours": 14, "courseLevel": "basic", "topicTags": ["evolution", "selection_adaptation", "behavior_cognition", "diversity_systematics"]}', 'unit-records-195'),
  ('d552c189-aeaf-53f8-9bb5-d88776903b2e', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-lk12-lb3-verhalten-von-tier-und-mensch', '8b1ce946-15d0-5b1b-89ca-9fb84b498ae8', 'unit', 'biologie', 'Gymnasium', '12', NULL, 'DE-SN-LP-BIO-bio-lk12-lb3-verhalten-von-tier-und-mensch', 3, 'Verhalten von Tier und Mensch', 'Behaviour of animals and humans', NULL, 'Students learn methods of behavioural biology such as ethograms and unbiased observation, and the causes of behaviour (endogenous and exogenous, proximate and ultimate). Cost-benefit analysis and fitness explain adaptive value. Primate social behaviour, development, communication and reproduction serve as applications.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "3", "hours": 10, "courseLevel": "advanced", "topicTags": ["behavior_cognition", "selection_adaptation"]}', 'unit-records-195'),
  ('faf92e4e-6668-594b-b6c6-52a876e8dda7', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-lk12-lb4-biodiversitaet', '8b1ce946-15d0-5b1b-89ca-9fb84b498ae8', 'unit', 'biologie', 'Gymnasium', '12', NULL, 'DE-SN-LP-BIO-bio-lk12-lb4-biodiversitaet', 4, 'Biodiversität und ihre Entstehung', 'Biodiversity and its origin', NULL, 'Students apply the synthetic theory of evolution to progression and specialisation, including adaptive radiation, drift, chance and coevolution. They assess social Darwinism and Gould''s theory, use molecular evidence and phylogenetic trees, and treat human evolution and cultural evolution.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "4", "hours": 20, "courseLevel": "advanced", "topicTags": ["evolution", "selection_adaptation", "diversity_systematics"]}', 'unit-records-195'),
  ('e06cc4ae-546b-5186-b607-edb9fdfbd12c', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-lk12-wb2-evolution-des-stoffwechsels', '8b1ce946-15d0-5b1b-89ca-9fb84b498ae8', 'unit', 'biologie', 'Gymnasium', '12', NULL, 'DE-SN-LP-BIO-bio-lk12-wb2-evolution-des-stoffwechsels', 5, 'Evolution des Stoffwechsels', 'Evolution of metabolism', NULL, 'An optional unit applying knowledge of metabolism to the evolution of feeding types: protobionts and eobionts, prokaryotic and eukaryotic cells, the endosymbiont hypothesis, chemosynthesis and photosynthesis, fermentation and respiration.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "Wahlbereich 2", "courseLevel": "advanced", "topicTags": ["evolution"]}', 'unit-records-195'),
  ('bb5c5756-329e-5918-85b6-1f50fe9a5639', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-gk12-wb4-verhaltensbiologisches-praktikum', '8b1ce946-15d0-5b1b-89ca-9fb84b498ae8', 'unit', 'biologie', 'Gymnasium', '12', NULL, 'DE-SN-LP-BIO-bio-gk12-wb4-verhaltensbiologisches-praktikum', 6, 'Verhaltensbiologisches Praktikum', 'Practical course in behavioural biology', NULL, 'An optional practical in which students plan observations and experiments on animal or human behaviour such as aggression, territory and learning, using animals like crickets, small mammals or fighting fish.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "Wahlbereich 4", "courseLevel": "basic", "topicTags": ["behavior_cognition", "nature_of_science"]}', 'unit-records-195'),
  ('890b81ae-70bf-5831-a016-35432127227a', 'saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-lk12-wb4-verhaltensbiologisches-praktikum', '8b1ce946-15d0-5b1b-89ca-9fb84b498ae8', 'unit', 'biologie', 'Gymnasium', '12', NULL, 'DE-SN-LP-BIO-bio-lk12-wb4-verhaltensbiologisches-praktikum', 7, 'Verhaltensbiologisches Praktikum', 'Practical course in behavioural biology', NULL, 'An optional practical in which students plan observations and experiments on animal or human behaviour such as aggression, territory and learning, with digital media and animals like crickets, small mammals or fighting fish.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/522', '{"unitNumber": "Wahlbereich 4", "courseLevel": "advanced", "topicTags": ["behavior_cognition", "nature_of_science"]}', 'unit-records-195'),
  ('128523d1-b92d-5617-a452-e9597c728419', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor', NULL, 'edition', 'informatik', 'Gymnasium', NULL, NULL, NULL, 0, 'Informatik, Gymnasium · 2022', 'Computer science, Gymnasium · 2022', NULL, NULL, NULL, NULL, '{"units": 58, "edition": "2022 (portal edition line: ''Gymnasium Informatik 2022, Neuerarbeitung 2022 für Sekundarstufe I, gültig für Kl. 7 - 10, Jgst. 11'')"}', 'unit-records-195'),
  ('08fe4b57-7929-5d7f-a850-1332b097c215', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/7', '128523d1-b92d-5617-a452-e9597c728419', 'grade_band', 'informatik', 'Gymnasium', '7', NULL, NULL, 7, 'Klassenstufe 7', 'Grade 7', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('9c114c62-93df-57d3-a194-6bb8de5b8d73', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/7/de-sn-lp-inf-inf-k7-lb1-informationen-und-daten', '08fe4b57-7929-5d7f-a850-1332b097c215', 'unit', 'informatik', 'Gymnasium', '7', NULL, 'DE-SN-LP-INF-inf-k7-lb1-informationen-und-daten', 0, 'Informationen und Daten', 'Information and data', NULL, 'Pupils get a first look at computer science and separate the ideas of information and data. They meet forms of representation, binary coding of numbers, text and images, units from kilo to tera, and object-oriented ideas applied to vector graphics and office software.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "1", "hours": 13, "topicTags": ["information_data"]}', 'unit-records-195'),
  ('0e6d8354-5736-5e08-acc4-54aee50e08c4', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/7/de-sn-lp-inf-inf-k7-lb2-informatiksysteme', '08fe4b57-7929-5d7f-a850-1332b097c215', 'unit', 'informatik', 'Gymnasium', '7', NULL, 'DE-SN-LP-INF-inf-k7-lb2-informatiksysteme', 1, 'Informatiksysteme', 'Computing systems', NULL, 'Pupils learn the hardware parts of computing devices and apply the input-processing-output model to systems from daily life, using state diagrams and noting the limits of the model. They also meet operating systems, file types and sensible file names.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "2", "hours": 6, "topicTags": ["systems_networks", "modelling_simulation"]}', 'unit-records-195'),
  ('ca9ea01f-c1ea-5e43-b80d-8ed1f51567b6', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/7/de-sn-lp-inf-inf-k7-lb3-algorithmen', '08fe4b57-7929-5d7f-a850-1332b097c215', 'unit', 'informatik', 'Gymnasium', '7', NULL, 'DE-SN-LP-INF-inf-k7-lb3-algorithmen', 2, 'Algorithmen', 'Algorithms', NULL, 'Pupils describe algorithmic procedures in words and solve simple problems in a block-based or visual programming environment.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "3", "hours": 6, "topicTags": ["algorithms_programming"]}', 'unit-records-195'),
  ('2855e5c1-b012-55c6-ad81-e7d7e050865c', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/7/de-sn-lp-inf-inf-k7-wb1-rechnen-mit-binaerzahlen', '08fe4b57-7929-5d7f-a850-1332b097c215', 'unit', 'informatik', 'Gymnasium', '7', NULL, 'DE-SN-LP-INF-inf-k7-wb1-rechnen-mit-binaerzahlen', 3, 'Rechnen mit Binärzahlen', 'Calculating with binary numbers', NULL, 'An optional unit on basic operations with binary numbers: addition, multiplication and shift operations.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 1", "topicTags": ["information_data"]}', 'unit-records-195'),
  ('06c131c9-71e7-5e51-b758-fe6bb4118a7b', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/7/de-sn-lp-inf-inf-k7-wb2-computergrafik', '08fe4b57-7929-5d7f-a850-1332b097c215', 'unit', 'informatik', 'Gymnasium', '7', NULL, 'DE-SN-LP-INF-inf-k7-wb2-computergrafik', 4, 'Computergrafik', 'Computer graphics', NULL, 'An optional unit on image editing software: image size and crop, colour channels, greyscale and negative images.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 2", "topicTags": ["information_data"]}', 'unit-records-195'),
  ('b69b41c4-5b45-59d9-b7b9-d8640de4ca12', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/7/de-sn-lp-inf-inf-k7-wb3-geschichte-der-rechentechnik', '08fe4b57-7929-5d7f-a850-1332b097c215', 'unit', 'informatik', 'Gymnasium', '7', NULL, 'DE-SN-LP-INF-inf-k7-wb3-geschichte-der-rechentechnik', 5, 'Geschichte der Rechentechnik', 'History of computing technology', NULL, 'An optional unit on milestones in the history of computing, from Schickard and Pascal to Lovelace, Zuse, von Neumann and Turing, with a possible visit to a technical museum.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 3", "topicTags": ["other", "media_society"]}', 'unit-records-195'),
  ('790ada05-5dc4-546c-be7f-d0ecfe8ba340', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/8', '128523d1-b92d-5617-a452-e9597c728419', 'grade_band', 'informatik', 'Gymnasium', '8', NULL, NULL, 8, 'Klassenstufe 8', 'Grade 8', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('d7549b35-721f-5acf-bcc2-b18b158406d2', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/8/de-sn-lp-inf-inf-k8-lb1-algorithmen', '790ada05-5dc4-546c-be7f-d0ecfe8ba340', 'unit', 'informatik', 'Gymnasium', '8', NULL, 'DE-SN-LP-INF-inf-k8-lb1-algorithmen', 0, 'Algorithmen', 'Algorithms', NULL, 'Pupils learn what makes a procedure an algorithm and test this on everyday cases such as social media or in-app purchases. They solve simple tasks in a visual programming environment with sequence, branching and loops, and discuss the social role of algorithms.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "1", "hours": 9, "topicTags": ["algorithms_programming", "media_society"]}', 'unit-records-195'),
  ('69be2466-9aec-53b7-8362-68f7bd3b170e', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/8/de-sn-lp-inf-inf-k8-lb2-vernetzte-systeme', '790ada05-5dc4-546c-be7f-d0ecfe8ba340', 'unit', 'informatik', 'Gymnasium', '8', NULL, 'DE-SN-LP-INF-inf-k8-lb2-vernetzte-systeme', 1, 'Vernetzte Systeme', 'Networked systems', NULL, 'Pupils develop search strategies, use communication and collaboration services with good manners, and learn basic data protection and security (phishing, passwords, authenticity). They also learn how network addresses are built and judge information sources, including manipulated images and generated text.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "2", "hours": 10, "topicTags": ["systems_networks", "media_society", "information_data"]}', 'unit-records-195'),
  ('d5bf6f06-27f7-51f3-90c5-0a9fec4682c0', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/8/de-sn-lp-inf-inf-k8-lb3-komplexaufgabe', '790ada05-5dc4-546c-be7f-d0ecfe8ba340', 'unit', 'informatik', 'Gymnasium', '8', NULL, 'DE-SN-LP-INF-inf-k8-lb3-komplexaufgabe', 2, 'Komplexaufgabe', 'Complex task', NULL, 'Pupils combine content from grades 7 and 8 in one project, for example a cross-subject project, a wiki or blog built with a content management system, or setting up a mobile device, and reflect on how they worked.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "3", "hours": 6, "topicTags": ["other"]}', 'unit-records-195'),
  ('898229b9-a124-595e-8b0d-02e518ffa832', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/8/de-sn-lp-inf-inf-k8-wb1-verschluesselung-von-informationen', '790ada05-5dc4-546c-be7f-d0ecfe8ba340', 'unit', 'informatik', 'Gymnasium', '8', NULL, 'DE-SN-LP-INF-inf-k8-wb1-verschluesselung-von-informationen', 3, 'Verschlüsselung von Informationen', 'Encryption of information', NULL, 'An optional unit on historical ciphers: substitution methods such as Caesar and Vigenere, and transposition methods such as the fence and column ciphers.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 1", "topicTags": ["information_data"]}', 'unit-records-195'),
  ('86f00fc8-15f0-5dec-9efc-5afa726db17f', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/8/de-sn-lp-inf-inf-k8-wb2-computer-im-alltag', '790ada05-5dc4-546c-be7f-d0ecfe8ba340', 'unit', 'informatik', 'Gymnasium', '8', NULL, 'DE-SN-LP-INF-inf-k8-wb2-computer-im-alltag', 4, 'Computer im Alltag', 'Computers in everyday life', NULL, 'An optional unit in which pupils take a position on how computer use affects their own personality, covering information sources, dependency, cyberbullying and grooming, and how digitalisation changes working life.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 2", "topicTags": ["media_society"]}', 'unit-records-195'),
  ('f621fb1f-6bac-5d3c-8199-9397594f1446', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/8/de-sn-lp-inf-inf-k8-wb3-computerspiele', '790ada05-5dc4-546c-be7f-d0ecfe8ba340', 'unit', 'informatik', 'Gymnasium', '8', NULL, 'DE-SN-LP-INF-inf-k8-wb3-computerspiele', 5, 'Computerspiele', 'Computer games', NULL, 'An optional unit on game mechanics: implementing a game with collision detection and computer-controlled opponents, and discussing the risk of addiction.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 3", "topicTags": ["algorithms_programming", "media_society"]}', 'unit-records-195'),
  ('e787b897-2a99-55a8-9bc4-89cba7720ac2', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/9', '128523d1-b92d-5617-a452-e9597c728419', 'grade_band', 'informatik', 'Gymnasium', '9', NULL, NULL, 9, 'Klassenstufe 9', 'Grade 9', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('b65383a1-9828-5a01-ab58-1b00fe3c581b', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/9/de-sn-lp-inf-inf-k9-lb1-informationen-und-daten', 'e787b897-2a99-55a8-9bc4-89cba7720ac2', 'unit', 'informatik', 'Gymnasium', '9', NULL, 'DE-SN-LP-INF-inf-k9-lb1-informationen-und-daten', 0, 'Informationen und Daten', 'Information and data', NULL, 'Pupils learn what a database system is, design a data model for a small slice of the world and implement it. They practise queries (insert, change, delete, join, aggregation) and discuss personality rights and the risks of centralised data and big data.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "1", "hours": 12, "topicTags": ["information_data", "modelling_simulation"]}', 'unit-records-195'),
  ('0450ab9c-2179-5f3e-a1ab-cffb670657e4', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/9/de-sn-lp-inf-inf-k9-lb2-kuenstliche-intelligenz', 'e787b897-2a99-55a8-9bc4-89cba7720ac2', 'unit', 'informatik', 'Gymnasium', '9', NULL, 'DE-SN-LP-INF-inf-k9-lb2-kuenstliche-intelligenz', 1, 'Künstliche Intelligenz', 'Artificial intelligence', NULL, 'Pupils survey areas of artificial intelligence such as expert systems, speech and face recognition and autonomous driving. They meet supervised, unsupervised and reinforcement learning with software tools and judge how far results can be trusted given the data and model.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "2", "hours": 5, "topicTags": ["ai_ml"]}', 'unit-records-195'),
  ('3b87c0fa-2c39-5645-b3c2-b5361c4db21e', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/9/de-sn-lp-inf-inf-k9-lb3-netzwerke', 'e787b897-2a99-55a8-9bc4-89cba7720ac2', 'unit', 'informatik', 'Gymnasium', '9', NULL, 'DE-SN-LP-INF-inf-k9-lb3-netzwerke', 2, 'Netzwerke', 'Networks', NULL, 'Pupils learn how networks transmit data: network types and components, peer-to-peer and client-server, packets, protocols such as TCP/IP and HTTPS, and addressing with DNS and routing. They also meet symmetric and asymmetric encryption and discuss information security.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "3", "hours": 8, "topicTags": ["systems_networks"]}', 'unit-records-195'),
  ('4f6ab47f-7004-5012-bb2f-8bad792dab53', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/9/de-sn-lp-inf-inf-k9-wb1-inhaltsverwaltung', 'e787b897-2a99-55a8-9bc4-89cba7720ac2', 'unit', 'informatik', 'Gymnasium', '9', NULL, 'DE-SN-LP-INF-inf-k9-wb1-inhaltsverwaltung', 3, 'Inhaltsverwaltung', 'Content management', NULL, 'An optional unit on content management systems: the separation of content and design, the database underneath, and user roles.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 1", "topicTags": ["information_data"]}', 'unit-records-195'),
  ('e272020b-de6a-5ef8-bce0-727d87bfd3e0', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/9/de-sn-lp-inf-inf-k9-wb2-digitalisierung-von-daten', 'e787b897-2a99-55a8-9bc4-89cba7720ac2', 'unit', 'informatik', 'Gymnasium', '9', NULL, 'DE-SN-LP-INF-inf-k9-wb2-digitalisierung-von-daten', 4, 'Digitalisierung von Daten', 'Digitisation of data', NULL, 'An optional unit on technical ways to digitise images, text and audio.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 2", "topicTags": ["information_data"]}', 'unit-records-195'),
  ('1765dba0-14d7-5a2e-91cc-4c7353b1f76b', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/9/de-sn-lp-inf-inf-k9-wb3-graphen', 'e787b897-2a99-55a8-9bc4-89cba7720ac2', 'unit', 'informatik', 'Gymnasium', '9', NULL, 'DE-SN-LP-INF-inf-k9-wb3-graphen', 5, 'Graphen', 'Graphs', NULL, 'An optional unit on modelling problems as graphs: neural networks, shortest paths (Dijkstra), the travelling salesman problem, modelling states, and Huffman coding of text.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 3", "topicTags": ["algorithms_programming", "modelling_simulation"]}', 'unit-records-195'),
  ('f4624b20-c22d-5bd3-a9da-85045e9c31af', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/10', '128523d1-b92d-5617-a452-e9597c728419', 'grade_band', 'informatik', 'Gymnasium', '10', NULL, NULL, 10, 'Klassenstufe 10', 'Grade 10', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('dd5aaaf2-045b-53d8-aa39-53c6bffc0816', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/10/de-sn-lp-inf-inf-k10-lb1-algorithmen', 'f4624b20-c22d-5bd3-a9da-85045e9c31af', 'unit', 'informatik', 'Gymnasium', '10', NULL, 'DE-SN-LP-INF-inf-k10-lb1-algorithmen', 0, 'Algorithmen', 'Algorithms', NULL, 'Pupils implement basic algorithm structures in a text-based programming language, with syntax and semantics, data types, variables and combined conditions. They learn modularisation with subprograms and libraries and look at automated decisions such as autonomous driving and face recognition.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "1", "hours": 11, "topicTags": ["algorithms_programming", "media_society"]}', 'unit-records-195'),
  ('f4919afa-3963-5f4f-90da-b2697dc9c4b9', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/10/de-sn-lp-inf-inf-k10-lb2-sprachen', 'f4624b20-c22d-5bd3-a9da-85045e9c31af', 'unit', 'informatik', 'Gymnasium', '10', NULL, 'DE-SN-LP-INF-inf-k10-lb2-sprachen', 1, 'Sprachen', 'Languages', NULL, 'Pupils learn regular languages and regular expressions for searching, replacing and validating data. They also structure documents with markup languages such as HTML, XML, LaTeX and Markdown, covering headings, references and output formats.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "2", "hours": 8, "topicTags": ["information_data", "other"]}', 'unit-records-195'),
  ('ceda084e-c35f-536f-8534-e380ab9484d2', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/10/de-sn-lp-inf-inf-k10-lb3-komplexaufgabe', 'f4624b20-c22d-5bd3-a9da-85045e9c31af', 'unit', 'informatik', 'Gymnasium', '10', NULL, 'DE-SN-LP-INF-inf-k10-lb3-komplexaufgabe', 2, 'Komplexaufgabe', 'Complex task', NULL, 'Pupils plan and carry out a team project that combines content from grades 9 and 10, for example building and testing an AI, a web application, a chatbot or a client-server service.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "3", "hours": 6, "topicTags": ["algorithms_programming", "ai_ml"]}', 'unit-records-195'),
  ('6a5707c3-39ea-5279-a9f9-9734c5f5e7c4', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/10/de-sn-lp-inf-inf-k10-wb1-3d-computergrafik', 'f4624b20-c22d-5bd3-a9da-85045e9c31af', 'unit', 'informatik', 'Gymnasium', '10', NULL, 'DE-SN-LP-INF-inf-k10-wb1-3d-computergrafik', 3, '3D-Computergrafik', '3D computer graphics', NULL, 'An optional unit on representing spatial objects with software, including export for 3D printing and the ideas of rendering and ray tracing.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 1", "topicTags": ["information_data", "modelling_simulation"]}', 'unit-records-195'),
  ('ea082af3-a6d5-54b2-ab45-2af2bda73f3d', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/10/de-sn-lp-inf-inf-k10-wb2-zeitabhaengige-medien', 'f4624b20-c22d-5bd3-a9da-85045e9c31af', 'unit', 'informatik', 'Gymnasium', '10', NULL, 'DE-SN-LP-INF-inf-k10-wb2-zeitabhaengige-medien', 4, 'Zeitabhängige Medien', 'Time-based media', NULL, 'An optional unit on audio and video: storage and coding, sampling, frames, and compression with video codecs.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 2", "topicTags": ["information_data"]}', 'unit-records-195'),
  ('53cb2aad-9094-5843-844c-112c687253e5', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/10/de-sn-lp-inf-inf-k10-wb3-robotik', 'f4624b20-c22d-5bd3-a9da-85045e9c31af', 'unit', 'informatik', 'Gymnasium', '10', NULL, 'DE-SN-LP-INF-inf-k10-wb3-robotik', 5, 'Robotik', 'Robotics', NULL, 'An optional unit on how a robot system works: single-board computers, sensors and actuators.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 3", "topicTags": ["systems_networks"]}', 'unit-records-195'),
  ('5f272106-6b20-5ec6-be05-d0e16455321f', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12', '128523d1-b92d-5617-a452-e9597c728419', 'grade_band', 'informatik', 'Gymnasium', '11/12', NULL, NULL, 11, 'Klassenstufe 11/12', 'Grade 11/12', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('7863e29a-c96c-51fa-bc8e-7049e09acb19', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb1-technische-informatik', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-gk-lb1-technische-informatik', 0, 'Technische Informatik', 'Technical computer science', NULL, 'Students study binary and hexadecimal numbers, number formats, character codes and Boolean algebra, and apply them to switching networks with simulation software. They also cover microchip production, computer architecture, storage systems and sustainable use of hardware.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "1", "hours": 10, "courseLevel": "basic", "topicTags": ["systems_networks", "information_data"]}', 'unit-records-195'),
  ('eff6d782-2947-5ca1-be6e-38263e8d304e', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb1-technische-informatik', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb1-technische-informatik', 1, 'Technische Informatik', 'Technical computer science', NULL, 'Extends the basic course with number formats, Boolean algebra and its simplification laws, analysis and synthesis of switching networks including half and full adders, computer architecture, and a comparison of commercial and open-source system software.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "1", "hours": 18, "courseLevel": "advanced", "topicTags": ["systems_networks", "information_data"]}', 'unit-records-195'),
  ('5f5c93ef-1faf-599b-a76e-986d55c4c7cb', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb2-algorithmierung-und-programmierung', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-gk-lb2-algorithmierung-und-programmierung', 2, 'Algorithmierung und Programmierung', 'Algorithms and programming', NULL, 'Students extend the notion of algorithm, implement structured data types and subprograms, learn object-oriented ideas such as inheritance and polymorphism, and cover recursion. They code solutions to complex problems and examine efficiency, complexity and limits of computability.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "2", "hours": 20, "courseLevel": "basic", "topicTags": ["algorithms_programming", "modelling_simulation"]}', 'unit-records-195'),
  ('49810a22-efd2-59f9-b9bd-cd86c6bf54ac', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb2-datenstrukturen-und-algorithmen', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb2-datenstrukturen-und-algorithmen', 3, 'Datenstrukturen und Algorithmen', 'Data structures and algorithms', NULL, 'Students study complex data structures (trees, graphs, lists, stacks and queues), implement structured and dynamic data types, and use strategies such as divide and conquer, backtracking and traversal. They apply recursion, search and sort methods and learn how big and changing data are processed.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "2", "hours": 32, "courseLevel": "advanced", "topicTags": ["algorithms_programming"]}', 'unit-records-195'),
  ('d9a4cde4-75af-595f-8360-fce72ea9c763', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb3-rechnernetze', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-gk-lb3-rechnernetze', 4, 'Rechnernetze', 'Computer networks', NULL, 'Students study network media, topologies, packet switching and TCP/IP, model networks with simulation or single-board computers, and learn addressing, routing and name resolution. Security measures such as TLS, VPN and two-factor authentication are applied.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "3", "hours": 10, "courseLevel": "basic", "topicTags": ["systems_networks"]}', 'unit-records-195'),
  ('1366013a-fc4e-5bc3-a95c-1fbcdc59493d', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb3-komplexitaet-und-berechenbarkeit', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb3-komplexitaet-und-berechenbarkeit', 5, 'Komplexität von Algorithmen und Berechenbarkeit', 'Complexity of algorithms and computability', NULL, 'Students judge the efficiency and complexity of algorithms with complexity classes and time cost, and learn limits of computability such as the halting problem, P and NP problems, approximate solutions, and decidable and undecidable sets.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "3", "hours": 14, "courseLevel": "advanced", "topicTags": ["algorithms_programming", "other"]}', 'unit-records-195'),
  ('45dcfcd1-b225-5fdb-84dd-e235f4f4102c', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb4-informationssicherheit', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-gk-lb4-informationssicherheit', 6, 'Informationssicherheit', 'Information security', NULL, 'Students learn the protection goals of information security, principles of symmetric and asymmetric cryptography, digital signatures and backup methods, and take a position on a current data protection question.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "4", "hours": 10, "courseLevel": "basic", "topicTags": ["systems_networks", "media_society"]}', 'unit-records-195'),
  ('86d99707-1629-5514-aa6e-c7f32925b70b', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb4-programmierparadigmen', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb4-programmierparadigmen', 7, 'Programmierparadigmen', 'Programming paradigms', NULL, 'Students compare imperative, object-oriented, functional and logic programming, classify programming languages, learn object-oriented concepts such as aggregation, inheritance and polymorphism, and solve a problem in an object-oriented way.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "4", "hours": 25, "courseLevel": "advanced", "topicTags": ["algorithms_programming"]}', 'unit-records-195'),
  ('c67fbd43-41bd-5ae0-8f1a-ea02b1612d50', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb5-datenmanagement', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-gk-lb5-datenmanagement', 8, 'Datenmanagement', 'Data management', NULL, 'Students see uses of open and big data, the data life cycle and the relational model with ER diagrams, write SQL queries and visualise results. They apply machine learning to data analysis and discuss bias, reliability, and the difference between correlation and causation.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "5", "hours": 18, "courseLevel": "basic", "topicTags": ["information_data", "ai_ml", "modelling_simulation"]}', 'unit-records-195'),
  ('88a71248-2f3d-55d4-ae2d-bccf31c1bb79', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb5-softwareentwicklung', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb5-softwareentwicklung', 9, 'Softwareentwicklung', 'Software development', NULL, 'Students learn software architecture basics, compare classical and agile development, meet version control software and apply methods of agile development.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "5", "hours": 15, "courseLevel": "advanced", "topicTags": ["algorithms_programming"]}', 'unit-records-195'),
  ('0c341b2b-f739-59ce-85d5-a2712631744e', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb6-sprachen-und-automaten', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-gk-lb6-sprachen-und-automaten', 10, 'Sprachen und Automaten', 'Languages and automata', NULL, 'Students compare natural and formal languages, work with formal grammars, design finite automata and convert between grammars and automata for regular languages. They weigh chances and risks of automated language processing such as voice assistants and bots.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "6", "hours": 10, "courseLevel": "basic", "topicTags": ["algorithms_programming", "other"]}', 'unit-records-195'),
  ('bca111d0-ff3a-5443-8f3d-66d68fbdbab6', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb6-sprachen-und-automaten', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb6-sprachen-und-automaten', 11, 'Sprachen und Automaten', 'Languages and automata', NULL, 'Students compare natural and formal languages, work with grammars including Backus-Naur form and the Chomsky hierarchy, classify automata up to Turing machines, and learn how compilers and interpreters translate languages. They discuss automated language processing.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "6", "hours": 18, "courseLevel": "advanced", "topicTags": ["algorithms_programming", "other"]}', 'unit-records-195'),
  ('43477a2f-d12b-5829-8abf-53dde16fb9b2', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb7-informatisches-projekt', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-gk-lb7-informatisches-projekt', 12, 'Informatisches Projekt', 'Computing project', NULL, 'Students learn project management techniques (classical or agile approach, cost planning, stakeholder analysis, documentation, reflection) and apply them in a project that draws on the other learning areas.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "7", "hours": 10, "courseLevel": "basic", "topicTags": ["other"]}', 'unit-records-195'),
  ('689a67f3-4305-5d6f-8715-ee4db13ba624', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb7-rechnernetze', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb7-rechnernetze', 13, 'Rechnernetze', 'Computer networks', NULL, 'Students study topologies, media, services and switching methods, model networks in simulation, and learn addressing and routing, subnetting and VLANs, name resolution, authentication, transport encryption and certificates. They build a network from single-board computers.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "7", "hours": 20, "courseLevel": "advanced", "topicTags": ["systems_networks"]}', 'unit-records-195'),
  ('5197b308-272a-58e5-80d1-a620e904c689', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb8-informationssicherheit', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb8-informationssicherheit', 14, 'Informationssicherheit', 'Information security', NULL, 'Students cover protection goals including accountability, judge symmetric and asymmetric methods such as AES and RSA, and learn hash functions, blockchain, signatures, backup, cryptanalysis and social engineering. They discuss data protection principles and the legal framework.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "8", "hours": 20, "courseLevel": "advanced", "topicTags": ["systems_networks", "media_society"]}', 'unit-records-195'),
  ('031570ce-bacb-58f9-9f91-26199ad402cf', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb8a-kuenstliche-intelligenz', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-gk-lb8a-kuenstliche-intelligenz', 15, 'Künstliche Intelligenz', 'Artificial intelligence', NULL, 'Students define artificial intelligence (weak, strong, superintelligence), survey symbolic AI and machine learning, and apply methods such as regression, decision trees, neural networks, genetic algorithms, clustering and Q-learning. They judge social effects, including treating subjective models as objective facts.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "8A", "hours": 8, "courseLevel": "basic", "topicTags": ["ai_ml", "media_society"]}', 'unit-records-195'),
  ('f626a398-0360-52f3-96ed-d75fd3581251', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb8b-softwareentwicklung', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-gk-lb8b-softwareentwicklung', 16, 'Softwareentwicklung', 'Software development', NULL, 'Students learn basics of software architecture (model-view-controller, monolith), compare classical (waterfall, V-model) and agile (sprints, prototyping) development, and apply one method to implement a solution.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "8B", "hours": 8, "courseLevel": "basic", "topicTags": ["algorithms_programming"]}', 'unit-records-195'),
  ('efcd824b-6263-541a-b34d-8960c6d160dc', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb8c-prozessautomatisierung', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-gk-lb8c-prozessautomatisierung', 17, 'Prozessautomatisierung', 'Process automation', NULL, 'Students learn models of control and regulation (open control chain, feedback loop, measuring, controlling, regulating) and apply them with microcontrollers, sensors and actuators in settings such as the Internet of Things and smart homes.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "8C", "hours": 8, "courseLevel": "basic", "topicTags": ["systems_networks", "modelling_simulation"]}', 'unit-records-195'),
  ('a3599684-9134-59a3-9dd7-e59405e0e2d0', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb9-datenmanagement', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb9-datenmanagement', 18, 'Datenmanagement', 'Data management', NULL, 'Students cover data management problems in several fields, the data life cycle, and judging data sources for bias and reliability. They build a dataset, apply the relational model with normalisation, query with SQL, visualise data, use exchange formats and APIs, and take a stance on data in society.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "9", "hours": 35, "courseLevel": "advanced", "topicTags": ["information_data"]}', 'unit-records-195'),
  ('56b845e5-8549-55be-96dd-8193d5206c0e', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb10-kuenstliche-intelligenz', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb10-kuenstliche-intelligenz', 19, 'Künstliche Intelligenz', 'Artificial intelligence', NULL, 'Students study foundations of AI, symbolic AI such as expert systems and knowledge graphs, and machine learning (supervised, unsupervised, reinforcement). They build an AI by collecting data and choosing and testing an algorithm, and judge explainability, bias and social effects.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "10", "hours": 18, "courseLevel": "advanced", "topicTags": ["ai_ml"]}', 'unit-records-195'),
  ('f8e1bae0-7592-57a0-b8e9-3816ea1a414b', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb11-informatisches-projekt', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb11-informatisches-projekt', 20, 'Informatisches Projekt', 'Computing project', NULL, 'Students learn project management (cost planning, stakeholder analysis, risk management, classical and agile approaches) and run a project linking content from the other learning areas, using tools such as Kanban boards, sprints and Gantt charts.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "11", "hours": 15, "courseLevel": "advanced", "topicTags": ["other"]}', 'unit-records-195'),
  ('ec53f64b-1aad-554a-b6a7-08225066b1d5', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb12a-quanteninformatik', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb12a-quanteninformatik', 21, 'Quanteninformatik', 'Quantum computing', NULL, 'Students distinguish quantum from classical information (quantum states, qubits, Hadamard gate), learn how superposition and entanglement serve information processing, survey quantum computers, networks and cryptography, and discuss effects on information security.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "12A", "hours": 10, "courseLevel": "advanced", "topicTags": ["other"]}', 'unit-records-195'),
  ('215bc306-3812-548d-a8b2-4e27ed3269db', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb12b-3d-modellierung', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb12b-3d-modellierung', 22, '3D-Modellierung', '3D modelling', NULL, 'Students learn how 3D objects are represented digitally with a Cartesian coordinate system, vectors and CAD software, model simple solids, and meet production methods such as 3D printing, CNC and laser engraving.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "12B", "hours": 10, "courseLevel": "advanced", "topicTags": ["modelling_simulation"]}', 'unit-records-195'),
  ('8efa0a31-e48d-5341-88f1-be38e5d56511', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb12c-prozessautomatisierung', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb12c-prozessautomatisierung', 23, 'Prozessautomatisierung', 'Process automation', NULL, 'Students learn models of control and regulation and apply them to computing systems with microcontrollers, sensors, actuators, robot kits and smart home settings.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "12C", "hours": 10, "courseLevel": "advanced", "topicTags": ["systems_networks", "modelling_simulation"]}', 'unit-records-195'),
  ('c75867bd-f7c3-58fa-aa84-9f4cb2bd27a5', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb12d-webtechnologien', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-lb12d-webtechnologien', 24, 'Webtechnologien', 'Web technologies', NULL, 'Students learn how web systems work (hypertext, browsers, client-server), build static pages with markup and dynamic web applications with a scripting language, connect a database, and study basic threats and security mechanisms.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "12D", "hours": 10, "courseLevel": "advanced", "topicTags": ["systems_networks", "algorithms_programming"]}', 'unit-records-195'),
  ('1a89efbd-4683-54ea-8f94-d122220f7596', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-wb1-betriebssysteme', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-wb1-betriebssysteme', 25, 'Betriebssysteme', 'Operating systems', NULL, 'An optional unit on what an operating system does: layers, resource management, processes and threads, file and memory management, and user management. Students work with a concrete system and discuss open source and proprietary systems.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 1", "courseLevel": "advanced", "topicTags": ["systems_networks"]}', 'unit-records-195'),
  ('ffb1256b-f6c0-5c47-8524-a9482b67077f', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-wb1-3d-modellierung', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-gk-wb1-3d-modellierung', 26, '3D-Modellierung', '3D modelling', NULL, 'An optional unit on geometric modelling of simple solids (views, intersections, z-buffer) and on making 3D objects.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 1", "courseLevel": "basic", "topicTags": ["modelling_simulation", "information_data"]}', 'unit-records-195'),
  ('aa605a54-249a-5913-90ec-38404f47c62a', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-wb2-quanteninformatik', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-gk-wb2-quanteninformatik', 27, 'Quanteninformatik', 'Quantum computing', NULL, 'An optional unit that separates quantum information from classical information (quantum states, qubits, superposition, entanglement), looks at quantum computers and quantum cryptography, and discusses effects on information security.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 2", "courseLevel": "basic", "topicTags": ["other"]}', 'unit-records-195'),
  ('98d2465c-9201-5409-a2ae-d467b158b343', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-wb2-wirtschaftsinformatik', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-wb2-wirtschaftsinformatik', 28, 'Wirtschaftsinformatik', 'Business informatics', NULL, 'An optional unit on markets and digital goods, network economics (economies of scale, network effects, platform economy, lock-in), typical IT business functions, software cost structure and financing models such as subscriptions, advertising and open source.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 2", "courseLevel": "advanced", "topicTags": ["media_society"]}', 'unit-records-195'),
  ('02652769-4ec9-50a0-b525-196daa479e17', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-wb3-wirtschaftsinformatik', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-gk-wb3-wirtschaftsinformatik', 29, 'Wirtschaftsinformatik', 'Business informatics', NULL, 'An optional unit on digital goods and network economics (economies of scale, fixed costs, network effects, platform economy, lock-in) and on financing models for software such as subscriptions, advertising and open source.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 3", "courseLevel": "basic", "topicTags": ["media_society"]}', 'unit-records-195'),
  ('45c9d706-4bdf-5c0a-9b89-c3ad25ac6c9a', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-wb3-informatik-und-oekologie', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-wb3-informatik-und-oekologie', 30, 'Informatik und Ökologie', 'Computer science and ecology', NULL, 'An optional unit on energy and resource use of computing, Green IT, simulation of ecological models such as climate models, desert spread and species loss, repairability, reuse and recycling, and students'' own use of digital devices.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 3", "courseLevel": "advanced", "topicTags": ["media_society", "modelling_simulation"]}', 'unit-records-195'),
  ('1fa27acd-58c3-5aad-924c-f74260f219f7', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-wb4-informatik-und-oekologie', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-gk-wb4-informatik-und-oekologie', 31, 'Informatik und Ökologie', 'Computer science and ecology', NULL, 'An optional unit on the environmental side of computing: energy use of the internet, algorithms and hardware manufacture, resource consumption and planned obsolescence, and Green IT with sustainable use of devices.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 4", "courseLevel": "basic", "topicTags": ["media_society"]}', 'unit-records-195'),
  ('47f536dc-4b63-5358-bcb8-7c896b5d1512', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-wb4-mathematische-methoden', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-wb4-mathematische-methoden', 32, 'Mathematische Methoden in der Informatik', 'Mathematical methods in computer science', NULL, 'An optional unit on computers as tools in mathematics: numerical methods such as the Heron and Newton methods, interpolation and regression, limits of numerical accuracy, and automated theorem provers and the effect of AI on proofs.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 4", "courseLevel": "advanced", "topicTags": ["modelling_simulation", "other"]}', 'unit-records-195'),
  ('ae7e6f97-6931-5200-b3b4-dfec1e936369', 'saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-wb5-generative-kunst', '5f272106-6b20-5ec6-be05-d0e16455321f', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-SN-LP-INF-inf-lk-wb5-generative-kunst', 33, 'Generative Kunst', 'Generative art', NULL, 'An optional unit on generative art: development environments, geometric shapes, random parameters, recursion and fractals, AI methods, and questions of authorship for works made by humans and machines together.', NULL, 'https://www.schulportal.sachsen.de/lplandb/lehrplan/630', '{"unitNumber": "Wahlbereich 5", "courseLevel": "advanced", "topicTags": ["other", "media_society"]}', 'unit-records-195'),
  ('22a958fe-0c20-520b-aa70-694c2f5e800f', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr', NULL, 'edition', 'informatik', 'Gymnasium', NULL, NULL, NULL, 0, 'Informatik, Gymnasium · 2026 (Erprobungsfassung)', 'Computer science, Gymnasium · 2026 (trial edition)', NULL, NULL, NULL, NULL, '{"units": 25, "edition": "2026 (Erprobungsfassung, two separate Lehrplan PDFs)"}', 'unit-records-195'),
  ('0a3f5c7c-d8aa-50ee-bfbe-a41cbca41167', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6', '22a958fe-0c20-520b-aa70-694c2f5e800f', 'grade_band', 'informatik', 'Gymnasium', '5/6', NULL, NULL, 5, 'Klassenstufe 5/6', 'Grade 5/6', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('57c92599-0199-5432-b2e5-98fed325b446', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-medienalltag-reflektieren', '0a3f5c7c-d8aa-50ee-bfbe-a41cbca41167', 'unit', 'informatik', 'Gymnasium', '5/6', NULL, 'DE-TH-LP-INF-mbi-5-6-medienalltag-reflektieren', 0, 'Den Medienalltag reflektieren', 'Reflecting on everyday media use', NULL, 'Pupils describe the kinds of media they meet every day and what each is used for, document and reflect on their own usage and its motives, and weigh benefits and risks such as screen time and costs. They derive sensible rules for their own media use.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.1.1", "topicTags": ["media_society"]}', 'unit-records-195'),
  ('91911108-f1b8-5e68-b5a2-4914d1d1c2be', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-informatiksysteme', '0a3f5c7c-d8aa-50ee-bfbe-a41cbca41167', 'unit', 'informatik', 'Gymnasium', '5/6', NULL, 'DE-TH-LP-INF-mbi-5-6-informatiksysteme', 1, 'Informatiksysteme verstehen und kompetent nutzen', 'Understanding and competently using computer systems', NULL, 'Pupils identify computer systems around them and describe hardware, software and networks and how they work together, using the EVAS principle. They find their way around user interfaces, manage files and folders and use web-based learning platforms.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.1.2", "topicTags": ["systems_networks"]}', 'unit-records-195'),
  ('df72e4ce-7772-5cc6-ac27-d97bb3d9140e', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-suchen-recherchieren-i', '0a3f5c7c-d8aa-50ee-bfbe-a41cbca41167', 'unit', 'informatik', 'Gymnasium', '5/6', NULL, 'DE-TH-LP-INF-mbi-5-6-suchen-recherchieren-i', 2, 'Informationen suchen, recherchieren und bewerten I', 'Searching, researching and evaluating information I', NULL, 'Pupils learn how search environments work, for example indexing and ranking, compare them, and use search operators and filters. They judge results for relevance and reliability, give sources correctly and consider what intentions lie behind media offers.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.1.3", "topicTags": ["information_data", "media_society"]}', 'unit-records-195'),
  ('535fae04-efb8-5761-b35d-6de6fb907376', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-texte-strukturieren-i', '0a3f5c7c-d8aa-50ee-bfbe-a41cbca41167', 'unit', 'informatik', 'Gymnasium', '5/6', NULL, 'DE-TH-LP-INF-mbi-5-6-texte-strukturieren-i', 3, 'Texte strukturieren und gestalten I', 'Structuring and designing texts I', NULL, 'Pupils use the basic functions of a word processor to produce clear, well-formatted documents with styles and proofing tools. They treat text elements as objects with properties, follow citation rules, and revise their own and shared texts.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.1.4", "topicTags": ["other"]}', 'unit-records-195'),
  ('7b7d1fe3-21cd-5913-a677-8b13140e0785', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-bilder-bearbeiten', '0a3f5c7c-d8aa-50ee-bfbe-a41cbca41167', 'unit', 'informatik', 'Gymnasium', '5/6', NULL, 'DE-TH-LP-INF-mbi-5-6-bilder-bearbeiten', 4, 'Bilder bearbeiten', 'Editing images', NULL, 'Pupils learn how raster images are stored as binary data with the RGB colour model, and how resolution and colour depth affect storage needs. They convert between images and bit sequences, edit images with tools and discuss how hard manipulated images are to spot.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.1.5", "topicTags": ["information_data"]}', 'unit-records-195'),
  ('4ad179c1-85b7-52af-9fae-a9c69590034f', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-praesentationen-gestalten', '0a3f5c7c-d8aa-50ee-bfbe-a41cbca41167', 'unit', 'informatik', 'Gymnasium', '5/6', NULL, 'DE-TH-LP-INF-mbi-5-6-praesentationen-gestalten', 5, 'Digitale Präsentationen visuell gestalten', 'Designing digital presentations visually', NULL, 'Pupils design digital presentations with meaningful images, short text and a consistent layout for a given audience. They respect copyright, cite sources, export and share the result, and assess presentations against given criteria.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.1.6", "topicTags": ["other"]}', 'unit-records-195'),
  ('cfed6542-5966-5756-b0d1-fcad31b07341', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-kommunizieren', '0a3f5c7c-d8aa-50ee-bfbe-a41cbca41167', 'unit', 'informatik', 'Gymnasium', '5/6', NULL, 'DE-TH-LP-INF-mbi-5-6-kommunizieren', 6, 'In digitalen Medienumgebungen handeln I: Kommunizieren', 'Acting in digital media environments I: communicating', NULL, 'Pupils compare digital and face-to-face communication, name risks such as cyberbullying and cybergrooming, and learn basic data protection for communication tools. They apply privacy settings, reflect on their own behaviour and agree rules for respectful online exchange.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.1.7", "topicTags": ["media_society"]}', 'unit-records-195'),
  ('a5cc610e-6ff9-583e-8349-308024a6b683', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-algorithmische-grundkonzepte', '0a3f5c7c-d8aa-50ee-bfbe-a41cbca41167', 'unit', 'informatik', 'Gymnasium', '5/6', NULL, 'DE-TH-LP-INF-mbi-5-6-algorithmische-grundkonzepte', 7, 'Mit algorithmischen Grundkonzepten kreativ gestalten', 'Creative work with basic algorithmic concepts', NULL, 'Pupils describe algorithms from everyday life and use basic building blocks such as sequences and loops in a graphical programming environment. They build and test simple programs in pairs, analyse errors and present their own project ideas.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.1.8", "topicTags": ["algorithms_programming"]}', 'unit-records-195'),
  ('a6f37e13-1277-53cf-88f6-a34637fc9033', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/7-8', '22a958fe-0c20-520b-aa70-694c2f5e800f', 'grade_band', 'informatik', 'Gymnasium', '7/8', NULL, NULL, 7, 'Klassenstufe 7/8', 'Grade 7/8', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('2887c9f9-5c36-5b68-aecd-7c0ab509892f', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/7-8/de-th-lp-inf-mbi-7-8-tabellenkalkulation', 'a6f37e13-1277-53cf-88f6-a34637fc9033', 'unit', 'informatik', 'Gymnasium', '7/8', NULL, 'DE-TH-LP-INF-mbi-7-8-tabellenkalkulation', 0, 'Daten tabellarisch strukturieren, auswerten und darstellen I: Tabellenkalkulation', 'Structuring, analysing and presenting data in tables I: spreadsheets', NULL, 'Pupils record everyday data in suitable data types, use cell addressing and basic functions, and build spreadsheet models for everyday problems. They choose and justify charts and discuss how data can be manipulated.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.2.1", "topicTags": ["information_data", "modelling_simulation"]}', 'unit-records-195'),
  ('3a53a511-9ee8-53ce-900e-b92ccbc5efb5', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/7-8/de-th-lp-inf-mbi-7-8-digitale-inhalte-veroeffentlichen', 'a6f37e13-1277-53cf-88f6-a34637fc9033', 'unit', 'informatik', 'Gymnasium', '7/8', NULL, 'DE-TH-LP-INF-mbi-7-8-digitale-inhalte-veroeffentlichen', 1, 'Digitale Inhalte erstellen und sich mit deren Veröffentlichung kritisch auseinandersetzen', 'Creating digital content and critically engaging with its publication', NULL, 'Pupils plan and produce a digital media product such as a podcast or video and explain technical aspects like file formats and compression. They discuss copyright, privacy and the ethical effects of publishing content for different audiences.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.2.2", "topicTags": ["media_society", "information_data"]}', 'unit-records-195'),
  ('c0c2eda0-2e7b-524a-b668-d6365f80fbe4', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/7-8/de-th-lp-inf-mbi-7-8-social-media', 'a6f37e13-1277-53cf-88f6-a34637fc9033', 'unit', 'informatik', 'Gymnasium', '7/8', NULL, 'DE-TH-LP-INF-mbi-7-8-social-media', 2, 'In digitalen Medienumgebungen handeln II: Social Media', 'Acting in digital media environments II: social media', NULL, 'Pupils describe how social media work, for example user-generated content and algorithmic steering, and weigh opportunities and risks. They explain data-driven business models and the role of influencers, and reflect on their own online profiles and privacy.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.2.3", "topicTags": ["media_society"]}', 'unit-records-195'),
  ('978af102-b457-5ee3-95ea-005ecdac9162', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/7-8/de-th-lp-inf-mbi-7-8-suchen-recherchieren-ii-ki', 'a6f37e13-1277-53cf-88f6-a34637fc9033', 'unit', 'informatik', 'Gymnasium', '7/8', NULL, 'DE-TH-LP-INF-mbi-7-8-suchen-recherchieren-ii-ki', 3, 'Informationen suchen, recherchieren und bewerten II: Vertiefung', 'Searching, researching and evaluating information II: deepening', NULL, 'Pupils explain how algorithms filter and personalise search results and why metadata and tracking matter. They describe how generative AI models such as large language models work and where they reach limits, check machine-made content for credibility, and reflect on bias.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.2.4", "topicTags": ["ai_ml", "media_society"]}', 'unit-records-195'),
  ('90829739-2517-519b-a4a0-89b99694e8ce', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/7-8/de-th-lp-inf-mbi-7-8-eingebettete-systeme', 'a6f37e13-1277-53cf-88f6-a34637fc9033', 'unit', 'informatik', 'Gymnasium', '7/8', NULL, 'DE-TH-LP-INF-mbi-7-8-eingebettete-systeme', 4, 'Eingebettete Systeme/Physical Computing gestalten', 'Designing embedded systems and physical computing', NULL, 'Pupils learn how sensors capture data and actuators act on the environment, and configure and program a microcontroller or robot for a task. They break problems into parts, test and debug their solutions, plan team projects and discuss automation in smart homes and industry.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.2.5", "topicTags": ["systems_networks", "algorithms_programming"]}', 'unit-records-195'),
  ('87021a9e-30ad-5d7b-8434-b7692444c297', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/7-8/de-th-lp-inf-mbi-7-8-datenbanken', 'a6f37e13-1277-53cf-88f6-a34637fc9033', 'unit', 'informatik', 'Gymnasium', '7/8', NULL, 'DE-TH-LP-INF-mbi-7-8-datenbanken', 5, 'Daten strukturieren, auswerten und darstellen II: Datenbanken', 'Structuring, analysing and presenting data II: databases', NULL, 'Pupils design an entity-relationship data model for a situation such as a social network, implement it in a database system and run basic operations and queries. They link this to how platforms collect data and reflect on data protection and their own data traces.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.2.6", "topicTags": ["information_data", "modelling_simulation"]}', 'unit-records-195'),
  ('4fb24927-273a-5896-beb4-f0f794769723', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/9', '22a958fe-0c20-520b-aa70-694c2f5e800f', 'grade_band', 'informatik', 'Gymnasium', '9', NULL, NULL, 9, 'Klassenstufe 9', 'Grade 9', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('47de8594-becc-523d-85e4-bf55489cc7b0', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/9/de-th-lp-inf-mbi-9-texte-strukturieren-ii', '4fb24927-273a-5896-beb4-f0f794769723', 'unit', 'informatik', 'Gymnasium', '9', NULL, 'DE-TH-LP-INF-mbi-9-texte-strukturieren-ii', 0, 'Texte strukturieren und gestalten II: komplexe Dokumente', 'Structuring and designing texts II: complex documents', NULL, 'Pupils build complex, multimedia documents with templates and styles, use automatic functions such as footnotes and tables of contents, and work on them jointly. They try AI-supported writing features and reflect on the effect on their own writing, copyright and resource use.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.3.1", "topicTags": ["other", "ai_ml"]}', 'unit-records-195')
) AS v(id, project_slug, node_key, parent_id, level, subject, school_type, grade_band, edition_source_id, record_source_id, sort_order, label_de, label_en, summary_de, summary_en, source_pages, source_url, facts, origin)
JOIN projects p ON p.slug = v.project_slug
ON CONFLICT (project_id, node_key) DO NOTHING;

INSERT INTO curriculum_repository_structure_nodes (id, project_id, node_key, parent_id, level, subject, school_type, grade_band, edition_record_id, record_id, sort_order, label_de, label_en, summary_de, summary_en, source_pages, source_url, facts, access_tier, review_status, origin)
SELECT v.id::uuid, p.id, v.node_key, v.parent_id::uuid, v.level, v.subject, v.school_type, v.grade_band,
       (SELECT r.id FROM curriculum_repository_records r WHERE r.project_id = p.id AND r.source_record_id = v.edition_source_id),
       (SELECT r.id FROM curriculum_repository_records r WHERE r.project_id = p.id AND r.source_record_id = v.record_source_id),
       v.sort_order::integer, v.label_de, v.label_en, v.summary_de, v.summary_en, v.source_pages, v.source_url, v.facts::jsonb,
       'summary-only', 'ai-draft', v.origin
FROM (VALUES
  ('52f94925-716e-54a2-91b8-8fa4b2bc0620', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/9/de-th-lp-inf-mbi-9-meinungsbildung-medienwelten', '4fb24927-273a-5896-beb4-f0f794769723', 'unit', 'informatik', 'Gymnasium', '9', NULL, 'DE-TH-LP-INF-mbi-9-meinungsbildung-medienwelten', 1, '(Meinungs-)Bildung in digitalen Medienwelten', 'Opinion formation and education in digital media worlds', NULL, 'Pupils examine how digital media shape opinion, including disinformation, filter bubbles created by personalisation and the influence of large platforms. They look at AI-made deepfakes, analyse political media formats and produce their own media product on a social topic.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.3.2", "topicTags": ["media_society", "ai_ml"]}', 'unit-records-195'),
  ('f622e1bd-08c0-5c9b-b406-4ec0fccb75ff', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/10', '22a958fe-0c20-520b-aa70-694c2f5e800f', 'grade_band', 'informatik', 'Gymnasium', '10', NULL, NULL, 10, 'Klassenstufe 10', 'Grade 10', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('81e8b4bf-6891-543c-a781-5fc21279d252', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/10/de-th-lp-inf-mbi-10-spielwelten', 'f622e1bd-08c0-5c9b-b406-4ec0fccb75ff', 'unit', 'informatik', 'Gymnasium', '10', NULL, 'DE-TH-LP-INF-mbi-10-spielwelten', 0, 'Digitale Spielwelten analysieren und gestalten', 'Analysing and designing digital game worlds', NULL, 'Pupils analyse digital games, mainly mobile games, as part of youth culture, including game principles, monetisation mechanisms such as loot boxes, and age ratings. They also model a simple game, implement it in a graphical programming environment and take a position on stereotypes.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.4.1", "topicTags": ["media_society", "algorithms_programming"]}', 'unit-records-195'),
  ('21b546bf-5f5d-57d4-994e-3f222304bef7', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/10/de-th-lp-inf-mbi-10-netzwerke-internet', 'f622e1bd-08c0-5c9b-b406-4ec0fccb75ff', 'unit', 'informatik', 'Gymnasium', '10', NULL, 'DE-TH-LP-INF-mbi-10-netzwerke-internet', 1, 'Netzwerke und Kommunikation im Internet verstehen und gestalten', 'Understanding and shaping networks and communication on the internet', NULL, 'Pupils explain how local and global networks are built and how data travels through them, including addressing and routing, the client-server model and name resolution. They model a simple network virtually and compare security measures such as firewalls.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.4.2", "topicTags": ["systems_networks"]}', 'unit-records-195'),
  ('eea82535-8517-567b-be03-7ebcf3be4354', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/10/de-th-lp-inf-mbi-10-grosse-datenmengen', 'f622e1bd-08c0-5c9b-b406-4ec0fccb75ff', 'unit', 'informatik', 'Gymnasium', '10', NULL, 'DE-TH-LP-INF-mbi-10-grosse-datenmengen', 2, 'Große Datenmengen automatisiert erfassen und auswerten', 'Automatically collecting and analysing large amounts of data', NULL, 'Pupils learn how large data sets are collected automatically, for example by sensors or tracking, and prepared for analysis. They write programs that store, analyse and visualise such data, and discuss how meaningful and how open to manipulation the results are.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf', '{"unitNumber": "2.4.3", "topicTags": ["information_data", "algorithms_programming"]}', 'unit-records-195'),
  ('15e3efcf-dba1-5045-a2aa-bcdd02cf87fb', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/11-12', '22a958fe-0c20-520b-aa70-694c2f5e800f', 'grade_band', 'informatik', 'Gymnasium', '11/12', NULL, NULL, 11, 'Klassenstufe 11/12', 'Grade 11/12', NULL, NULL, NULL, NULL, '{}', 'unit-records-195'),
  ('ee9b47ac-2e98-530a-966e-9b4f7cdf876c', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/11-12/de-th-lp-inf-inf-11-12-theoretische-informatik', '15e3efcf-dba1-5045-a2aa-bcdd02cf87fb', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-TH-LP-INF-inf-11-12-theoretische-informatik', 0, 'Lernbereich Theoretische Informatik', 'Learning area: theoretical computer science', NULL, 'Students compare natural and formal languages, derive words with grammars, and explain finite automata and the halting problem. The advanced level adds Turing machines, computability limits, complexity classes and O notation.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf', '{"unitNumber": "2.1", "topicTags": ["algorithms_programming"]}', 'unit-records-195'),
  ('6f627c34-1041-5e22-b8dc-8fabfe4cafde', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/11-12/de-th-lp-inf-inf-11-12-technische-informatik', '15e3efcf-dba1-5045-a2aa-bcdd02cf87fb', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-TH-LP-INF-inf-11-12-technische-informatik', 1, 'Lernbereich Technische Informatik', 'Learning area: technical computer science', NULL, 'Students explain the von Neumann architecture, binary coding and binary arithmetic, and logic gates with truth tables, including flip-flops and adders. The advanced level adds fractional numbers in bit patterns, adder circuits and analog-digital converters.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf', '{"unitNumber": "2.2", "topicTags": ["systems_networks", "information_data"]}', 'unit-records-195'),
  ('db78481b-4b94-5d0a-955c-67338361e309', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/11-12/de-th-lp-inf-inf-11-12-praktische-informatik', '15e3efcf-dba1-5045-a2aa-bcdd02cf87fb', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-TH-LP-INF-inf-11-12-praktische-informatik', 2, 'Lernbereich Praktische Informatik', 'Learning area: practical computer science', NULL, 'Students design, implement and compare iterative and recursive algorithms and model simple situations in an object-oriented way. They apply methods such as backtracking and divide and conquer. The advanced level adds dynamic data structures, graphs and polymorphism.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf', '{"unitNumber": "2.3", "topicTags": ["algorithms_programming", "modelling_simulation"]}', 'unit-records-195'),
  ('1358a7a5-44ed-572e-8301-f69179da5115', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/11-12/de-th-lp-inf-inf-11-12-netzwerke-it-sicherheit', '15e3efcf-dba1-5045-a2aa-bcdd02cf87fb', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-TH-LP-INF-inf-11-12-netzwerke-it-sicherheit', 3, 'Netzwerke und IT-Sicherheit', 'Networks and IT security', NULL, 'Students describe how data moves through networks, including the client-server model, layers and routing, and explain compression and encryption and attacks on ciphers. They run a team project, implement a symmetric cipher and discuss data protection. The advanced level adds asymmetric encryption.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf', '{"unitNumber": "2.4.1", "topicTags": ["systems_networks"]}', 'unit-records-195'),
  ('31fae606-3d9f-57d5-a6c2-bc9b7d9c2851', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/11-12/de-th-lp-inf-inf-11-12-wissensbasierte-systeme', '15e3efcf-dba1-5045-a2aa-bcdd02cf87fb', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-TH-LP-INF-inf-11-12-wissensbasierte-systeme', 4, 'Wissensbasierte Systeme', 'Knowledge-based systems', NULL, 'Students model a closed part of the world as facts and rules, implement it in a suitable system and query it. They describe a knowledge-based system as database, rules and inference engine, including depth-first search and backtracking, and judge its limits and the idea of weak AI.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf', '{"unitNumber": "2.4.2", "courseLevel": "advanced", "topicTags": ["ai_ml", "modelling_simulation"]}', 'unit-records-195'),
  ('1d7b31bf-cd35-5e6a-9181-afeb6157af8d', 'thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/11-12/de-th-lp-inf-inf-11-12-maschinelles-lernen', '15e3efcf-dba1-5045-a2aa-bcdd02cf87fb', 'unit', 'informatik', 'Gymnasium', '11/12', NULL, 'DE-TH-LP-INF-inf-11-12-maschinelles-lernen', 5, 'Maschinelles Lernen', 'Machine learning', NULL, 'Students describe basic ideas of AI such as pattern matching and machine learning, typical uses, and the role of AI in analysing big data. They use AI tools with care and discuss ethical and legal issues. The advanced level adds the main learning types, training data quality and training a model.', NULL, 'https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf', '{"unitNumber": "2.4.3", "topicTags": ["ai_ml", "information_data"]}', 'unit-records-195')
) AS v(id, project_slug, node_key, parent_id, level, subject, school_type, grade_band, edition_source_id, record_source_id, sort_order, label_de, label_en, summary_de, summary_en, source_pages, source_url, facts, origin)
JOIN projects p ON p.slug = v.project_slug
ON CONFLICT (project_id, node_key) DO NOTHING;

