JOIN curriculum_repository_structure_nodes n ON n.node_key = m.node_key AND n.project_id = (SELECT id FROM projects WHERE slug = 'thuringia-curriculum-repository')
JOIN lpm_data_objects o ON o.project_id IN (SELECT id FROM projects WHERE slug IN ('evomentor-thuringia', 'evomentor-thuringia-sandbox'))
  AND o.status = 'accepted' AND o.grade_band = m.band
  AND COALESCE(o.content ->> 'thema', '') = m.thema AND COALESCE(o.content ->> 'unterthema', '') = m.unterthema
ON CONFLICT DO NOTHING;

DO $$
DECLARE nodes integer; links integer;
BEGIN
  SELECT count(*) INTO nodes FROM curriculum_repository_structure_nodes;
  SELECT count(*) INTO links FROM curriculum_repository_node_goals n JOIN projects p ON p.id = n.project_id WHERE p.slug = 'evomentor-thuringia';
  IF nodes < 412 OR links < 320 THEN
    RAISE EXCEPTION 'migration 216: % structure nodes (expected 412), % goal links in EvoMentor Thueringen (expected about 356)', nodes, links;
  END IF;
END $$;
